var MASTER_EAU_B06 = {

  'MASTER-EAU-065': {
    id: 'MASTER-EAU-065',
    titre: 'Thermodynamique des systèmes aqueux',
    fiche: {
      intro: "La thermodynamique des solutions aqueuses est le fondement de la chimie des eaux naturelles. Elle prédit l'état d'équilibre des réactions géochimiques (dissolution, précipitation, oxydo-réduction) à partir des énergies libres de Gibbs. L'enthalpie de réaction, l'entropie et l'énergie de Gibbs permettent de calculer les constantes d'équilibre et leur variation avec la température, indispensables à la modélisation de la qualité des eaux.",
      sections: [
        { titre: "Énergie libre de Gibbs et équilibres chimiques", sous_sections: [
          { titre: "Relation ΔG et constante d'équilibre", contenu: "L'énergie libre de Gibbs G est la fonction thermodynamique qui prédit la spontanéité d'une réaction à pression et température constantes. ΔG = ΔH - TΔS. ΔG° = -RT ln K, où K = constante d'équilibre thermodynamique. ΔG < 0 : réaction spontanée (exergonique). ΔG > 0 : réaction non spontanée. ΔG = 0 : équilibre. L'indice de saturation (SI = log(IAP/K_sp)) prédit si une phase minérale précipite (SI > 0) ou se dissout (SI < 0). La relation ΔG = ΔG° + RT ln Q (Q = quotient réactionnel) permet de calculer l'énergie disponible pour les réactions microbiennes (métabolisme anaérobie)." },
          { titre: "Variation des constantes avec la température", contenu: "La constante d'équilibre varie avec la température selon l'équation de Van't Hoff : d(ln K)/dT = ΔH°/(RT²). Intégrée entre T₁ et T₂ : ln(K₂/K₁) = -ΔH°/R × (1/T₂ - 1/T₁). La solubilité du CO₂ dans l'eau diminue avec T (Henry : K_H(25°C) = 3,4×10⁻² mol/L/atm, K_H(10°C) = 5,3×10⁻² mol/L/atm). La solubilité de la calcite augmente quand T diminue (réaction exothermique : CaCO₃ + H₂O ⇌ Ca²⁺ + HCO₃⁻ + OH⁻, ΔH > 0). La variation de K avec T est essentielle pour la modélisation des eaux froides (karst, hautes altitudes)." }
        ]},
        { titre: "Activités et coefficients d'activité", sous_sections: [
          { titre: "Activité thermodynamique vs concentration", contenu: "L'activité thermodynamique a_i = γ_i × c_i/c°, où γ_i = coefficient d'activité, c° = 1 mol/L. Pour les solutions diluées (<10⁻³ M), γ ≈ 1 (comportement idéal). Dans les eaux naturelles (force ionique I = 0,001-0,05 M), γ < 1 : les ions interagissent entre eux. Dans les eaux très salines (mer, saumures), γ peut être > 1. Le coefficient d'activité est calculé par des modèles : Davies (I < 0,3 M), Debye-Hückel étendu (I < 0,1 M), Pitzer (I > 0,1 M pour les saumures). Les logiciels géochimiques (PHREEQC, MINTEQ) calculent automatiquement γ pour chaque ion." },
          { titre: "Modèles de Debye-Hückel et Davies", contenu: "L'équation de Debye-Hückel étendue : log γ = -A z² √I / (1 + Ba √I), où A = 0,509 (25°C), B = 0,329, a = paramètre de taille de l'ion, z = charge, I = force ionique. L'équation de Davies (simplifiée) : log γ = -A z² × (√I/(1+√I) - 0,3I). La force ionique I = 0,5 × Σ cᵢzᵢ². Exemple : eau de mer, I ≈ 0,7 M → γ(Ca²⁺) ≈ 0,25 (correction de 75%!). Pour I > 0,3 M, le modèle de Pitzer (interactions ion-ion) est nécessaire. PHREEQC utilise LLNL thermodynamic database (thermo.com.V8.R6.230) avec des constantes à 25°C et des corrections de température." }
        ]},
        { titre: "Thermochimie des réactions géochimiques", sous_sections: [
          { titre: "Enthalpie de réaction et loi de Hess", contenu: "L'enthalpie de réaction ΔH°r = Σ ΔH°f (produits) - Σ ΔH°f (réactifs), calculée à partir des enthalpies de formation standard. La loi de Hess permet de combiner les réactions. Exemples dans les eaux naturelles : dissolution de la pyrite FeS₂ + 7/2 O₂ + H₂O → Fe²⁺ + 2SO₄²⁻ + 2H⁺ (ΔH° = -1521 kJ/mol, très exothermique → drainage acide minier génère de la chaleur). Dissolution de la calcite CaCO₃ ⇌ Ca²⁺ + CO₃²⁻ (ΔH° = +13,1 kJ/mol, légèrement endothermique). Ces valeurs permettent de calculer la variation de K avec T (Van't Hoff)." },
          { titre: "Énergie de Gibbs des réactions microbiennes", contenu: "Le métabolisme anaérobie des bactéries exploite l'énergie des réactions géochimiques. ΔG de quelques réactions respiratoires anaérobies (kJ/mol CH₂O) : réduction des nitrates (dénitrification) ΔG = -481 kJ/mol, réduction des sulfates ΔG = -77 kJ/mol, méthanogenèse ΔG = -24 kJ/mol. L'ordre de succession des terminaux d'electron est donné par l'énergie disponible (séquence redox) : O₂ > NO₃⁻ > MnO₂ > Fe(OH)₃ > SO₄²⁻ > CO₂. Cette séquence est observée dans les profils de nappe phréatique contaminée (from aerobic to methanogenic). Le ΔG minimum requis par les bactéries est -20 kJ/mol (limite bioénergétique)." }
        ]},
        { titre: "Applications aux eaux naturelles et industrielles", sous_sections: [
          { titre: "Corrosion des conduites et eau corrosive", contenu: "L'indice de Langelier (IL = pH - pH_sat) évalue l'agressivité d'une eau vis-à-vis du carbonate de calcium. pH_sat = pK₂ - pK_sp + p[Ca²⁺] + p[ALK]. IL > 0 : eau entartrante (risque de dépôt de CaCO₃). IL < 0 : eau corrosive (risque de dissolution du CaCO₃ de protection, attaque du béton). IL = 0 : eau à l'équilibre. En distribution d'eau potable, l'objectif est IL ≈ 0 (eau ni corrosive, ni entartrante). Le conditionnement chaux-CO₂ (calcification) ajuste le pH pour atteindre l'équilibre calco-carbonique. L'indice de Ryznar (2 pH_sat - pH) est un critère complémentaire." },
          { titre: "Précipitation et coprécipitation en traitement des eaux", contenu: "La précipitation chimique (coagulation-floculation) est un processus de traitement des eaux fortement gouverné par la thermodynamique. La précipitation de l'hydroxyde de fer Fe(OH)₃ (coagulation par le sulfate ferreux) élimine les phosphates par adsorption et coprécipitation. La précipitation de la struvite (MgNH₄PO₄, ISS > 0) dans les digesteurs de boues est un problème opérationnel (colmatage des conduites) mais aussi une ressource (engrais). PHREEQC calcule les indices de saturation de toutes les phases minérales et prédit les précipitations en traitement des eaux (réacteurs, réseaux)." }
        ]}
      ],
      points: ["ΔG° = -RT ln K. ΔG < 0 → réaction spontanée.", "Van't Hoff : d(ln K)/dT = ΔH°/(RT²). CO₂ : solubilité↓ quand T↑.", "Force ionique I = 0,5 Σ cᵢzᵢ². Eau de mer : I ≈ 0,7 M.", "Debye-Hückel : log γ = -A z² √I / (1+Ba√I). Davies : I < 0,5 M.", "Indice de saturation SI = log(IAP/K_sp). SI > 0 → précipitation.", "Indice de Langelier IL = pH - pH_sat. IL < 0 → eau corrosive.", "Séquence redox : O₂ > NO₃⁻ > MnO₂ > Fe(OH)₃ > SO₄²⁻ > CO₂.", "PHREEQC : logiciel de spéciation géochimique (USGS, gratuit).", "Struvite (MgNH₄PO₄) : précipitation indésirable dans les digesteurs.", "Limite bioénergétique des bactéries : ΔG_min ≈ -20 kJ/mol."],
      formules: [
        { nom: "Énergie libre de Gibbs et constante d'équilibre", expression: "ΔG° = -RT ln K", variables: "R = 8,314 J/mol/K, T = température absolue (K), K = constante d'équilibre" },
        { nom: "Équation de Van't Hoff", expression: "ln(K₂/K₁) = -ΔH°/R × (1/T₂ - 1/T₁)", variables: "ΔH° = enthalpie de réaction (J/mol), T en K. Donne la variation de K avec T" },
        { nom: "Force ionique", expression: "I = 0,5 × Σ cᵢ × zᵢ²", variables: "cᵢ = concentration de l'ion i (mol/L), zᵢ = charge algébrique" },
        { nom: "Équation de Davies", expression: "log γᵢ = -A × zᵢ² × (√I/(1+√I) - 0,3I)", variables: "A = 0,509 à 25°C, zᵢ = charge de l'ion, I = force ionique. Valable pour I < 0,5 M" },
        { nom: "Indice de saturation (Langelier pour CaCO₃)", expression: "SI = log(IAP / K_sp) = pH - pH_sat", variables: "IAP = [Ca²⁺][CO₃²⁻], K_sp = 10⁻⁸·³ à 25°C. SI > 0 → sursaturation → précipitation" }
      ],
      retenir: "La thermodynamique des solutions aqueuses (ΔG, K, activités) est le socle de la géochimie des eaux. PHREEQC calcule la spéciation et les indices de saturation. L'équation de Van't Hoff prédit la variation de K avec T. Les coefficients d'activité (Debye-Hückel, Davies) sont indispensables pour les eaux chargées. L'indice de Langelier gère la corrosion et l'entartrage en distribution d'eau potable."
    },
    exercices: [
      { id: 1, enonce: "K_sp(CaCO₃) = 10⁻⁸·³ à 25°C et ΔH° = +13,1 kJ/mol. Calculez K_sp à 10°C.", correction: "ln(K₁₀/K₂₅) = -ΔH°/R × (1/T₁₀ - 1/T₂₅) = -13100/8,314 × (1/283 - 1/298) = -1575 × (3,534×10⁻³ - 3,356×10⁻³) = -1575 × 1,78×10⁻⁴ = -0,280. K₁₀ = K₂₅ × e^(-0,280) = 10⁻⁸·³ × 0,756 = 10⁻⁸·³ × 10⁻⁰·¹²¹ = 10⁻⁸·⁴²¹. La calcite est légèrement moins soluble à 10°C (CaCO₃ endothermique : solubilité ↑ avec T)." },
      { id: 2, enonce: "Eau de source : Ca²⁺ = 2,5 mmol/L, Mg²⁺ = 1,2 mmol/L, Na⁺ = 0,8 mmol/L, Cl⁻ = 1,0 mmol/L, SO₄²⁻ = 1,5 mmol/L, HCO₃⁻ = 4,2 mmol/L. Calculez I.", correction: "I = 0,5 × [2,5×4 + 1,2×4 + 0,8×1 + 1,0×1 + 1,5×4 + 4,2×1] = 0,5 × [10 + 4,8 + 0,8 + 1,0 + 6,0 + 4,2] = 0,5 × 26,8 = 13,4 mmol/L = 0,0134 M. Eau douce typique : I faible → γ ≈ 0,9-0,95 pour les ions divalents." },
      { id: 3, enonce: "Calculez γ(Ca²⁺) avec l'équation de Davies pour I = 0,05 M.", correction: "log γ(Ca²⁺) = -0,509 × 2² × (√0,05/(1+√0,05) - 0,3×0,05) = -2,036 × (0,2236/1,2236 - 0,015) = -2,036 × (0,1827 - 0,015) = -2,036 × 0,1677 = -0,341. γ(Ca²⁺) = 10⁻⁰·³⁴¹ = 0,456. La concentration active de Ca²⁺ est seulement 45,6% de la concentration analytique à I = 0,05 M." },
      { id: 4, enonce: "Eau de distribution : pH = 7,2, [Ca²⁺] = 1,8 mmol/L, alcalinité = 3,5 meq/L, T = 15°C. pH_sat = 7,8. Calculez IL et commentez.", correction: "IL = pH - pH_sat = 7,2 - 7,8 = -0,6. IL < 0 → eau corrosive. Elle a tendance à dissoudre le CaCO₃ de protection des conduites en béton ou en fonte revêtue de ciment. Risque de dissolution du calcaire des conduites, relargage de métaux (Pb, Cu depuis les soudures). Action corrective : augmenter le pH par ajout de chaux ou de NaOH, ou recarbonater pour atteindre pH_sat. Objectif : IL ≈ 0 à +0,2." },
      { id: 5, enonce: "La réduction du sulfate (ΔG = -77 kJ/mol CH₂O) et la méthanogenèse (ΔG = -24 kJ/mol CH₂O) se produisent dans une nappe contaminée. Dans quelle zone chacune prédomine-t-elle ?", correction: "Dans une zone redox stratifiée : la réduction des sulfates (ΔG = -77 kJ/mol, plus énergétique) prédomine tant que les sulfates sont disponibles. Les bactéries sulfato-réductrices (BSR) colonisent la zone où SO₄²⁻ > 0 et l'énergie est suffisante (ΔG < -20 kJ/mol). La méthanogenèse (ΔG = -24 kJ/mol, moins énergétique) se produit dans la zone la plus réduite, en aval-flux ou en profondeur, après épuisement des sulfates. Elle est proche de la limite bioénergétique (-24 kJ/mol ≈ -20 kJ/mol). Dans les décharges et les aquifères très contaminés, les deux processus peuvent coexister spatialement." },
      { id: 6, enonce: "IAP(BaSO₄) = 10⁻⁹·⁸ dans une eau d'injection pétrolière. K_sp(BaSO₄) = 10⁻⁹·⁹⁷. Calculez SI. Y a-t-il risque de précipitation ?", correction: "SI = log(IAP/K_sp) = log(10⁻⁹·⁸ / 10⁻⁹·⁹⁷) = log(10⁰·¹⁷) = +0,17. SI > 0 → légère sursaturation en BaSO₄ (barytine). Risque de précipitation. Dans les puits pétroliers, la précipitation de barytine (scale formation) est un problème opérationnel majeur : obstruction des tubages, pertes de production. Traitement préventif : inhibiteurs d'entartrage (phosphonates) ou déminéralisation de l'eau d'injection." },
      { id: 7, enonce: "Qu'est-ce que la struvite et pourquoi pose-t-elle problème dans les stations d'épuration ?", correction: "Struvite = MgNH₄PO₄·6H₂O, minéral phosphaté qui précipite spontanément quand le produit ionique [Mg²⁺][NH₄⁺][PO₄³⁻] > K_sp. Dans les digesteurs anaérobies (méthanisation des boues) : libération de NH₄⁺ et PO₄³⁻ en grandes quantités → sursaturation → dépôts de struvite dans les conduites de retour de digestat. Problèmes : colmatage des conduites, réduction de débit, coûts de nettoyage. Solution : précipitation contrôlée de struvite dans un réacteur dédié (valorisation comme engrais à libération lente, valeur commerciale 200-400 €/tonne). PHREEQC prédit l'IS de la struvite." },
      { id: 8, enonce: "Un aquifère karstique a T = 10°C (hiver) et T = 18°C (été). Prévoyez la dissolution ou précipitation de la calcite selon la saison.", correction: "Dissolution calcite endothermique (ΔH° > 0) → K_sp augmente avec T → calcite plus soluble à 18°C qu'à 10°C. En hiver (10°C) : K_sp plus faible → risque de précipitation de calcite (dépôts de travertin, spéléothèmes). En été (18°C) : K_sp plus élevé → dissolution favorisée. Mais la CO₂ dissous (Henry) diminue quand T↑ → effet inverse sur le pH. En pratique : c'est la teneur en CO₂ (pCO₂) qui domine dans les karsts. Pluies d'été → CO₂ élevé dans le sol → dissolution de calcite. Hiver → moins de CO₂ → précipitation." }
    ],
    flashcards: [
      { question: "ΔG, K et spontanéité : relations clés", reponse: "ΔG° = -RT ln K. ΔG = ΔG° + RT ln Q. ΔG < 0 : spontané. ΔG > 0 : non spontané. ΔG = 0 : équilibre (Q = K). R = 8,314 J/mol/K. À 25°C (298 K) : ΔG° = -5705 × log K (kJ/mol). Exemple : K_sp(CaCO₃) = 10⁻⁸·³ → ΔG°(dissolution) = +5705 × 8,3 = +47,4 kJ/mol → dissolution non spontanée (eau distillée pure — mais conditions naturelles changent tout)." },
      { question: "Équation de Van't Hoff : usage pratique", reponse: "ln(K₂/K₁) = -ΔH°/R × (1/T₂ - 1/T₁). ΔH° > 0 (endothermique) : K augmente avec T (solubilité↑ avec T). ΔH° < 0 (exothermique) : K diminue avec T. CO₂ dans l'eau (exothermique) : solubilité ↓ quand T ↑. Calcite (endothermique) : solubilité ↑ quand T ↑. Utilisé pour corriger les K des bases de données thermodynamiques (souvent données à 25°C) vers les températures de terrain." },
      { question: "Force ionique et coefficients d'activité", reponse: "I = 0,5 Σ cᵢzᵢ². Eau distillée : I ≈ 0. Eau douce typique : I ≈ 0,001-0,01 M. Eau de mer : I ≈ 0,7 M. γ < 1 pour I > 0 (ions interagissent → activité effective < concentration). Davies : pour I < 0,5 M. Pitzer : pour I > 0,5 M (saumures). PHREEQC calcule automatiquement γ et les activités pour chaque ion, à partir de la composition chimique mesurée." },
      { question: "Indice de Langelier : eau corrosive ou entartrante", reponse: "IL = pH - pH_sat. pH_sat = cote de saturation en CaCO₃ (calculée depuis [Ca²⁺], alcalinité, T, force ionique). IL < -0,5 : eau très corrosive (attaque les bétons, dissout la couche de CaCO₃ protectrice). IL = 0 : équilibre calco-carbonique. IL > +0,5 : eau entartrante (dépôts de calcaire). En distribution AEP : viser IL = 0 à +0,3. Corrigé par ajout de chaux (↑ pH, ↑ [Ca²⁺], ↑ IL) ou de CO₂ (↓ pH, ↓ IL)." },
      { question: "Séquence redox et ΔG", reponse: "Ordre décroissant d'énergie disponible par mol CH₂O oxydé : O₂ (-487 kJ/mol) > NO₃⁻ (-481) > MnO₂ (-349) > Fe(OH)₃ (-114) > SO₄²⁻ (-77) > CO₂ (méthanogenèse, -24). Cette séquence s'observe dans les profils verticaux des nappes contaminées (zonation redox) et dans les digesteurs anaérobies. Chaque réaction ne peut opérer que si ΔG < -20 kJ/mol (limite bioénergétique des bactéries)." },
      { question: "PHREEQC : fonctionnalités principales", reponse: "Logiciel USGS gratuit pour la spéciation géochimique et la modélisation réactive. Fonctions : calcul de la spéciation à partir d'une analyse chimique, calcul des IS pour toutes les phases minérales, titrage, mélange d'eaux, réaction avec des phases solides, transport réactif 1D. Bases de données : PHREEQC.DAT (générale), LLNL.DAT (étendue), MINTEQ.DAT. Standard mondial pour la géochimie des eaux souterraines, le traitement des eaux et les études de contamination." }
    ]
  },

  'MASTER-EAU-066': {
    id: 'MASTER-EAU-066',
    titre: 'Activités chimiques, force ionique et spéciation',
    fiche: {
      intro: "La spéciation chimique détermine la répartition d'un élément entre ses différentes formes chimiques en solution (ions libres, complexes, paires d'ions). Elle conditionne la réactivité, la biodisponibilité et la toxicité des contaminants. La spéciation des métaux lourds (Cu, Pb, Cd, Zn), des nutriments (N, P, C inorganique) et des métalloïdes (As, Se) est fondamentale pour l'évaluation de la qualité des eaux.",
      sections: [
        { titre: "Complexation et paires d'ions", sous_sections: [
          { titre: "Constantes de stabilité des complexes", contenu: "Un complexe est formé par la coordination d'un métal Mⁿ⁺ avec un ligand L : Mⁿ⁺ + L ⇌ ML, K₁ = [ML]/([M][L]). Les constantes de stabilité cumulées : β_n = K₁ × K₂ × ... × K_n. Les complexes OH⁻ (hydrolyse), CO₃²⁻, SO₄²⁻, Cl⁻, HCO₃⁻ sont les plus importants dans les eaux naturelles. Exemples : Fe³⁺ forme des complexes hydroxyl stables (FeOH²⁺, Fe(OH)₂⁺, Fe(OH)₃) → spéciation très différente de Fe³⁺ libre. CuCO₃ est la forme dominante du cuivre dans les eaux calcaires (pCO₂ = 10⁻³·⁵ atm). Les ligands organiques naturels (acides humiques, fulviques) complexent fortement les métaux (Cu²⁺, Pb²⁺)." },
          { titre: "Paires d'ions et association", contenu: "Les paires d'ions (ion pairs) sont des associations électrostatiques faibles (non covalentes) entre ions de signes opposés. CaSO₄°, MgCO₃°, NaSO₄⁻ sont des paires d'ions importantes dans les eaux sulfatées. Elles réduisent la charge nette des ions → réduction de γ. L'association des ions divalents avec les anions divalents peut représenter 20-50% des espèces dans les eaux chargées. PHREEQC calcule automatiquement les paires d'ions. Dans les eaux de mer, le calcium libre Ca²⁺ représente seulement ~90% du calcium total (10% sous forme de paires)." }
        ]},
        { titre: "Spéciation des nutriments", sous_sections: [
          { titre: "Spéciation de l'azote en solution", contenu: "L'azote inorganique dissous comprend : NH₄⁺/NH₃ (ammonium/ammoniac), NO₂⁻ (nitrite), NO₃⁻ (nitrate). La forme dominante dépend du pH et du potentiel redox. NH₃ (non ionisé) est 100-1000× plus toxique pour les poissons que NH₄⁺. L'équilibre NH₄⁺ ⇌ NH₃ + H⁺ (pKa = 9,25 à 25°C) est fortement température-dépendant. À pH 7,5, 25°C : NH₃/(NH₃+NH₄⁺) = 10^(7,5-9,25)/(1+10^(7,5-9,25)) = 1,7%. À pH 8,5 : 15%. La toxicité de l'ammoniac non ionisé est le critère de qualité des eaux piscicoles (NH₃ < 0,02 mg N/L)." },
          { titre: "Spéciation du phosphore et de l'acide phosphorique", contenu: "L'acide phosphorique H₃PO₄ est triprotique (pKa1 = 2,15, pKa2 = 7,20, pKa3 = 12,35). Dans les eaux naturelles (pH 6-9) : H₂PO₄⁻ et HPO₄²⁻ dominent. À pH = 7,20 : [H₂PO₄⁻] = [HPO₄²⁻] (moitié-moitié). Le phosphore inorganique dissous (SRP = Soluble Reactive Phosphorus) est mesuré par la méthode au molybdate bleu. La spéciation du phosphore conditionne sa biodisponibilité et sa rétention par les sédiments (adsorption sur Fe(OH)₃). Dans les lacs eutrophes, la désorption du phosphore des sédiments (P-release interne) se produit en conditions anoxiques quand Fe(OH)₃ se dissout." }
        ]},
        { titre: "Spéciation des métaux lourds", sous_sections: [
          { titre: "Spéciation du plomb et du cuivre dans les eaux naturelles", contenu: "Le plomb Pb²⁺ forme des complexes carbonatés (PbCO₃, PbHCO₃⁺) dominants dans les eaux calcaires (pH > 7). Pb²⁺ libre est très faible (<5% du Pb total dans les eaux dures). La spéciation du Pb conditionne la corrosivité de l'eau sur les canalisations en plomb (très importantes avant 1950 en Europe). Le cuivre Cu²⁺ est complexé par CO₃²⁻ et par les acides organiques (humique, fulvique). Dans les eaux douces (pH 6-7), Cu²⁺ libre peut représenter 20-40% du cuivre total → toxicité. Le cuivre libre est l'espèce biodisponible (critère environnemental : [Cu²⁺] libre < 5-10 μg/L)." },
          { titre: "Arsenic et spéciation des métalloïdes", contenu: "L'arsenic existe sous deux états d'oxydation principaux dans les eaux : As(V) = arséniate (H₂AsO₄⁻, HAsO₄²⁻, H₃AsO₄) et As(III) = arsénite (H₃AsO₃). Le pE (potentiel redox) et le pH contrôlent la spéciation. As(III) (arsénite) est 25-60× plus toxique que As(V) et moins retenu par les adsorbants. Dans les aquifères réducteurs (Bangladesh, Inde), la réduction de As(V) → As(III) et la dissolution des oxydes de fer (libération de l'As adsorbé) sont responsables de la crise de l'arsenic (> 100 millions de personnes exposées). La spéciation de l'As est mesurée par HPLC-ICP-MS." }
        ]},
        { titre: "Méthodes de spéciation et modélisation", sous_sections: [
          { titre: "Méthodes analytiques de spéciation", contenu: "La spéciation analytique mesure les formes chimiques individuelles. Méthodes pour les métaux : HPLC-ICP-MS (séparation chromatographique + détection par spectrométrie de masse à plasma inductif, ppb à ppt), dialyse et ultrafiltration (séparation par taille), voltammétrie (spéciation électrochimique de Cu, Pb, Zn). Pour l'azote : chromatographie ionique (NO₃⁻, NO₂⁻), Nessler ou OPA pour NH₄⁺. Les sondes multiparamètres mesurent en continu NH₄⁺, NO₃⁻, et Ptot par spectroscopie UV. La comparaison entre la spéciation mesurée et calculée (PHREEQC) est une validation essentielle." },
          { titre: "Modélisation géochimique et codes de spéciation", contenu: "Les codes de spéciation (PHREEQC, MINTEQ, WATEQ4F, Geochemist's Workbench) calculent la répartition des espèces chimiques à l'équilibre à partir d'une analyse chimique. L'entrée : pH, T, composition chimique (concentrations totales des éléments). La sortie : concentrations et activités de chaque espèce, indices de saturation de tous les minéraux. PHREEQC résout un système d'équations non-linéaires (lois de masse + conservation de la charge). La base de données MINTEQ.V4 contient 2000+ espèces et 400+ minéraux. La modélisation géochimique est indispensable pour les études de contamination des eaux souterraines, le traitement des eaux et la décharge de déchets." }
        ]}
      ],
      points: ["Complexe ML : K₁ = [ML]/([M][L]). β_n = K₁ × ... × K_n.", "NH₃ (non ionisé) : toxique pour poissons, pKa = 9,25 (25°C).", "H₃PO₄ : pKa1 = 2,15, pKa2 = 7,20, pKa3 = 12,35.", "As(III) : 25-60× plus toxique et mobile que As(V) en conditions réductrices.", "Pb²⁺ libre < 5% dans eaux calcaires (carbonates complexent le Pb).", "HPLC-ICP-MS : mesure de la spéciation des métaux et métalloïdes.", "PHREEQC : spéciation à l'équilibre, IS minéraux, titrage, transport réactif.", "P-release : désorption interne du phosphore des sédiments en anoxie.", "Cu libre : critère toxicité = < 5-10 μg/L (forme biodisponible).", "Bangladesh arsenic crisis : As(III) libéré par dissolution FeOOH sous nappe."],
      formules: [
        { nom: "Fraction de NH₃ non ionisé", expression: "f(NH₃) = 1 / (1 + 10^(pKa - pH))", variables: "pKa(NH₄⁺/NH₃) = 9,25 à 25°C. f(NH₃) augmente avec pH et T" },
        { nom: "Fraction de HPO₄²⁻ (acide diprotique simplifié)", expression: "f(HPO₄²⁻) = 10^(pH-pKa2) / (1 + 10^(pH-pKa2) + 10^(pKa3-pH))", variables: "pKa2 = 7,20, pKa3 = 12,35 pour H₃PO₄. Valable à pH 5-12" },
        { nom: "Constante de stabilité du complexe", expression: "K = [ML] / ([M] × [L])", variables: "M = métal (activité), L = ligand (activité), ML = complexe. K en unités de (mol/L)⁻¹" },
        { nom: "Fraction d'espèce libre αM", expression: "αM = [M] / [M_tot] = 1 / (1 + Σ βᵢ [L]ⁱ)", variables: "βᵢ = constante de stabilité cumulée du complexe MLᵢ. αM ≤ 1" },
        { nom: "Équilibre de complexation carbone inorganique - calcium", expression: "CaCO₃° : K = [CaCO₃°] / ([Ca²⁺][CO₃²⁻]) = 10^(3·2)", variables: "K = 1585. Paire d'ions neutre CaCO₃° non chargée, non précipitée" }
      ],
      retenir: "La spéciation détermine quelle fraction d'un élément est biodisponible, mobile ou toxique. NH₃ libre (pH, T dépendant) est le critère piscicole. Les carbonates complexent les métaux lourds (Pb, Cu). As(III) est libéré en conditions réductrices dans les aquifères alluviaux. PHREEQC calcule la spéciation à l'équilibre. La mesure analytique de spéciation (HPLC-ICP-MS) valide les modèles."
    },
    exercices: [
      { id: 1, enonce: "pH = 8,0, T = 20°C, NH₄_tot = 2 mg N/L. pKa(NH₄⁺/NH₃) = 9,30 à 20°C. Calculez [NH₃] en mg N/L.", correction: "f(NH₃) = 1/(1 + 10^(9,30-8,0)) = 1/(1 + 10^1,30) = 1/(1 + 19,95) = 0,0477. [NH₃] = 2 × 0,0477 = 0,0953 mg N/L. Critère toxicité poissons : NH₃ < 0,02 mg N/L → cette eau est légèrement toxique (0,095 >> 0,02)." },
      { id: 2, enonce: "pH = 7,2, Ptot = 0,5 mg P/L (tout sous forme H₂PO₄⁻/HPO₄²⁻). Calculez [HPO₄²⁻] en mg P/L.", correction: "pKa2 = 7,20. f(HPO₄²⁻) = 10^(pH-pKa2)/(1 + 10^(pH-pKa2)) = 10^(7,2-7,2)/(1 + 10^0) = 1/(1+1) = 0,5. [HPO₄²⁻] = 0,5 × 0,5 = 0,25 mg P/L. À pH = pKa2, les deux formes sont équiprésentes : [H₂PO₄⁻] = [HPO₄²⁻] = 0,25 mg P/L." },
      { id: 3, enonce: "Expliquez pourquoi le cuivre libre Cu²⁺ est utilisé comme critère de toxicité plutôt que le cuivre total.", correction: "Le cuivre total inclut toutes les formes : Cu²⁺ libre (biodisponible, toxique), complexes carbonatés CuCO₃ (peu biodisponibles), complexes organiques Cu-fulvate/humate (non toxiques), et phases colloïdales (non disponibles). Seul Cu²⁺ libre traverse les membranes biologiques des branchies des poissons → c'est lui qui interagit avec les enzymes. Dans les eaux riches en matières organiques (tourbières), le cuivre total peut être élevé (1 mg/L) mais Cu²⁺ libre très faible → peu toxique. Dans les eaux claires oligotrophes, même 50 μg/L de Cu total peut être très toxique car Cu²⁺ libre représente une grande fraction." },
      { id: 4, enonce: "Pourquoi l'arsénite As(III) est-il plus mobile que l'arséniate As(V) dans les aquifères ?", correction: "As(V) = H₂AsO₄⁻, HAsO₄²⁻ : forte adsorption sur les oxydes de fer amorphes (Fe(OH)₃, FeOOH) → retenu dans le sol et les sédiments. As(III) = H₃AsO₃ (acide faible neutre à pH naturel) : beaucoup moins adsorbé sur les oxydes de fer (charge nulle à pH 6-9) → mobile dans la solution. De plus, en conditions réductrices (nappe profonde, aquifères deltaïques), les oxydes de fer se dissolvent (Fe(OH)₃ → Fe²⁺) et libèrent l'As adsorbé sous forme As(III). Double mécanisme de mobilisation : réduction As(V)→As(III) + dissolution Fe(OH)₃. Résultat : [As] >> 10 μg/L (norme OMS) dans les aquifères réducteurs d'Asie du Sud." },
      { id: 5, enonce: "Citez 3 complexes importants du plomb dans les eaux calcaires alcalines.", correction: "1. PbCO₃° (paire d'ions carbonate) : dominant à pH 7-9 dans les eaux calcaires, réduction de la toxicité. 2. PbHCO₃⁺ : complexe avec le bicarbonate, stable à pH 6-8. 3. PbOH⁺ (hydrolyse) : important à pH > 7, réduction du Pb²⁺ libre. Dans les eaux dures calcaires, Pb²⁺ libre représente < 5% du plomb total → corrosion des canalisations en plomb beaucoup moindre qu'en eau douce acide. L'eau de pluie (acide, faible alcalinité) est la plus corrosive pour les canalisations en plomb (Pb²⁺ libre > 50%)." },
      { id: 6, enonce: "PHREEQC donne SI(calcite) = -0,3 pour une eau. Interprétez et décrivez l'évolution de l'eau si elle entre en contact avec de la calcite.", correction: "SI = -0,3 → eau sous-saturée en calcite (IAP < K_sp). Cette eau va dissoudre la calcite : CaCO₃ + CO₂ + H₂O → Ca²⁺ + 2HCO₃⁻. La dissolution augmente [Ca²⁺], [HCO₃⁻] et le pH jusqu'à l'équilibre (SI = 0). L'eau devient plus dure (TH ↑) et l'alcalinité augmente. Ce processus est à la base de la chimie des eaux karstiques : les pluies acides (SI calcite ≈ -1 à -3) dissolvent progressivement les roches calcaires. Vitesse de dissolution : rapide pour les calcaires fins (quelques heures dans un réacteur) à lente pour les marbres (années)." },
      { id: 7, enonce: "Qu'est-ce que la crise de l'arsenic au Bangladesh et quel processus géochimique l'explique ?", correction: "Au Bangladesh et dans le delta du Gange, > 50 millions de personnes consomment de l'eau de puits artisanaux contenant > 50 μg/L d'As (norme OMS = 10 μg/L). Origine géochimique : 1. Alluvions jeunes riches en oxydes de fer (FeOOH) adsorbant l'As(V) naturellement présent. 2. Conditions réductrices dans la nappe (matière organique > 10 mg C/L) → fermentation bactérienne → consommation de l'O₂ → réduction des nitrates puis des oxydes de fer. 3. Dissolution de Fe(OH)₃ → libération de As(V) → réduction As(V)→As(III). 4. As(III) non adsorbé → mobilité dans la nappe. L'extraction intensive d'eaux souterraines amplifie le phénomène." },
      { id: 8, enonce: "Dans un lac eutrophe, le fond est anoxique en été. Prévoyez la spéciation du phosphore dans les sédiments vs la colonne d'eau.", correction: "Colonne d'eau oxique : phosphore retenu dans les sédiments sous forme HPO₄²⁻/H₂PO₄⁻ adsorbé sur Fe(OH)₃ → [P] dissous faible en surface. Fond anoxique (été) : réduction microbienne de Fe(OH)₃ → Fe²⁺ soluble + libération du P adsorbé → augmentation de [PO₄³⁻] dans les eaux interstitielles. Gradient de concentration → diffusion du P vers la colonne d'eau → 'P-release interne'. Flux de P depuis les sédiments peut alimenter les algues en surface même sans apport externe. Ce mécanisme explique pourquoi la réduction des apports externes seule est insuffisante pour restaurer rapidement un lac eutrophe (inertie des stocks sédimentaires)." }
    ],
    flashcards: [
      { question: "Spéciation du phosphore : formes selon le pH", reponse: "H₃PO₄ (pKa1=2,15) → H₂PO₄⁻ (pKa2=7,20) → HPO₄²⁻ (pKa3=12,35) → PO₄³⁻. pH 4-7 : H₂PO₄⁻ domine. pH 7-11 : HPO₄²⁻ domine. pH 7,2 : moitié H₂PO₄⁻, moitié HPO₄²⁻. Les eaux naturelles (pH 6-9) contiennent principalement H₂PO₄⁻ et HPO₄²⁻. PO₄³⁻ libre n'existe qu'à pH > 12 (pratiquement inexistant dans les eaux naturelles)." },
      { question: "NH₃ libre et toxicité piscicole", reponse: "pKa(NH₄⁺/NH₃) = 9,25 (25°C). f(NH₃) = 1/(1+10^(pKa-pH)). Augmente fortement avec pH et T. Critère qualité eau piscicole : NH₃ < 0,02 mg N/L (truite). À pH 7, 20°C : f(NH₃) ≈ 0,3% → NH₄_tot = 7 mg N/L atteint le seuil. À pH 8, 20°C : f(NH₃) ≈ 2,8% → NH₄_tot = 0,7 mg N/L suffit pour être toxique. Eau chaude + pH élevé (algues en été) = condition de toxicité maximale." },
      { question: "Arsenic : As(III) vs As(V)", reponse: "As(V) = arséniate = H₂AsO₄⁻, HAsO₄²⁻ à pH naturel. Adsorbé sur FeOOH. As(III) = arsénite = H₃AsO₃ (neutre à pH 6-9). Faiblement adsorbé → mobile. 25-60× plus toxique que As(V). En conditions oxiques : As(V) domine. En conditions réductrices : As(III) domine. Standard OMS = 10 μg/L (toutes formes). Problème majeur en Asie du Sud (Bangladesh, Bengale occidental), Chili, Mongolie." },
      { question: "PHREEQC : fonctionnement et usage", reponse: "Entrée : analyse chimique complète (pH, T, composition en éléments). Résolution du système d'équations de masse et de charge. Sortie : concentrations de toutes les espèces, activités, indices de saturation SI. Base de données : phreeqc.dat, llnl.dat, minteq.dat. Usages : spéciation des eaux naturelles, évaluation de la précipitation/dissolution minérale, simulation de mélanges d'eaux, titrage, transport réactif 1D. Gratuit (USGS). Interface graphique : PhreeqcI." },
      { question: "Complexation des métaux lourds par les carbonates", reponse: "Dans les eaux calcaires (alcalinité > 2 meq/L, pH > 7), les carbonates forment des complexes avec les métaux lourds divalents. Exemples : CuCO₃° (dominant dans les eaux calcaires), PbCO₃° et PbHCO₃⁺ (réduisent Pb²⁺ libre), ZnCO₃° (10-30% du Zn total). La complexation réduit la fraction libre et donc la toxicité et la mobilité. C'est pourquoi les PNEC (concentrations sans effet) pour les métaux sont plus élevées dans les eaux dures que dans les eaux douces." }
    ]
  },

  'MASTER-EAU-067': {
    id: 'MASTER-EAU-067',
    titre: 'Équilibres acido-basiques et système carbonaté',
    fiche: {
      intro: "Le système carbonaté (CO₂-H₂CO₃-HCO₃⁻-CO₃²⁻) est le principal système tampon des eaux naturelles, contrôlant le pH de la quasi-totalité des rivières, lacs et aquifères. Sa maîtrise est fondamentale pour comprendre la corrosion des conduites, l'eutrophisation, le drainage acide minier, la carbonatation de l'eau de mer et le cycle biologique du carbone.",
      sections: [
        { titre: "Le système tampon carbonate", sous_sections: [
          { titre: "Équilibres acido-basiques du CO₂ dissous", contenu: "Le CO₂ dissous dans l'eau donne naissance à plusieurs espèces : CO₂(aq) ⇌ H₂CO₃* (H₂CO₃* = CO₂ dissous + acide carbonique, les deux n'étant pas distingués analytiquement). H₂CO₃* ⇌ H⁺ + HCO₃⁻ : Ka1 = 10⁻⁶·³⁵ à 25°C (pKa1 = 6,35). HCO₃⁻ ⇌ H⁺ + CO₃²⁻ : Ka2 = 10⁻¹⁰·³³ à 25°C (pKa2 = 10,33). La loi de Henry : [CO₂] = K_H × pCO₂ (K_H = 3,4×10⁻² mol/L/atm à 25°C). Dans l'atmosphère, pCO₂ = 10⁻³·⁵ atm → [CO₂]_atm = 1,2×10⁻⁵ mol/L. Les eaux souterraines (CO₂ biogénique du sol) ont pCO₂ = 10⁻²·⁵ à 10⁻¹·⁵ atm → fortement chargées en CO₂." },
          { titre: "Alcalinité et capacité tampon", contenu: "L'alcalinité totale AT = [HCO₃⁻] + 2[CO₃²⁻] + [OH⁻] - [H⁺] = Σ bases protonables. Mesurée par titrage acide fort jusqu'à pH ≈ 4,5 (point de Méthyl Orange). Dans les eaux naturelles (pH 6-9), AT ≈ [HCO₃⁻] (HCO₃⁻ est l'espèce dominante). La capacité tampon β = dAT/dpH = 2,303 × ([H⁺] + Ka1[H₂CO₃*] + 4Ka2[HCO₃⁻] + [OH⁻]). La capacité tampon maximale est aux pH proches des pKa (6,35 et 10,33). Entre les deux pKa (pH 6-10), l'alcalinité bicarbonate assure le tampon. Les eaux pauvres en bicarbonate (< 1 meq/L, granites) sont peu tamponnées et très sensibles aux pluies acides." }
        ]},
        { titre: "Diagramme de Bjerrum et domaines de dominance", sous_sections: [
          { titre: "Construction et lecture du diagramme de Bjerrum", contenu: "Le diagramme de Bjerrum représente les concentrations des espèces carbonatées en fonction du pH, à CT constant (CT = carbone inorganique total = [CO₂] + [HCO₃⁻] + [CO₃²⁻]). Points caractéristiques : pH = pKa1 = 6,35 → [CO₂] = [HCO₃⁻]. pH = pKa2 = 10,33 → [HCO₃⁻] = [CO₃²⁻]. pH < 6,35 : CO₂ domine. 6,35 < pH < 10,33 : HCO₃⁻ domine. pH > 10,33 : CO₃²⁻ domine. Dans les eaux naturelles (pH 6-9), HCO₃⁻ est l'espèce omniprésente. Le diagramme de Bjerrum est l'outil de base pour comprendre les titrages acido-basiques des eaux et pour le dimensionnement des systèmes de pH ajustement." },
          { titre: "Effet du CO₂ dissous sur le pH", contenu: "Dans un système ouvert (en contact avec l'atmosphère), pCO₂ est fixé et CT varie avec le pH. Dans un système fermé, CT est fixe et pCO₂ change. Les eaux souterraines sont en système fermé (pas d'échange avec l'atmosphère) : leur pH et leurs espèces carbonatées évoluent selon les réactions géochimiques. À la résurgence (eau exposée à l'air), le dégazage du CO₂ excédentaire augmente le pH et peut précipiter CaCO₃ (tuf calcaire, travertin, spéléothèmes). Exemple : eau karstique (pH 7,0, pCO₂ = 10⁻²·⁵ atm) dégazée à pCO₂_atm = 10⁻³·⁵ → pH monte à 8,3 → SI(calcite) > 0 → précipitation de tuf." }
        ]},
        { titre: "Drainage acide minier (DAM)", sous_sections: [
          { titre: "Formation du drainage acide : oxydation de la pyrite", contenu: "Le drainage acide minier (DAM, AMD en anglais) résulte de l'oxydation de la pyrite (FeS₂) exposée à l'air et à l'eau lors des opérations minières. Réaction principale : FeS₂ + 7/2 O₂ + H₂O → Fe²⁺ + 2SO₄²⁻ + 2H⁺. Cette réaction est chimiquement lente mais biologiquement accélérée (Acidithiobacillus thiooxidans, Acidithiobacillus ferrooxidans) × 10⁵ à 10⁶. Fe²⁺ oxydé en Fe³⁺ (catalyseur supplémentaire). Le pH peut descendre à 1-3 dans les lixiviats miniers. L'acidité consomme le pouvoir tampon carbonaté en quelques mois. Le DAM génère des concentrations élevées de métaux (Zn, Pb, Cu, Cd, As) dissous dans les lixiviats acides." },
          { titre: "Traitement du DAM et neutralisation", contenu: "Le traitement du DAM utilise la neutralisation par la chaux (Ca(OH)₂) ou la cendre de chaux (CaO) : Ca(OH)₂ + H₂SO₄ → CaSO₄ + 2H₂O. La neutralisation précipite les métaux sous forme d'hydroxydes (Fe(OH)₃, Zn(OH)₂) et de sulfates (gypse). Le pH est ajusté à 8-9 pour précipiter tous les métaux. Les boues générées (riche en Fe(OH)₃) sont déshydratées et entreposées. Les zones humides construites (constructed wetlands) et les barrières réactives perméables (ZVI, calcaire) sont des traitements passifs. Le coût du traitement du DAM est un passif environnemental majeur des sites miniers (10-100 M€/site pour les grandes mines)." }
        ]},
        { titre: "Acidification des eaux et pluies acides", sous_sections: [
          { titre: "Pluies acides et acidification des lacs", contenu: "Les précipitations sont naturellement légèrement acides (pH ≈ 5,6, CO₂ atmosphérique). Les pluies acides (pH < 5,0) résultent des émissions de SO₂ et NOₓ (combustions, transports) : SO₂ + H₂O → H₂SO₃ → H₂SO₄. L'acidification des lacs sur roches granitiques (Scandinavie, Vosges, Canada) : pH < 5 → élimination des poissons, perte de biodiversité. L'alcalinité de l'eau (HCO₃⁻) est la première ligne de défense. La capacité de neutralisation des acides (CNA = alcalinité du bassin versant en eq/an) diminue avec l'acidification. Depuis les années 1990, la réduction des émissions de SO₂ (-80%) a permis une récupération partielle des lacs acidifiés (rerétauration)." },
          { titre: "Acidification des océans et cycle du carbone", contenu: "L'absorption de CO₂ anthropique par les océans (25% du CO₂ émis) diminue le pH marin : pH moyen de surface est passé de 8,2 à 8,1 depuis le début de l'ère industrielle (-0,1 unité = réduction de 26% de [H⁺]). Cette acidification : réduit la saturation en aragonite et calcite (coquilles des organismes marins), limite la calcification des coraux et pteropodes, modifie la spéciation des nutriments (CO₃²⁻ → HCO₃⁻). À horizon 2100 (SSP5-8.5) : pH marin pourrait descendre à 7,8 (-0,4 unité). La zone de dissolution des carbonates (lysocline) remonte vers la surface → dissolution des sédiments carbonatés." }
        ]}
      ],
      points: ["pKa1(H₂CO₃*/HCO₃⁻) = 6,35. pKa2(HCO₃⁻/CO₃²⁻) = 10,33 (25°C).", "Alcalinité = [HCO₃⁻] + 2[CO₃²⁻] + [OH⁻] - [H⁺] ≈ [HCO₃⁻] à pH 6-9.", "Système ouvert : pCO₂ fixé, CT variable. Système fermé : CT fixé.", "Pyrite + O₂ + H₂O → Fe²⁺ + SO₄²⁻ + H⁺ (DAM, bactéries accélèrent ×10⁶).", "DAM : pH 1-3, métaux lourds très solubles. Neutralisation à la chaux.", "Pluies acides : pH < 5 → lac acidifié sur granites (HCO₃⁻ épuisé).", "Océan : absorption 25% CO₂ anthropique → pH 8,2 → 8,1 (-26% [H⁺]).", "K_H(CO₂, 25°C) = 3,4×10⁻² mol/L/atm. [CO₂] = K_H × pCO₂.", "Spéléothèmes (stalactites) : précipitation CaCO₃ après dégazage CO₂.", "Eaux granitiques : faible alcalinité → très sensibles aux pluies acides."],
      formules: [
        { nom: "Loi de Henry (CO₂ dissous)", expression: "[CO₂] = K_H × pCO₂", variables: "K_H = 3,4×10⁻² mol/L/atm (25°C), pCO₂ = pression partielle (atm)" },
        { nom: "Équilibre acido-basique H₂CO₃*", expression: "Ka1 = [H⁺][HCO₃⁻] / [CO₂] = 10⁻⁶·³⁵", variables: "pKa1 = 6,35 à 25°C. [CO₂] = [H₂CO₃*] = CO₂ dissous total" },
        { nom: "Alcalinité totale", expression: "AT = [HCO₃⁻] + 2[CO₃²⁻] + [OH⁻] - [H⁺]", variables: "En meq/L. Conservée lors du dégazage de CO₂ (contrairement au pH et à CT)" },
        { nom: "Oxydation de la pyrite (DAM)", expression: "FeS₂ + 7/2 O₂ + H₂O → Fe²⁺ + 2SO₄²⁻ + 2H⁺", variables: "ΔH° = -1521 kJ/mol (très exothermique). Catalysée par Acidithiobacillus ferrooxidans" },
        { nom: "pH eaux karstiques (système ouvert)", expression: "pH = (pKa1 - log K_H - log pCO₂) / 2 + f(alcalinité)", variables: "Simplifié : pH = 7,8 à pCO₂ = 10⁻³·⁵ atm, [CaCO₃] = équilibre" }
      ],
      retenir: "Le système carbonaté (CO₂/HCO₃⁻/CO₃²⁻, pKa 6,35 et 10,33) tamponne le pH des eaux naturelles. L'alcalinité bicarbonate est la mesure clé de la capacité tampon. Le DAM résulte de l'oxydation bactérienne de la pyrite → pH 1-3. Les pluies acides épuisent l'alcalinité des bassins granitiques. L'acidification des océans par absorption de CO₂ est un défi environnemental majeur."
    },
    exercices: [
      { id: 1, enonce: "pCO₂ = 10⁻³·⁵ atm (atmosphère), K_H = 3,4×10⁻² mol/L/atm. Calculez [CO₂] en mg C/L.", correction: "[CO₂] = K_H × pCO₂ = 3,4×10⁻² × 10⁻³·⁵ = 3,4×10⁻² × 3,162×10⁻⁴ = 1,075×10⁻⁵ mol/L. En mg C/L : 1,075×10⁻⁵ × 12000 = 0,129 mg C/L. Concentration typique du CO₂ dissous dans les eaux de surface en équilibre avec l'atmosphère." },
      { id: 2, enonce: "Eau naturelle : pH = 7,5, CT = 2,5 mmol/L. Calculez [CO₂], [HCO₃⁻], [CO₃²⁻].", correction: "α₀ = 1/(1 + 10^(pH-pKa1) + 10^(2pH-pKa1-pKa2)) = 1/(1 + 10^(7,5-6,35) + 10^(2×7,5-6,35-10,33)) = 1/(1 + 14,13 + 10^(-2,18)) = 1/(15,13 + 0,0066) ≈ 1/15,14 = 0,0661. [CO₂] = 0,0661 × 2,5 = 0,165 mmol/L. [HCO₃⁻] = (10^(1,15)) × [CO₂] = 14,13 × 0,165 = 2,33 mmol/L. [CO₃²⁻] = (10^(-2,83)) × [HCO₃⁻] = 0,00148 × 2,33 = 0,00345 mmol/L." },
      { id: 3, enonce: "Un lac de granites a alcalinité = 0,15 meq/L. Évaluez sa vulnérabilité aux pluies acides.", correction: "Alcalinité de 0,15 meq/L = 150 μeq/L. Très faible (eau douce de granites pauvres en carbonates). Capacité de neutralisation : quelques dizaines à centaines de mmol H⁺/m² par an selon le volume du lac. Avec des apports de pluies acides de 0,5-2 meq/L pH 4,5 par an, l'alcalinité peut être épuisée en quelques années → lac acide (pH < 5). Très vulnérable : risque de perte de populations piscicoles. Critère de survie des poissons : AT > 50 μeq/L et pH > 5,5. Ce lac est en situation critique." },
      { id: 4, enonce: "Citez les 3 étapes de la formation du drainage acide minier par l'oxydation de la pyrite.", correction: "Étape 1 : Oxydation chimique lente de la pyrite par O₂ : FeS₂ + 7/2 O₂ + H₂O → Fe²⁺ + 2SO₄²⁻ + 2H⁺. pH diminue progressivement. Étape 2 : Oxydation de Fe²⁺ en Fe³⁺ (accélérée par Acidithiobacillus ferrooxidans à pH 2-4). Fe³⁺ est un puissant oxydant de la pyrite : FeS₂ + 14Fe³⁺ + 8H₂O → 15Fe²⁺ + 2SO₄²⁻ + 16H⁺. Étape 3 : Réaction autocatalytique : Fe³⁺ régénéré → pyrite dissolue → plus de Fe²⁺ → plus de bactéries → accélération explosive. pH peut atteindre 1-2 en quelques mois." },
      { id: 5, enonce: "Eau de source, pH = 6,8, [HCO₃⁻] = 150 mg/L. Elle dégazé de CO₂ jusqu'à l'équilibre avec l'atmosphère. Estimez le nouveau pH.", correction: "[HCO₃⁻] = 150/61 = 2,46 mmol/L. L'alcalinité est conservée au dégazage (HCO₃⁻ ne dégazé pas). En équilibre atmosphérique : pCO₂ = 10⁻³·⁵ atm → [CO₂] = 1,2×10⁻⁵ M. Ka1 = [H⁺][HCO₃⁻]/[CO₂] = 10⁻⁶·³⁵. [H⁺] = Ka1 × [CO₂]/[HCO₃⁻] = 10⁻⁶·³⁵ × 1,2×10⁻⁵ / 2,46×10⁻³ = 1,35×10⁻⁶/2,46×10⁻³ = 5,49×10⁻⁴... non, recalc : [H⁺] = 4,467×10⁻⁷ × 1,2×10⁻⁵/2,46×10⁻³ = 2,18×10⁻⁹ → pH = 8,66. L'eau se rééquilibre à pH ≈ 8,7 (dégazage de CO₂ → pH monte)." },
      { id: 6, enonce: "Expliquez pourquoi l'acidification des océans menace les coraux.", correction: "Les coraux construisent leur squelette en aragonite (CaCO₃ polymorpbisme). La solidité de l'aragonite dépend de l'état de saturation Ω_aragonite = [Ca²⁺][CO₃²⁻]/K_sp_aragonite. Ω > 3 : calcification forte. Ω = 1-3 : calcification réduite. Ω < 1 : dissolution. L'absorption de CO₂ par l'océan : CO₂ + H₂O → H⁺ + HCO₃⁻ → H⁺ réagit avec CO₃²⁻ → HCO₃⁻. Résultat : [CO₃²⁻] diminue → Ω_aragonite diminue. Ω a baissé de ~3,5 (pré-industriel) à ~2,5 actuellement sur les récifs tropicaux. À horizon 2100 (SSP5-8.5) : Ω < 1,5 dans de nombreuses zones → déclin des récifs, érosion des squelettes." },
      { id: 7, enonce: "Méthode de titrage de l'alcalinité : pourquoi titrer jusqu'à pH 4,5 ?", correction: "pH 4,5 est le point de demi-neutralisation du bicarbonate (point d'équivalence de l'indicateur méthyl orange, ME = Méthyl Orange). À ce pH, HCO₃⁻ est totalement converti en CO₂ : HCO₃⁻ + H⁺ → CO₂ + H₂O. CO₃²⁻ a été doublement neutralisé : CO₃²⁻ + 2H⁺ → CO₂ + H₂O. pH 4,5 correspond à la fin de la réaction de neutralisation du bicarbonate. En titrant jusqu'à ce point, on mesure AT = [HCO₃⁻] + 2[CO₃²⁻] (+ corrections OH⁻, H⁺). Titrer jusqu'à pH < 4 dissoudrait le CO₂ produit, perturbant l'équilibre." },
      { id: 8, enonce: "Un bassin minier génère un DAM de débit Q = 50 L/s, pH = 2,8, SO₄²⁻ = 1500 mg/L, [Fe_tot] = 150 mg/L. Estimez la quantité de Ca(OH)₂ à injecter par heure pour neutraliser à pH 8.", correction: "Acide libre : [H⁺] = 10⁻²·⁸ = 1,585×10⁻³ mol/L. Acide ajouté par précipitation de Fe(OH)₃ : Fe³⁺ + 3OH⁻ → Fe(OH)₃ : [Fe³⁺] ≈ 150/56 = 2,68 mmol/L → 3 × 2,68 = 8,04 mmol OH⁻/L. Total à neutraliser ≈ 1,585 + 8,04 ≈ 10 meq/L. Pour neutraliser à pH 8 : besoin de 10 meq Ca(OH)₂/L. M(Ca(OH)₂) = 74 g/mol, 1 meq = 37 mg. Besoin : 10 × 37 = 370 mg/L. Q = 50 L/s = 180 m³/h. Masse Ca(OH)₂/h = 370 g/m³ × 180 = 66,6 kg/h ≈ 67 kg/h de lait de chaux." }
    ],
    flashcards: [
      { question: "pKa du système carbonaté et domaines de pH", reponse: "H₂CO₃* (CO₂ dissous) ⇌ HCO₃⁻ : pKa1 = 6,35. HCO₃⁻ ⇌ CO₃²⁻ : pKa2 = 10,33 (à 25°C). pH < 6,35 : CO₂ domine. 6,35 < pH < 10,33 : HCO₃⁻ domine (eaux naturelles). pH > 10,33 : CO₃²⁻ domine. Dans les eaux naturelles (pH 6-9), HCO₃⁻ est toujours l'espèce carbonatée dominante. Les eaux très acides (tourbières, DAM) ont CO₂ dissous dominant. Les eaux très basiques (dolines, lacs alcalins sodiques) ont CO₃²⁻." },
      { question: "Alcalinité : définition et mesure", reponse: "AT = [HCO₃⁻] + 2[CO₃²⁻] + [OH⁻] - [H⁺] (en eq/L). Mesurée par titration acide fort jusqu'à pH 4,5 (méthyl orange). Propriété conservée lors du dégazage de CO₂ (uniquement carbonate et bicarb. qui participent). En meq/L : eau très douce < 0,5, eau douce 0,5-5, eau dure 2-10, eau de mer 2,3. Indicateur de tampon : eau très douce AT < 0,5 meq/L = vulnérable aux pluies acides." },
      { question: "Drainage acide minier : processus et impact", reponse: "Oxydation pyrite : FeS₂ + 7/2 O₂ + H₂O → Fe²⁺ + 2SO₄²⁻ + 2H⁺. Autocatalytique via bactéries (Acidithiobacillus ferrooxidans) × 10⁵-10⁶. pH 1-3 dans les lixiviats. Métaux solubles à pH bas (Zn, Pb, Cd, Cu, As). Impact : rivières ocre (floc de Fe(OH)₃), mort des poissons, contamination des eaux souterraines. Traitement : neutralisation à la chaux, zones humides construites. Passif env. : milliards € pour les mines abandonnées." },
      { question: "Acidification des océans : mécanisme", reponse: "Absorption de CO₂ : CO₂ + H₂O ⇌ H₂CO₃* → H⁺ + HCO₃⁻. H⁺ consomme CO₃²⁻ : H⁺ + CO₃²⁻ → HCO₃⁻. Résultat : [CO₃²⁻] ↓ → Ω aragonite ↓ → impact coraux. pH marin : 8,2 (pré-industriel) → 8,1 (aujourd'hui, soit -26% [H⁺]). À +4°C/2100 : pH 7,8 (-100% Ω aragonite tropical). La lysocline (zone de dissolution des carbonates) remonte vers la surface." },
      { question: "Loi de Henry pour le CO₂", reponse: "[CO₂] = K_H × pCO₂. K_H(25°C) = 3,4×10⁻² mol/L/atm. K_H(10°C) = 5,3×10⁻² mol/L/atm (CO₂ plus soluble dans l'eau froide). Atmosphère : pCO₂ = 10⁻³·⁵ atm (420 ppm) → [CO₂] = 1,2×10⁻⁵ M. Sol sous forêt : pCO₂ = 10⁻²·⁵ à 10⁻¹·⁵ atm → [CO₂] 10-100× plus élevé. Eaux souterraines riches en CO₂ biogénique → acides → dissolution des roches carbonatées." }
    ]
  },

  'MASTER-EAU-068': {
    id: 'MASTER-EAU-068',
    titre: 'Oxydoréduction et transformations des éléments',
    fiche: {
      intro: "Les réactions d'oxydoréduction (redox) contrôlent la spéciation et la mobilité de nombreux éléments en traces dans les eaux naturelles (Fe, Mn, N, S, As, Cr, U, Se). Le potentiel redox (Eh ou pE) et le pH définissent le diagramme Eh-pH (Pourbaix) qui prédit les espèces stables de chaque élément. La cinétique microbienne des réactions redox est fondamentale pour comprendre la qualité des eaux souterraines et la bioremédiation.",
      sections: [
        { titre: "Thermodynamique des réactions redox", sous_sections: [
          { titre: "Potentiel redox Eh et pE", contenu: "Le potentiel redox Eh (en volts) ou pE = Eh/0,05916 (sans dimension, à 25°C) mesure la tendance d'un système à donner ou recevoir des électrons. pE = -log[e⁻]. Plus pE est élevé, plus le milieu est oxydant. Les couples redox standard (E°) sont classés par ordre de potentiel croissant : O₂/H₂O (E° = +1,23V), NO₃⁻/N₂ (+0,74V), MnO₂/Mn²⁺ (+0,42V), Fe(OH)₃/Fe²⁺ (-0,05V), SO₄²⁻/H₂S (-0,22V), CO₂/CH₄ (-0,24V). La relation de Nernst : Eh = E° + (RT/nF) × ln([oxydant]/[réducteur])." },
          { titre: "Diagramme Eh-pH (Pourbaix)", contenu: "Le diagramme Eh-pH (ou diagramme de Pourbaix) représente les domaines de stabilité des espèces d'un élément en fonction du potentiel redox (Eh) et du pH. Axes : pH (0-14) en abscisse, Eh (-1 à +1,5 V) en ordonnée. Limites de stabilité de l'eau : droite supérieure (oxydation de H₂O en O₂ : Eh = 1,23 - 0,059 pH) et droite inférieure (réduction de H₂O en H₂ : Eh = -0,059 pH). Les eaux naturelles se situent dans ce domaine. Les diagrammes Eh-pH de Fe, Mn, As, Cr, S, N permettent de prévoir l'espèce stable pour toute combinaison Eh/pH et d'interpréter les mesures de terrain." }
        ]},
        { titre: "Réactions redox importantes dans les eaux naturelles", sous_sections: [
          { titre: "Cycle du fer et du manganèse", contenu: "Le fer est l'élément redox le plus important dans la géochimie des eaux douces. Fe(II) = Fe²⁺ (soluble, conditions réductrices), Fe(III) = Fe³⁺ ou Fe(OH)₃ (insoluble, conditions oxiques). La transition Fe²⁺/Fe(OH)₃ se produit à Eh ≈ 0 V (conditions légèrement oxiques). L'oxydation de Fe²⁺ par O₂ est lente à pH < 6 (cinétique chimique), rapide à pH > 7 (catalysée par les surfaces). Gallionella ferruginea et Sphaerotilus natans oxydent Fe²⁺ → Fe(OH)₃ biologiquement. Dans les eaux souterraines : Fe²⁺ peut atteindre 10-50 mg/L en conditions réductrices. Le Mn(II) suit un comportement similaire mais avec un Eh de réduction plus élevé (Mn(IV)/Mn²⁺ à Eh ≈ +0,4V)." },
          { titre: "Cycle du soufre et des sulfates", contenu: "Le soufre existe sous plusieurs états d'oxydation : SO₄²⁻ (S+VI, oxydé), S° (S0, élémentaire), H₂S/HS⁻ (S-II, réduit). La réduction des sulfates (BSR, bactéries sulfato-réductrices) : SO₄²⁻ + 2CH₂O → H₂S + 2HCO₃⁻. Conditions : anaérobie, matière organique disponible. Produit H₂S (gaz, odorant et toxique, seuil olfactif 0,05 ppm). L'oxydation de H₂S produit des sulfates et de l'acidité (eaux sulfureuses). Dans les sédiments marins, la réduction des sulfates est la principale respiration anaérobie. Dans les eaux souterraines profondes (aquifères artésiens), la présence d'H₂S indique des conditions fortement réductrices." }
        ]},
        { titre: "Redox et comportement des contaminants", sous_sections: [
          { titre: "Chrome : Cr(III) vs Cr(VI)", contenu: "Le chrome existe sous deux formes principales : Cr(III) = chrome trivalent (peu mobile, précipite en Cr(OH)₃, essentiel à faible dose) et Cr(VI) = chromate/dichromate (CrO₄²⁻, Cr₂O₇²⁻, très mobile, hautement toxique et cancérigène). Dans les eaux oxiques (Eh > +0,3V), Cr(VI) est stable → risque de contamination. Dans les eaux réductrices, Cr(VI) est réduit en Cr(III) → immobilisation. La bioremédiation de sites contaminés au Cr(VI) utilise cette réaction : injection de matière organique (éthanol, acétate) → réduction microbienne de Cr(VI) → précipitation de Cr(OH)₃ → immobilisation. La norme AEP est 50 μg/L (Cr total), en révision à 25 μg/L." },
          { titre: "Uranium et actinides : mobilité selon Eh", contenu: "L'uranium naturel existe sous deux états d'oxydation : U(VI) = UO₂²⁺ (uranyle, très soluble en pH 5-9, mobile, forme des complexes carbonatés UO₂(CO₃)₂²⁻) et U(IV) = UO₂ (uraninite, insoluble, immobile). Les aquifères oxydants dissolvent l'uranium de la roche (leucogranites, phosphorites) → contamination des eaux. La norme OMS est 30 μg/L. La bioremédiation des eaux uranifères injecte des accepteurs d'électrons pour créer des conditions réductrices → U(VI) réduit en U(IV) → précipitation. La réduction de U(VI) par Geobacter metallireducens est l'une des biorémédiations redox les mieux étudiées (projet NABIR, USA)." }
        ]},
        { titre: "Mesure et interprétation du potentiel redox", sous_sections: [
          { titre: "Mesure terrain de Eh et son interprétation", contenu: "Le potentiel redox est mesuré par une électrode de platine (inerte) couplée à une électrode de référence (Ag/AgCl, calomel). Eh_terrain = E_mesuré + E_ref + correction de jonction. L'électrode de platine mesure le couple redox dominant dans la solution. Dans les eaux aérées : Eh ≈ +0,4 à +0,6V (couple O₂/H₂O). Dans les eaux souterraines réductrices : Eh peut atteindre -0,2 à -0,4V (couple SO₄²⁻/H₂S ou CO₂/CH₄). L'interprétation de Eh est délicate : mélange de couples, déséquilibre cinétique, fouling de l'électrode. Le pE calculé (PHREEQC) est plus précis que le Eh mesuré." },
          { titre: "Zonation redox et séquence de réduction", contenu: "Dans les aquifères et les sédiments, la consommation de l'oxygène par les bactéries crée une séquence de zones redox (zonation de Chapelle) : zone aérobie (DO > 1 mg/L) → zone de dénitrification (NO₃⁻ consommé) → zone de réduction du manganèse → zone de réduction du fer → zone sulfato-réductrice (H₂S présent) → zone méthanogène. Cette séquence est observée dans les panaches de contamination organique (stations-service, décharges). La géochimie du panache est un indicateur des processus de biodégradation naturelle (MNA, Monitored Natural Attenuation)." }
        ]}
      ],
      points: ["pE = Eh/0,05916 (25°C). Élevé → oxydant. Bas → réducteur.", "Nernst : Eh = E° + (RT/nF) × ln([Ox]/[Red]).", "O₂/H₂O : E° = +1,23V. SO₄²⁻/H₂S : E° = -0,22V.", "Fe²⁺ soluble (réducteur). Fe(OH)₃ insoluble (oxydant).", "Cr(VI) : mobile, cancérigène. Cr(III) : immobile, peu toxique.", "BSR (bactéries sulfato-réductrices) : SO₄²⁻ → H₂S en anaérobie.", "Zonation redox : O₂ > NO₃⁻ > MnO₂ > Fe(OH)₃ > SO₄²⁻ > CO₂.", "Diagramme Pourbaix : domaines de stabilité Eh-pH de chaque espèce.", "Bioremédiation Cr(VI) : injection matière organique → réduction Cr(VI) → Cr(OH)₃.", "Uranium mobile en U(VI) (oxydant) → U(IV) insoluble (réducteur)."],
      formules: [
        { nom: "Équation de Nernst", expression: "Eh = E° + (RT/nF) × ln([Ox]/[Red])", variables: "E° = potentiel standard (V), R = 8,314, T en K, n = nb d'électrons, F = 96485 C/mol" },
        { nom: "Relation pE-Eh", expression: "pE = Eh / 0,05916  (à 25°C)", variables: "pE = -log([e⁻]). Eh en Volts. 0,05916 = RT ln10/F = 0,02569 × 2,303" },
        { nom: "Réduction des sulfates par BSR", expression: "SO₄²⁻ + 2CH₂O → H₂S + 2HCO₃⁻", variables: "CH₂O = matière organique (formule simplifiée). Anaérobie strict. ΔG° = -77 kJ/mol CH₂O" },
        { nom: "Réduction du fer ferrique (conditions anaérobies)", expression: "Fe(OH)₃ + 3H⁺ + e⁻ → Fe²⁺ + 3H₂O",  variables: "E° = -0,05V (vs EHN). Réaction catalysée par Geobacter, Shewanella" },
        { nom: "Réduction du chrome hexavalent", expression: "CrO₄²⁻ + 3e⁻ + 4H⁺ → Cr³⁺ + 4H₂O",  variables: "E° = +1,33V. Réduction spontanée en présence de réducteur (Fe²⁺, MO). Cr³⁺ précipite en Cr(OH)₃" }
      ],
      retenir: "Le potentiel redox (Eh, pE) contrôle la spéciation de Fe, Mn, S, N, As, Cr, U. Les diagrammes Pourbaix (Eh-pH) prévoient les espèces stables. La séquence redox des aquifères reflète l'épuisement progressif des accepteurs d'électrons. Cr(VI) est un contaminant mobile en conditions oxiques, immobilisé en conditions réductrices. La bioremédiation exploite les réactions redox microbiennes pour immobiliser les contaminants."
    },
    exercices: [
      { id: 1, enonce: "Eh mesuré = +0,42V. T = 25°C. Calculez pE.", correction: "pE = Eh/0,05916 = 0,42/0,05916 = 7,1. Interprétation : pE = 7,1 ≈ eau légèrement oxique. La frontière Fe²⁺/Fe(OH)₃ est à pE ≈ 1 (pH 7) → à pE = 7,1, le fer est sous forme Fe(OH)₃ (oxydé, insoluble). Conditions de dénitrification active possible (pE > 4 nécessaire pour NO₃⁻)." },
      { id: 2, enonce: "Couple SO₄²⁻/H₂S : E° = -0,22V. [SO₄²⁻] = 1 mmol/L, [H₂S] = 10 μmol/L, pH = 7. Calculez Eh.", correction: "Demi-réaction : SO₄²⁻ + 10H⁺ + 8e⁻ → H₂S + 4H₂O. Nernst : Eh = E° + (0,05916/8) × log([SO₄²⁻][H⁺]¹⁰/[H₂S]) = -0,22 + 0,0074 × log(10⁻³ × (10⁻⁷)¹⁰ / 10⁻⁵) = -0,22 + 0,0074 × log(10⁻³ × 10⁻⁷⁰ / 10⁻⁵) = -0,22 + 0,0074 × log(10⁻⁶⁸) = -0,22 + 0,0074 × (-68) = -0,22 - 0,503 = -0,723V. Très réducteur → conditions de réduction des sulfates active." },
      { id: 3, enonce: "Expliquez la zonation redox dans un panache de contamination d'une station-service.", correction: "Le carburant (BTEX, hydrocarbures) = matière organique → épuisement progressif des accepteurs d'électrons selon l'énergie disponible : Zone A (proche source) : O₂ consommé en premier (aérobie → anaérobie) en quelques mètres. Zone B : NO₃⁻ consommé (dénitrification) → N₂. Zone C : Mn(IV) → Mn²⁺ dissous. Zone D : Fe(OH)₃ → Fe²⁺ dissous (eau orange à la remontée). Zone E : SO₄²⁻ → H₂S (odeur dans les puits proches). Zone F : CO₂ → CH₄ (zone méthanogène). Cette zonation est utilisée pour évaluer la biodégradation naturelle atténuée (MNA) dans les études de sites pollués." },
      { id: 4, enonce: "Cr(VI) est mesuré à 120 μg/L dans une eau souterraine d'un site industriel. Quelle stratégie de bioremédiation proposez-vous ?", correction: "Principe : injecter un substrat carboné (éthanol, acétate, molasse) pour stimuler les bactéries réductrices anaérobies qui vont : 1. Consommer O₂ et NO₃⁻ (créer l'anaérobiose). 2. Réduire Cr(VI) → Cr(III) : CrO₄²⁻ + réducteur → Cr(OH)₃↓. Cr(OH)₃ précipite en place et est immobile. Alternative abiotique : barrière ZVI (zero-valent iron, Fe⁰) → Fe⁰ réduit Cr(VI) directement. Monitoring : mesures de Cr(VI), Cr(III), Fe²⁺, SO₄²⁻, Eh dans les puits amont/aval de la barrière. Cr(OH)₃ est stable à long terme si les conditions restent réductrices. Risque : re-mobilisation en cas de re-oxygénation." },
      { id: 5, enonce: "Citez les 5 accepteurs d'électrons utilisés dans les aquifères contaminés par ordre d'énergie disponible.", correction: "O₂ (ΔG = -487 kJ/mol CH₂O oxydé) → NO₃⁻ (-481 kJ/mol) → MnO₂ (-349 kJ/mol) → Fe(OH)₃ (-114 kJ/mol) → SO₄²⁻ (-77 kJ/mol) → CO₂ (-24 kJ/mol, méthanogenèse). Cette séquence est dictée par l'énergie disponible (thermodynamique) + la cinétique microbienne. Elle est observée depuis la zone la plus contaminée (méthanogène) jusqu'à la frange du panache (aérobie). C'est la clé de la compréhension de la biodégradation naturelle atténuée." },
      { id: 6, enonce: "Dans un lac stratifié, la couche hypolimnique (fond) a Eh = -0,15V en été. Quelles espèces de Mn, Fe, N et S prédominent ?", correction: "Eh = -0,15V ≈ pE = -2,5. Zone fortement réductrice (anaérobie confirmé). Fe : Fe²⁺ soluble (Fe(OH)₃ dissous, eau rougeâtre à la remontée). Mn : Mn²⁺ soluble (MnO₂ réduit). N : NH₄⁺ (NO₃⁻ et NO₂⁻ réduits → dénitrification complète, puis ammonification). S : H₂S/HS⁻ présents (SO₄²⁻ réduit par BSR). Ce type de lac méromictique (stratification persistante) peut accumuler des quantités importantes de Fe²⁺, Mn²⁺, NH₄⁺ et H₂S dans le fond. À la déstratification automnale, ces espèces remontent et créent une demande en O₂ intense." },
      { id: 7, enonce: "Pourquoi l'uranium est-il plus mobile dans les eaux oxiques que dans les eaux réductrices ?", correction: "U(VI) = uranyle UO₂²⁺ : très soluble à pH 5-9 (eaux naturelles), surtout sous forme de complexes carbonatés UO₂(CO₃)₂²⁻ et UO₂(CO₃)₃⁴⁻ → mobile, peut atteindre 100-10000 μg/L dans les aquifères uranifères. U(IV) = uraninite UO₂ : minéral insoluble (Ksp très bas), pas de complexes importants → immobile. Réduction : UO₂²⁺ + 2e⁻ → UO₂↓. Les aquifères réducteurs (faible Eh) immobilisent l'uranium. Les aquifères oxydants (contactant des granites ou des phosphorites uranifères) dissolvent l'uranium → contamination." },
      { id: 8, enonce: "Un puits artésien donne une eau avec H₂S = 0,8 mg/L et Fe²⁺ = 5 mg/L. Que se passe-t-il à l'émergence (contact avec l'air) ?", correction: "À l'émergence, la mise en contact avec O₂ atmosphérique déclenche des oxydations rapides : Fe²⁺ + 1/4 O₂ + 5/2 H₂O → Fe(OH)₃↓ + 2H⁺ → précipité brun rouille (ocre). H₂S + 1/2 O₂ → S° + H₂O → soufre élémentaire (blanc/jaune), ou H₂S + 2O₂ → SO₄²⁻ + 2H⁺ (acidification). Résultat : eau turbide (Fe(OH)₃), odeur d'œuf pourri (H₂S résiduel), pH baisse. Traitement : dégazage (aération) pour éliminer H₂S + filtration pour Fe(OH)₃. Ces eaux sont courantes dans les aquifères profonds artésiens (eaux thermales, sources artésiennes de plaine)." }
    ],
    flashcards: [
      { question: "pE et Eh : signification et relation", reponse: "Eh = potentiel de l'électrode de platine vs EHN (V). pE = -log[e⁻] = Eh/0,05916 (25°C). pE élevé (+7 à +13) : eau très oxydante (oxique). pE faible (-5 à -2) : eau très réductrice (méthanogène). Eau de pluie en équilibre O₂ : Eh ≈ +0,8V, pE ≈ 13. Eau souterraine profonde (H₂S) : Eh ≈ -0,2V, pE ≈ -3. Mesure terrain avec électrode Pt, référence Ag/AgCl." },
      { question: "Diagramme Eh-pH (Pourbaix) : utilisation", reponse: "Axes : pH (0-14) en x, Eh (-1 à +1,5V) en y. Limites de stabilité de l'eau (droites du haut O₂ et du bas H₂). Domaines de stabilité des espèces d'un élément (délimités par des lignes représentant les équilibres redox et acido-basiques). Usage : prédire l'espèce stable pour tout couple (Eh, pH). Exemple Fe : Eh > 0V, pH > 7 → Fe(OH)₃. Eh < -0,1V → Fe²⁺. pH < 3, Eh élevé → Fe³⁺." },
      { question: "Cycle du fer en milieu aquatique", reponse: "Fe(II) : Fe²⁺ et FeOH⁺ → soluble, aquifères réducteurs, eau de fond des lacs, eaux souterraines. Fe(III) : Fe(OH)₃ amorphe, FeOOH, Fe₂O₃ → insoluble, précipite en eau oxique. Transition à Eh ≈ 0V (pH 7) → 2Fe²⁺ + 1/2O₂ + 5H₂O → 2Fe(OH)₃ + 4H⁺. Accélérée biologiquement par Gallionella à pH > 6. Rôle clé : adsorption de l'As, PO₄, Cr sur Fe(OH)₃. Libération lors de la dissolution réductrice (anoxie)." },
      { question: "Cr(VI) vs Cr(III) : contraste de réactivité", reponse: "Cr(VI) = CrO₄²⁻ et HCrO₄⁻ : très soluble, mobile, CMR (cancérogène mutagène reprotoxique), norme 50 μg/L. Cr(III) : peu soluble (précipite en Cr(OH)₃), immobile, peu toxique, oligo-élément essentiel. Transition Cr(VI)→Cr(III) : réduction par Fe²⁺ ou matière organique (spontanée en conditions réductrices). Transition Cr(III)→Cr(VI) : oxydation par MnO₂ (spontanée en conditions oxiques). Bioremédiation : stimuler la réduction microbienne → immobilisation. Sites concernés : industries du chrome, tanneries." },
      { question: "Bactéries sulfato-réductrices (BSR)", reponse: "Réduction anaérobie des sulfates : SO₄²⁻ + 2CH₂O → H₂S + 2HCO₃⁻. Bactéries obligatoirement anaérobies : Desulfovibrio, Desulfobacter. Conditions : Eh < -0,1V, disponibilité de sulfates et de MO. H₂S : toxique (LC50 inhalation 300-500 ppm), odeur oeuf pourri seuil 0,05 ppm. Problèmes : corrosion des conduites (H₂S + Fe → FeS), odeurs dans les réseaux d'égouts, formation de sulfures dans les digesteurs. Utilité : bioremédiation (réduction des métaux, précipitation FeS immobilise métaux)." }
    ]
  }

,

  'MASTER-EAU-069': {
    id: 'MASTER-EAU-069',
    titre: 'Dissolution, précipitation, adsorption et échanges ioniques',
    fiche: {
      intro: "La réactivité des surfaces minérales (argiles, oxydes de fer, carbonates) avec les ions en solution (dissolution, précipitation, adsorption, échanges ioniques) contrôle la chimie des eaux souterraines et de surface. Ces processus sont à la base du traitement des eaux (coagulation, échange d'ions, adsorption sur charbon actif) et conditionnent la mobilité des contaminants dans les sols et les aquifères.",
      sections: [
        { titre: "Dissolution et précipitation minérale", sous_sections: [
          { titre: "Cinétique et thermodynamique de la dissolution", contenu: "La dissolution d'un minéral est gouvernée par la thermodynamique (SI = log IAP/K_sp) et la cinétique de surface. Loin de l'équilibre (SI << 0), la vitesse de dissolution r = k × a_H⁺^n × A_min (loi de Lasaga), où k = constante de vitesse, a_H⁺ = activité du proton, n = ordre de réaction, A_min = aire de surface réactive. Pour la calcite : r = k × (1 - IAP/K_sp) (loi linéaire proche de l'équilibre). La dissolution de la calcite dans les karsts est contrôlée par la diffusion du CO₂ et par la cinétique de surface selon le régime hydraulique. Les minéraux alumino-silicatés (feldspaths, argiles) se dissolvent très lentement (temps géologiques) mais contrôlent la chimie à long terme des aquifères anciens." },
          { titre: "Précipitation et nucléation", contenu: "La précipitation d'un minéral nécessite une sursaturation (SI > 0) et un mécanisme de nucléation. La nucléation homogène (formation spontanée d'un germe) est difficile (barrière d'énergie élevée). La nucléation hétérogène (sur une surface existante) est beaucoup plus facile. Le phénomène de précipitation séquentielle (règle d'Ostwald) stipule que c'est la phase la moins stable thermodynamiquement qui précipite en premier (cinétique plus rapide) avant d'évoluer vers la phase stable. Exemple : CaCO₃ précipite d'abord en vatérite (instable) ou aragonite (métastable), avant de se recristalliser en calcite (stable). La précipitation contrôlée de métaux en traitement des eaux utilise ces principes pour séparer les métaux et contrôler la granulométrie des boues." }
        ]},
        { titre: "Adsorption sur les surfaces minérales", sous_sections: [
          { titre: "Isothermes de Langmuir et Freundlich", contenu: "L'adsorption est la fixation d'un soluté (adsorbat) sur une surface solide (adsorbant). L'isotherme de Langmuir décrit l'adsorption en monocouche sur des sites identiques : q = q_max × K_L × c / (1 + K_L × c), où q = quantité adsorbée (mg/g), c = concentration en solution (mg/L), q_max = capacité maximale, K_L = constante de Langmuir. L'isotherme de Freundlich décrit l'adsorption sur surfaces hétérogènes : q = K_F × c^(1/n), où K_F et n = constantes empiriques. L'adsorption sur les oxydes de fer (FeOOH, Fe(OH)₃) est majeure pour les anions (As, PO₄, F⁻, Mo) : adsorption par échange de ligand avec les groupes FeOH de surface (surface complexation)." },
          { titre: "Adsorption sur le charbon actif et les zéolithes", contenu: "Le charbon actif (granulaire GAC, poudre PAC) est l'adsorbant universel en traitement des eaux (surface spécifique 800-1500 m²/g). Il adsorbe les composés organiques hydrophobes (pesticides, HAP, médicaments, perturbateurs endocriniens). La capacité d'adsorption est décrite par l'isotherme de Freundlich. La désorption thermique à 800°C régénère le charbon actif. Les zéolithes (alumino-silicates microporeux, surface 300-800 m²/g) échangent les cations monovalents (NH₄⁺, Na⁺) et divalents (Ca²⁺, Mg²⁺). La clinoptilolite (zéolithe naturelle) est utilisée pour l'élimination de l'ammonium (nitrification artificielle)." }
        ]},
        { titre: "Échanges ioniques et capacité d'échange", sous_sections: [
          { titre: "Échange cationique dans les argiles", contenu: "Les argiles (montmorillonite, illite, kaolinite) possèdent des charges de surface négatives (substitutions isomorphiques) qui fixent les cations échangeables (Ca²⁺, Mg²⁺, Na⁺, K⁺, H⁺). La capacité d'échange cationique (CEC, en cmolc/kg) : montmorillonite 80-150, illite 20-50, kaolinite 3-15. L'adoucissement des eaux dures utilise des résines échangeuses de cations : Ca²⁺ + 2 R-Na⁺ ⇌ R₂-Ca²⁺ + 2Na⁺. L'échange ionique dans les aquifères est à l'origine de la diminution du Ca²⁺ et de l'augmentation du Na⁺ dans les eaux évoluant vers les milieux réducteurs (réactions de Wallis). Ces réactions modifient profondément la chimie des eaux en transit dans les argiles." },
          { titre: "Échangeurs d'ions en traitement des eaux", contenu: "Les résines échangeuses d'ions (cationiques fortes et faibles, anioniques fortes et faibles) sont largement utilisées en traitement des eaux : adoucissement (élimination Ca²⁺, Mg²⁺), déminéralisation complète (production d'eau ultrapure), élimination des nitrates (résines anioniques), déarsénication (résines chargées en Fe ou Al). La capacité d'échange (meq/mL de résine) conditionne la taille de l'installation. La régénération des résines utilise NaCl (résines cationiques), NaOH (résines anioniques fortes), ou H₂SO₄ (résines cationiques fortes). Le produit de régénération (saumures) est un déchet à traiter. Les résines à haute sélectivité pour les nitrates (Type II anioniques) sont le standard en France." }
        ]},
        { titre: "Interactions contaminants-surfaces", sous_sections: [
          { titre: "Rétention des métaux lourds sur les sols", contenu: "La rétention des métaux lourds (Cu, Pb, Zn, Cd, Ni) dans les sols résulte de plusieurs processus simultanés : adsorption sur les oxydes de Fe/Mn (prédominante à pH > 5), échanges ioniques sur les argiles et l'humus (CEC), précipitation d'hydroxydes ou de carbonates (pH > 7), incorporation dans des phases cristallines (occlusion). Le coefficient de distribution Kd = q/c (L/kg) synthétise tous ces processus. Kd(Pb²⁺) = 1000-100000 L/kg (très fortement retenu). Kd(Cd²⁺) = 100-10000. Kd(Ni²⁺) = 10-1000. Ces valeurs dépendent fortement du pH, de la teneur en oxydes de Fe, de la CEC et du pH." },
          { titre: "Contaminants organiques et partage sol-eau", contenu: "La rétention des composés organiques dans le sol est gouvernée par la matière organique (MO) : Koc = Kd/foc, où Koc = coefficient de partage normalisé par la fraction de carbone organique foc. Log Koc est corrélé à log Kow (coeffcient de partage octanol-eau) : log Koc ≈ log Kow - 0,2 (relation empirique). Composés très lipophiles (PCB, HAP, dioxines) : Kow > 10⁵ → Koc > 10⁴ → fortement retenus par la MO. Composés hydrophiles (pesticides polaires, médicaments) : Kow faible → Koc < 100 → mobiles dans les aquifères. La rétention par la MO est réversible par lessivage, thermique ou biochimique (métabolisme microbien)." }
        ]}
      ],
      points: ["Langmuir : q = q_max × K_L × c/(1+K_L×c). Freundlich : q = K_F × c^(1/n).", "Charbon actif GAC : surface 800-1500 m²/g. Adsorbe composés organiques.", "CEC argiles : montmorillonite 80-150, illite 20-50, kaolinite 3-15 cmolc/kg.", "Résines échangeuses : adoucissement (Ca²⁺→Na⁺), dénitrification.", "Kd = q/c (L/kg) : coefficient de distribution contaminant-sol.", "Koc = Kd/foc. Log Koc ≈ log Kow - 0,2 (composés organiques).", "As, PO₄ : adsorption par échange de ligand sur FeOOH.", "Règle d'Ostwald : précipitation de la phase métastable en premier.", "Nucléation hétérogène : sur surface existante, beaucoup plus facile.", "CEC humus : 150-400 cmolc/kg (très élevé → rétention des métaux cationiques)."],
      formules: [
        { nom: "Isotherme de Langmuir", expression: "q = q_max × K_L × c / (1 + K_L × c)", variables: "q = quantité adsorbée (mg/g), c = concentration solution (mg/L), q_max = capacité max (mg/g), K_L = constante (L/mg)" },
        { nom: "Isotherme de Freundlich", expression: "q = K_F × c^(1/n)", variables: "K_F et n = constantes empiriques. n > 1 : favorable. log q = log K_F + (1/n) × log c" },
        { nom: "Coefficient de partage sol-eau", expression: "K_d = q / c",  variables: "q = concentration dans le solide (mg/kg), c = concentration en solution (mg/L). K_d en L/kg" },
        { nom: "Koc normalisé par la MO", expression: "K_oc = K_d / f_oc", variables: "f_oc = fraction de carbone organique du sol. log K_oc ≈ log K_ow - 0,2 (relation empirique)" },
        { nom: "Cinétique de dissolution (loi de Lasaga)", expression: "r = k × a_H⁺^n × A_min × (1 - IAP/K_sp)^p", variables: "k = constante de vitesse, A_min = surface réactive, IAP = produit ionique, K_sp = solubilité" }
      ],
      retenir: "La dissolution (cinétique + SI), l'adsorption (Langmuir, Freundlich) et l'échange ionique contrôlent la chimie des eaux et la mobilité des contaminants. Le charbon actif et les zéolithes sont les adsorbants clés en traitement des eaux. Les argiles (CEC) échangent les cations. Kd et Koc quantifient la rétention des contaminants dans les sols. Les oxydes de fer adsorbent spécifiquement As et PO₄."
    },
    exercices: [
      { id: 1, enonce: "Adsorption d'As sur FeOOH : q_max = 50 mg/g, K_L = 0,5 L/μg. c = 10 μg/L. Calculez q (Langmuir).", correction: "q = q_max × K_L × c / (1 + K_L × c) = 50 × 0,5 × 10 / (1 + 0,5 × 10) = 250 / (1 + 5) = 250/6 = 41,7 mg/g. L'adsorbant est utilisé à 41,7/50 = 83% de sa capacité maximale. À cette concentration (10 μg/L), l'adsorption est fortement saturée (plateau de Langmuir)." },
      { id: 2, enonce: "Résine échangeuse de cations : Ca²⁺ = 2 mmol/L, Mg²⁺ = 1 mmol/L. Calculez la dureté totale éliminée en °F pour Q = 10 m³/h de débit. Capacité résine = 50 g CaCO₃/L résine. Volume résine nécessaire pour 24h de traitement ?", correction: "TH entrée : Ca²⁺ = 2 mmol/L → 2 meq/L. Mg²⁺ = 1 mmol/L → 2 meq/L. TH = 4 meq/L = 4×2,5 = 10 °F. TH sortie ≈ 0 °F (échange complet). Charge journalière = TH × Q × t = 4 meq/L × 10000 L/h × 24h = 960 000 meq/j = 480 000 mg CaCO₃/j = 480 g CaCO₃/j. Volume résine : 480000/50000 = 9,6 L/j. Volume résine totale (1 cycle/j) = 9,6 L ≈ 10 L (très compact)." },
      { id: 3, enonce: "log Kow (atrazine) = 2,5, foc = 0,02 (sol agricole). Calculez Kd et estimez si l'atrazine est mobile.", correction: "log Koc ≈ log Kow - 0,2 = 2,5 - 0,2 = 2,3. Koc = 10^2,3 = 200 L/kg. Kd = Koc × foc = 200 × 0,02 = 4 L/kg. Facteur de retard R = 1 + ρ_b × Kd/θ, ρ_b ≈ 1,5 g/cm³, θ ≈ 0,3 : R = 1 + 1500 × 4/300 = 1 + 20 = 21. L'atrazine est retardée d'un facteur 21 par rapport à l'eau. Elle est relativement mobile comparée aux HAP (Kd > 1000) mais pas très mobile. Elle peut contaminer les aquifères sur des années à décennies." },
      { id: 4, enonce: "Citez 3 avantages du charbon actif granulaire (GAC) en traitement de l'eau potable.", correction: "1. Spectre très large : adsorbe la quasi-totalité des composés organiques hydrophobes (pesticides, HAP, COV, perturbateurs endocriniens, médicaments, goûts et odeurs). 2. Capacité élevée : surface spécifique 800-1500 m²/g → efficace à faibles concentrations (ng/L à μg/L). 3. Régénérabilité : régénération thermique à 800°C → économie d'échelle, durée de vie 5-10 ans. Limitations : pas de rétention des ions minéraux (NO₃⁻, As, F⁻), saturation progressive, coût élevé de la régénération thermique." },
      { id: 5, enonce: "Expliquez pourquoi l'arséniate (As(V)) est mieux retenu que l'arsénite (As(III)) par les sols ferriques.", correction: "As(V) = H₂AsO₄⁻, HAsO₄²⁻ à pH naturel : ions anioniques chargés. Adsorption par échange de ligand sur FeOOH (surface ≡Fe-OH₂⁺ → ≡Fe-AsO₄²⁻). Liaison forte (bi-dentate), log Kd = 3-4 L/kg. As(III) = H₃AsO₃ : espèce neutre (pKa = 9,2) à pH 6-9. Pas de charge → adsorption électrostatique faible. Liaison moins forte que As(V). Kd(As(III)) << Kd(As(V)). En conditions réductrices, As(V) est réduit en As(III) ET les oxydes de fer se dissolvent (libération physique de l'As) → double mécanisme de mobilisation. C'est pourquoi les aquifères réducteurs (Bangladesh, Cambodge) ont des concentrations en As(III) très élevées." },
      { id: 6, enonce: "Quelle est la différence entre adsorption et précipitation pour l'élimination du phosphore en station d'épuration ?", correction: "Adsorption (coagulation-floculation avec FeCl₃ ou Al₂(SO₄)₃) : Fe³⁺ forme Fe(OH)₃ amorphe (floc) → PO₄ adsorbé sur le floc (échange de ligand sur ≡Fe-OH) → décantation du floc. Réaction : FeCl₃ + HPO₄²⁻ + 2H₂O → FeHPO₄+. FePO₄↓ (si précipitation). La coagulation-floculation est rapide (minutes), contrôlée par le dosage en réactif. Précipitation biologique (Enhanced Biological Phosphorus Removal, EBPR) : les bactéries PAO (Accumulibacter) stockent PO₄ intracellulaire en conditions anaérobies/aérobies alternées → wasted sludge riche en P. EBPR : pas de réactif chimique mais installation plus complexe (réacteur anaérobie/aérobie)." },
      { id: 7, enonce: "Qu'est-ce que la CEC d'un sol et comment affecte-t-elle la rétention des métaux lourds ?", correction: "CEC = capacité d'échange cationique = nombre de charges négatives sur les surfaces des argiles et de la matière organique = capacité à fixer les cations. En cmolc/kg ou meq/100g. Sols sableux (peu d'argile, peu de MO) : CEC = 2-10 cmolc/kg → peu retiennent les métaux. Sols argileux + matière organique : CEC = 20-50 cmolc/kg → retiennent bien les métaux. Humus : CEC = 150-400 cmolc/kg. Les métaux lourds cationiques (Pb²⁺, Cd²⁺, Cu²⁺, Zn²⁺, Ni²⁺) échangent les ions naturellement adsorbés (Ca²⁺, Mg²⁺) → Kd fonction de la CEC. Les sols à haute CEC (argiles 2:1, terres noires) sont plus résilients aux contaminations métalliques." },
      { id: 8, enonce: "Un aquifère gréseux (foc = 0,002) reçoit une plume de trichloréthylène (TCE, log Kow = 2,42). Calculez R et la vitesse de migration.", correction: "log Koc ≈ 2,42 - 0,2 = 2,22. Koc = 166 L/kg. Kd = 166 × 0,002 = 0,332 L/kg. R = 1 + ρ_b × Kd/θ = 1 + 1600 × 0,332/0,25 = 1 + 2124 = 2125. Non, recalc : ρ_b = 1,6 kg/L, θ = 0,25, Kd = 0,332 L/kg (ou kg/kg?) → utiliser Kd en kg/kg = Kd(L/kg) × 10⁻³ = 0,000332. R = 1 + 1600 × 0,000332/0,25... attention unités : R = 1 + (ρ_b/θ) × Kd = 1 + (1,6/0,25) × 0,332 = 1 + 6,4 × 0,332 = 1 + 2,12 = 3,1. Avec v_eau = 1 m/j, v_TCE = 1/3,1 = 0,32 m/j. TCE assez mobile dans les grès (Kd faible)." }
    ],
    flashcards: [
      { question: "Isothermes de Langmuir et Freundlich", reponse: "Langmuir : q = q_max × K_L × c/(1+K_L×c). Hypothèse : monocouche, sites équivalents, saturation à q_max. Forme linéarisable : c/q = c/q_max + 1/(K_L × q_max). Freundlich : q = K_F × c^(1/n). Log-log linéaire. Hétérogène. n > 1 : favorable (cas courant). Usage : calage expérimental des isothermes d'adsorption pour le charbon actif, les oxydes de fer et les sols." },
      { question: "Charbon actif GAC vs PAC", reponse: "GAC (Granulaire, 0,5-2 mm) : filtre en colonne, durée de vie 5-10 ans, régénération thermique in situ ou externalisée. Traitements tertiaires en STEP (micropollluants) ou traitement AEP. PAC (Poudre, < 50 μm) : surface active très grande, contact court (15-30 min), dosage variable, dans les bassins de décantation. Boues riches en carbone à valoriser ou éliminer. Surface spécifique : 800-1500 m²/g pour les deux. Composés cibles : pesticides, médicaments, goûts/odeurs, COV chlorés." },
      { question: "CEC des argiles : valeurs et usage", reponse: "Kaolinite : 3-15 cmolc/kg (peu d'échange, charges permanentes faibles). Illite : 20-50 cmolc/kg. Montmorillonite (smectite) : 80-150 cmolc/kg (forte expansion, charges permanentes élevées). Humus : 150-400 cmolc/kg. L'argile montmorillonite est utilisée pour les géomembranes imperméables des décharges (GCL, Geosynthetic Clay Liner). La kaolinite est peu réactive. CEC élevée → forte capacité de rétention des cations (K⁺, Ca²⁺, NH₄⁺, métaux lourds)." },
      { question: "Kd et facteur de retard R", reponse: "Kd = q/c (L/kg) = coefficient de partage sol/eau. R = facteur de retard = v_eau/v_contaminant. R = 1 + (ρ_b/θ) × Kd. ρ_b = densité apparente ≈ 1,5-1,8 kg/L. θ = porosité effective ≈ 0,25-0,35. R = 1 (non rédacteur), R >> 1 (très retardé). Exemple : Pb²⁺ Kd = 1000 L/kg → R = 1 + (1,6/0,3)×1000 = 5334 → 5000× plus lent que l'eau. R conditionne les temps de migration dans les aquifères (évaluation des sites pollués)." },
      { question: "Adsorption de l'As sur les oxydes de fer", reponse: "Échange de ligand sur les groupes ≡Fe-OH de surface de FeOOH (goethite) et Fe(OH)₃. As(V) : forte adsorption (liaison bi-dentate, log Kd = 3-4). As(III) : faible adsorption (neutre à pH 6-9). Capacité max ≈ 10-50 mg As/g FeOOH. Concurrence : PO₄²⁻ et H₄SiO₄ compétiteurs (réduisent l'adsorption d'As). Application : filtres à sable ferriques, médias GFH (Granular Ferric Hydroxide) pour la déarsénication en AEP." }
    ]
  },

  'MASTER-EAU-070': {
    id: 'MASTER-EAU-070',
    titre: 'Cinétique des réactions et interactions biogéochimiques',
    fiche: {
      intro: "La cinétique des réactions géochimiques et microbiologiques détermine si un système évolue vers l'équilibre thermodynamique dans le temps caractéristique de l'eau (séjour dans l'aquifère, temps de transit dans la rivière). La biogéochimie couplant les processus chimiques et biologiques est fondamentale pour la compréhension des cycles de l'azote, du phosphore, du carbone et des métaux dans les écosystèmes aquatiques.",
      sections: [
        { titre: "Cinétique des réactions géochimiques", sous_sections: [
          { titre: "Lois cinétiques d'ordre 1 et pseudo-ordre 1", contenu: "Une réaction d'ordre 1 : dc/dt = -k × c → c(t) = c₀ × e^(-kt). Demi-vie : t₁/₂ = ln 2/k = 0,693/k. L'ordre 1 décrit la dégradation des composés organiques par photolyse, hydrolyse et biodégradation. La dégradation des pesticides dans les sols suit souvent une cinétique d'ordre 1 (DT50 = demi-vie = 10-500 jours selon le composé et le sol). La décroissance radioactive est un ordre 1 strict (k = λ = ln2/T₁/₂). La décomposition de la matière organique dans les sédiments : d[MO]/dt = -k₁ × [MO], k₁ = 0,01-0,1 j⁻¹ selon la qualité de la MO." },
          { titre: "Cinétique de Monod pour les réactions biologiques", contenu: "La cinétique de Monod décrit la croissance microbienne en fonction de la concentration du substrat limitant : μ = μ_max × S/(K_s + S), où μ = taux de croissance (j⁻¹), μ_max = taux maximal, S = concentration du substrat, K_s = constante de demi-saturation (S quand μ = μ_max/2). Le taux de consommation du substrat : dS/dt = -(μ_max/Y) × S/(K_s + S) × X, où Y = rendement microbien, X = biomasse. La cinétique de Monod est à la base de la modélisation des stations d'épuration biologiques (procédés à boues activées, biofilms), de la biodégradation dans les aquifères et des réacteurs de bioremédiation. Elle converge vers l'ordre 1 si S << K_s et vers l'ordre 0 si S >> K_s." }
        ]},
        { titre: "Cycle biogéochimique de l'azote", sous_sections: [
          { titre: "Nitrification, dénitrification et fixation symbiotique", contenu: "Le cycle de l'azote dans les eaux est gouverné par des processus biologiques : nitrification (NH₄⁺ → NO₂⁻ → NO₃⁻, bactéries nitrifiantes Nitrosomonas + Nitrobacter, aérobie strict, pH 7-8 optimal, inhibé < 10°C) ; dénitrification (NO₃⁻ → N₂, bactéries dénitrifiantes hétérotrophes comme Pseudomonas, anaérobie strict, source de carbone nécessaire) ; fixation symbiotique de N₂ (légumineuses-Rhizobium, cyanobactéries-Anabaena) ; ammonification (MO → NH₄⁺). La dénitrification dans les zones humides et les ripisylves (bandes enherbées) réduit les flux de NO₃⁻ vers les rivières (10-80% de réduction). L'anammox (dénitrification anaérobie avec NH₄⁺ et NO₂⁻) est utilisé dans les procédés SHARON-ANAMMOX des STEP." },
          { titre: "ANAMMOX et procédés biologiques de dénitrification", contenu: "L'anammox (Anaerobic Ammonium OXidation) : NH₄⁺ + NO₂⁻ → N₂ + 2H₂O. Découvert en 1995 (Mulder et al., Delft). Bactéries : Candidatus Brocadia, croissance très lente (temps de doublement 10-14 jours). Avantage : pas de carbone externe nécessaire (contrairement à la dénitrification classique). Inconvénient : cinétique lente, sensible aux chocs thermiques et aux inhibiteurs. Le procédé SHARON (Single reactor High Activity Ammonia Removal Over Nitrite) oxyde partiellement NH₄⁺ en NO₂⁻ (nitritation partielle), puis l'anammox convertit le mélange NH₄⁺/NO₂⁻ en N₂. Économie de 60% d'O₂ et 100% de carbone organique par rapport à la voie nitrification/dénitrification classique." }
        ]},
        { titre: "Cycle biogéochimique du phosphore", sous_sections: [
          { titre: "Sources, puits et temps de résidence du phosphore", contenu: "Le phosphore ne présente qu'un seul état d'oxydation stable (+5) dans les eaux naturelles (pas de cycle redox comme N, S). Le flux de P naturel = altération des roches phosphatées + P atmosphérique. Sources anthropiques dominantes : agriculture (engrais phosphatés, effluents d'élevage), eaux usées non ou mal épurées. Puits : sédimentation des particules (P particulaire), adsorption sur Fe(OH)₃ et argiles, précipitation de CaHPO₄ et HA (hydroxyapatite Ca₅(PO₄)₃OH). Le P est un nutriment limitant dans la plupart des lacs (eutrophisation) car l'azote peut être fourni par la fixation de N₂ atmosphérique. Le temps de résidence du P dans les lacs (quelques années à dizaines d'années) est beaucoup plus court que celui dans les sédiments (milliers d'années)." },
          { titre: "Eutrophisation et modélisation de l'eutrophisation", contenu: "L'eutrophisation des lacs (prolifération d'algues et de cyanobactéries) est liée à l'excès de phosphore (et parfois d'azote). Le modèle de Vollenweider (1968) : [P]_lac = L_P / (q_s × (1 + t_w^(1/2))), où L_P = charge en P (mg/m²/an), q_s = débit hydraulique spécifique (m/an), t_w = temps de résidence hydraulique. Les seuils trophiques : oligo < 10 μg P/L, meso 10-35, eutrophe 35-100, hypereutrophe > 100. Le modèle de Dillon-Rigler (Rp = coefficient de rétention du P dans le lac) améliore Vollenweider. Les actions de dephosphatation dans les STEP en amont ont réduit les charges en P de 70-90% en France (mesures DCE)." }
        ]},
        { titre: "Interactions biogéochimiques dans les zones hyporhéiques", sous_sections: [
          { titre: "Zone hyporhéique : définition et fonctions", contenu: "La zone hyporhéique est la zone d'interface entre les eaux de surface et les eaux souterraines, dans les sédiments alluviaux sous et autour du lit de la rivière. Elle est caractérisée par des gradients de température, d'O₂ et de concentration en nutriments. L'hyporheic exchange flow (HEF) est l'échange bidirectionnel entre la rivière et les alluvions. Fonctions biogéochimiques : nitrification des NH₄⁺ fluviaux, rétention des sédiments fins et des nutriments, réduction des NO₃⁻ (dénitrification en conditions anoxiques), épuration des eaux (autoépuration). La zone hyporhéique est un 'bioréacteur naturel' et un habitat crucial pour les macroinvertébrés et les stades larvaires des saumons." },
          { titre: "Autoépuration fluviale et demande en oxygène", contenu: "L'autoépuration est la dégradation naturelle de la matière organique dans les rivières par les bactéries aérobies. Elle consomme de l'O₂ → courbe d'oxygène (Streeter-Phelps, 1925) : dD/dt = k₁ × L - k₂ × D, où D = déficit en O₂ (DO_sat - DO), L = DBO résiduelle, k₁ = taux de déphosphatation, k₂ = taux de réaération. La DBO₅ (demande biologique en oxygène à 5 jours) est la mesure standard de la charge organique des eaux usées. Eau propre : DBO₅ < 3 mg/L. Eau de STEP non traitée : DBO₅ = 300-600 mg/L. La DBO ultime DBOU = 1,46 × DBO₅ (approximation). Le point critique (D_max) se produit en aval du rejet : c'est le point le plus pauvre en O₂." }
        ]}
      ],
      points: ["Monod : μ = μ_max × S/(K_s+S). Ordre 1 si S << K_s.", "Nitrification : NH₄⁺ → NO₃⁻, aérobie, Nitrosomonas/Nitrobacter.", "Dénitrification : NO₃⁻ → N₂, anaérobie, C organique requis.", "ANAMMOX : NH₄⁺ + NO₂⁻ → N₂, sans carbone, économie 60% O₂.", "Vollenweider : [P]_lac = L_P/(q_s × (1+√t_w)).", "Seuils eutrophisation : oligo < 10 μg P/L, eutrophe > 35 μg P/L.", "Zone hyporhéique : bioréacteur sous le lit fluvial, N et P retenus.", "Streeter-Phelps : courbe de déficit en O₂ après un rejet organique.", "DBO₅ = demande biologique en O₂ à 5 jours. Eau propre : < 3 mg/L.", "DT50 pesticides : cinétique ordre 1, demi-vie 10-500 j selon composé."],
      formules: [
        { nom: "Cinétique d'ordre 1", expression: "c(t) = c₀ × e^(-k × t)", variables: "k = constante cinétique (j⁻¹), t₁/₂ = ln2/k = 0,693/k" },
        { nom: "Cinétique de Monod", expression: "μ = μ_max × S / (K_s + S)", variables: "μ = taux de croissance (j⁻¹), K_s = constante de demi-saturation (mg/L), S = substrat (mg/L)" },
        { nom: "Modèle de Vollenweider (P dans les lacs)", expression: "[P]_lac = L_P / (q_s × (1 + √t_w))", variables: "L_P = charge en P (mg/m²/an), q_s = débit volumique/aire surface (m/an), t_w = temps résidence (an)" },
        { nom: "Équation de Streeter-Phelps (déficit O₂)", expression: "D(t) = (k₁ L₀)/(k₂-k₁) × (e^(-k₁t) - e^(-k₂t)) + D₀ e^(-k₂t)", variables: "D = déficit O₂ (mg/L), k₁ = déoxygénation, k₂ = réaération, L₀ = DBO initiale" },
        { nom: "Réaction ANAMMOX", expression: "NH₄⁺ + NO₂⁻ → N₂ + 2H₂O", variables: "Sans carbone externe. Économie 60% O₂ vs voie classique. Candidatus Brocadia" }
      ],
      retenir: "La cinétique de Monod décrit la croissance microbienne. L'ordre 1 s'applique aux dégradations chimiques (pesticides, radioactivité). La nitrification-dénitrification et l'anammox gouvernent le cycle de N. Vollenweider modélise le P des lacs. Streeter-Phelps décrit l'autoépuration. La zone hyporhéique est le bioréacteur naturel des rivières. La DBO₅ mesure la pollution organique."
    },
    exercices: [
      { id: 1, enonce: "DT50 d'un herbicide = 30 jours (ordre 1). Calculez k et la concentration après 90 jours si c₀ = 2 μg/L.", correction: "k = ln2/DT50 = 0,693/30 = 0,0231 j⁻¹. c(90) = 2 × e^(-0,0231×90) = 2 × e^(-2,079) = 2 × 0,125 = 0,250 μg/L. Soit 3 demi-vies → c₀/8 = 2/8 = 0,25 μg/L ✓. L'herbicide a perdu 87,5% de sa concentration après 90 jours." },
      { id: 2, enonce: "Monod : μ_max = 2 j⁻¹, K_s = 20 mg/L, S = 5 mg/L. Calculez μ.", correction: "μ = μ_max × S/(K_s+S) = 2 × 5/(20+5) = 10/25 = 0,4 j⁻¹. S << K_s : régime ordre 1 (μ ≈ μ_max/K_s × S = 0,1 j⁻¹/mg/L × 5 mg/L = 0,5 j⁻¹ ≈ 0,4 j⁻¹). La croissance est 5× plus lente que μ_max car le substrat est limitant." },
      { id: 3, enonce: "Un lac reçoit L_P = 500 mg P/m²/an, q_s = 10 m/an, t_w = 1 an. Calculez [P]_lac et son état trophique.", correction: "[P]_lac = L_P/(q_s × (1+√t_w)) = 500/(10 × (1+1)) = 500/20 = 25 μg P/L. 10 < 25 < 35 μg/L → lac mésotrophe (limite meso-eutrophe). Risque d'eutrophisation en été si les températures augmentent (algues favorisées). Pour atteindre l'état oligotrophe (< 10 μg/L), la charge L_P doit être réduite à : L_P = 10 × 20 = 200 mg P/m²/an (réduction de 60%)." },
      { id: 4, enonce: "Citez les avantages du procédé ANAMMOX par rapport à la dénitrification classique en STEP.", correction: "1. Pas de carbone externe (éthanol, méthanol) nécessaire → économie ~100% du coût de carbone (20-50 €/kg N éliminé). 2. Économie de 60% d'O₂ (seulement la nitritation partielle NH₄⁺→NO₂⁻ est aérobie, pas la réduction finale). 3. Production de boues réduite de 90% (biomasse anammox à croissance très lente). Inconvénients : bactéries anammox à croissance très lente (doublement 10-14 jours) → démarrage lent (3-6 mois), sensibilité aux températures < 15°C, aux NO₂⁻ élevés > 20 mg/L. Idéal pour les rejets chauds riches en NH₄⁺ (retours de déshydratation de boues en STEP)." },
      { id: 5, enonce: "Streeter-Phelps : rejet DBO₅ = 50 mg/L, débit rivière = 20 m³/s, débit rejet = 1 m³/s. L₀ et D₀ après mélange ?", correction: "Après mélange : L₀ = 50 × 1/(20+1) = 2,38 mg/L de DBO₅. DBO ultime : DBOU = L₀/0,68 = 3,50 mg/L (DBO₅ = 68% de DBOU). D₀ = DO_sat - DO_mélange. Si rivière : DO = 9 mg/L (DO_sat 20°C = 9,1 mg/L) → D₀ ≈ 0,1 mg/L. Le rejet dilué est faible → autoépuration rapide. Point critique : x km en aval selon k₁ et k₂." },
      { id: 6, enonce: "Expliquez la fonction de rétention des nutriments de la zone hyporhéique.", correction: "La zone hyporhéique (sédiments alluviaux sous le lit de la rivière) fonctionne comme un bioréacteur : l'eau fluviale s'infiltre dans les sédiments (hyporheic exchange flow) → contact avec les biofilms bactériens. Les processus biogéochimiques dans la zone hyporhéique : 1. Nitrification des NH₄⁺ fluviaux (conditions aérobies en surface des sédiments). 2. Dénitrification des NO₃⁻ (conditions anoxiques en profondeur des sédiments, réduction de NO₃⁻ → N₂). 3. Rétention du phosphore (adsorption sur les particules, précipitation de CaHPO₄). 4. Biodégradation de la matière organique (DBO). La zone hyporhéique peut réduire les concentrations en NO₃⁻ de 20-80% sur quelques mètres de transit." },
      { id: 7, enonce: "Citez les paramètres qui influencent k₁ (déoxygénation) et k₂ (réaération) dans le modèle de Streeter-Phelps.", correction: "k₁ (déoxygénation) influencé par : température (↑ 10°C → k₁ × 1,047^10 = ×1,58), nature de la matière organique (facilement biodégradable → k₁ élevé), concentration en bactéries. k₂ (réaération) influencé par : vitesse du courant (↑ vitesse → ↑ k₂), profondeur d'eau (↓ profondeur → ↑ k₂, plus grande surface relative), turbulence (obstacles, chutes). Rivière rapide peu profonde : k₂ = 0,5-1 j⁻¹ → autoépuration rapide. Rivière lente profonde : k₂ = 0,05-0,1 j⁻¹ → autoépuration lente → risque de déoxygénation forte." },
      { id: 8, enonce: "Un aquifère côtier reçoit des apports en NO₃⁻ agricoles (20 mg N-NO₃⁻/L). Citez les conditions nécessaires à la dénitrification naturelle dans l'aquifère.", correction: "Pour que la dénitrification se produise naturellement : 1. Conditions anaérobies : O₂ dissous < 0,5 mg/L (O₂ consommé par la matière organique ou la pyrite). 2. Source de carbone organique (DOC > 1 mg/L) : troncs enfouis, tourbe, matière organique des sédiments → donneur d'électrons pour les bactéries dénitrifiantes. 3. Présence de bactéries dénitrifiantes (ubiquistes). 4. Température > 5°C (cinétique suffisante). 5. Temps de contact suffisant (aquifère confiné, temps de résidence > quelques semaines). En pratique : certains aquifères alluviaux contenant du bois organique dénitrifient spontanément. Les barrières réactives carbonées (bois, compost) stimulent la dénitrification artificielle." }
    ],
    flashcards: [
      { question: "Cinétique de Monod : sens et limites", reponse: "μ = μ_max × S/(K_s+S). Modèle empirique de croissance microbienne. K_s = substrat pour μ = μ_max/2. S >> K_s : ordre 0, μ ≈ μ_max (substrat non limitant). S << K_s : ordre 1, μ ≈ (μ_max/K_s) × S. Utilisé dans les modèles de STEP (boues activées, ASM1-3), les modèles de biodégradation en aquifère, les bioréacteurs. Limitation : un seul substrat limitant, pas de toxicité, pas de compétition inter-espèces." },
      { question: "Nitrification : étapes et conditions", reponse: "Nitritation : NH₄⁺ + 1,5O₂ → NO₂⁻ + H₂O + 2H⁺ (Nitrosomonas). Nitritation : NO₂⁻ + 0,5O₂ → NO₃⁻ (Nitrobacter). Conditions : aérobie (DO > 2 mg/L), T = 20-30°C optimal (< 10°C ralentit fortement), pH = 7-8, temps de rétention de boues ≥ 10 jours (bactéries lentes). Consomme 4,57 g O₂/g N-NH₄ et 7,14 g alcalinité/g N-NH₄. Appliqué en STEP biologiques (tranche nitrification en 2ème étage ou procédé SBR)." },
      { question: "Modèle de Vollenweider : P dans les lacs", reponse: "[P]_lac = L_P/(q_s×(1+√t_w)). L_P = charge surfacique (mg/m²/an). q_s = taux de charge hydraulique = débit/aire (m/an). t_w = temps de résidence hydraulique (an). Prédit la concentration en P à l'équilibre. Utile pour évaluer l'impact d'une réduction des charges (STEP, agriculture). Seuils : < 10 μg/L oligotrophe, > 35 μg/L eutrophe. Amélioration : modèle de Dillon-Rigler (coefficient de rétention R_p)." },
      { question: "Zone hyporhéique : définition et rôle", reponse: "Zone d'échange entre eaux de surface et souterraines dans les sédiments alluviaux (sous et autour du lit de la rivière). Caractérisée par un gradient de T (moins variable que la rivière), O₂ variable (aérobie surface, anoxie profondeur). Fonctions : nitrification des NH₄⁺ fluviaux, dénitrification des NO₃⁻, rétention du P, dégradation de la MO, habitat pour macroinvertébrés, nurserie des salmonidés. 'Rein de la rivière'. Perturbé par le colmatage des sédiments (fines) et les bétonnages de berges." },
      { question: "DBO₅ et courbe de Streeter-Phelps", reponse: "DBO₅ = O₂ consommé à 5 jours (20°C) pour dégrader la MO : indicateur standard de la pollution organique. Eau propre < 3 mg/L. STEP sortie < 25 mg/L (norme FR). Effluent brut 300-600 mg/L. Streeter-Phelps : courbe en creux d'O₂ aval d'un rejet. D = DO_sat - DO. Max D = point critique (le plus pauvre en O₂). k₁ = déoxygénation. k₂ = réaération (dépend de la vitesse et de la profondeur). Modèle de base pour les études d'impact des rejets sur les rivières." }
    ]
  },

  'MASTER-EAU-071': {
    id: 'MASTER-EAU-071',
    titre: 'Stratégies analytiques et assurance qualité',
    fiche: {
      intro: "La production de données analytiques fiables sur la qualité des eaux requiert une démarche d'assurance qualité (AQ) rigoureuse, depuis le prélèvement sur le terrain jusqu'à l'interprétation statistique. Les méthodes de référence (norme ISO, AFNOR), les protocoles d'étalonnage, les blancs, les duplicats et les contrôles de qualité internes/externes forment le socle de toute analyse chimique accréditée.",
      sections: [
        { titre: "Méthodes d'analyse de la qualité des eaux", sous_sections: [
          { titre: "Paramètres de terrain et analyses in situ", contenu: "Les paramètres mesurés sur le terrain (in situ) sont : pH (électrode de verre, précision ±0,05 unité), conductivité électrique (mesure de la force ionique, corrélation avec TDS), O₂ dissous (sonde optique ou à membrane polarographique, précision ±0,1 mg/L), température (thermocouple, précision ±0,1°C), turbidité (NTU, sonde optique à 90°), potentiel redox Eh (électrode Pt). La séquence de mesure sur le terrain : pH, conductivité et O₂ d'abord (paramètres instables), puis Eh, turbidité. Les sondes multiparamètres (YSI, Hach, Hydrolab) mesurent tous ces paramètres simultanément et enregistrent en continu. La calibration sur le terrain est indispensable (solutions tampons pH, standards de conductivité)." },
          { titre: "Méthodes de laboratoire standard", contenu: "Les méthodes d'analyse de l'eau en laboratoire suivent des normes NF EN ISO publiées par l'AFNOR et l'ISO. Principaux paramètres et méthodes : NO₃⁻ (chromatographie ionique, ISO 10304-1 ou réduction cadmium + colorimétrie, NF EN ISO 13395), NH₄⁺ (colorimétrie manuelle ou automatique, NF T90-015), PO₄³⁻ (bleu de molybdène, NF EN ISO 6878), DBO₅ (dilution + incubation 5j, NF EN 1899), DCO (dichromate oxydation, NF T90-101), métaux (ICP-MS ou ICP-AES, NF EN ISO 17294), COT (oxidation/IR, NF EN 1484). La chromatographie ionique (CI) est la méthode de référence pour les anions (NO₃⁻, SO₄²⁻, Cl⁻, F⁻, PO₄³⁻)." }
        ]},
        { titre: "Assurance qualité analytique", sous_sections: [
          { titre: "Blanc, étalon et contrôle de qualité interne", contenu: "Les éléments de contrôle qualité internes indispensables : Blanc de réactif : eau ultra-pure traitée comme l'échantillon → mesure les contaminations par les réactifs. Blanc de terrain : eau ultra-pure emportée sur le terrain et traitée comme les échantillons → mesure les contaminations lors du prélèvement et du transport. Solution d'étalonnage : standards certifiés à concentrations connues pour calibrer la méthode et vérifier la linéarité. CIQ (Contrôle Interne de Qualité) : échantillon de matrice préparé en interne, analysé en début et fin de série → vérification de la dérive de l'instrument. Duplicat : deux analyses du même échantillon → calcul de la précision (CV = écart-type/moyenne × 100, objectif < 10%)." },
          { titre: "Accréditation COFRAC et incertitude de mesure", contenu: "En France, les laboratoires qui réalisent des analyses réglementaires (contrôle sanitaire AEP, surveillance DCE) doivent être accrédités COFRAC (Comité Français d'Accréditation, norme ISO/IEC 17025). L'accréditation certifie la compétence technique (méthodes validées, étalonnage, personnel qualifié) et la fiabilité des résultats. Chaque résultat analytique doit être accompagné de son incertitude de mesure (U, généralement à k=2 soit 95% de confiance). L'incertitude est estimée selon le guide GUM (Guide to the Expression of Uncertainty in Measurement, ISO). Pour NO₃⁻ par CI : U ≈ ±5-10% (k=2). Pour les métaux en traces par ICP-MS : U ≈ ±10-20%." }
        ]},
        { titre: "Prélèvement et conservation des échantillons", sous_sections: [
          { titre: "Protocoles de prélèvement et filtration", contenu: "Le prélèvement est l'étape la plus critique de l'analyse. Pour les métaux en traces : rincer 3 fois le flacon avec l'eau du site, utiliser des flacons HDPE pré-acidifiés, filtrer sur 0,45 μm (Millipore) pour séparer le dissous du particulaire, acidifier à HNO₃ ultrapure (pH < 2) pour conserver les métaux. Pour les nutriments : filtration sur 0,45 μm, congélation (-18°C) si > 24h de délai. Pour les composés volatils (COV) : flacon à col étroit avec bouchon teflon hermétique, sans espace d'air, pas de filtration, conservation à 4°C, analyse < 14j. L'échantillon composite (mélange de prélèvements sur 24h) est utilisé pour les STEP, l'échantillon spot (instantané) pour les rivières." },
          { titre: "Conservation et délais d'analyse", contenu: "Les délais de conservation des échantillons d'eau (après prélèvement, NF EN ISO 5667) : pH, O₂, CO₂ : mesure immédiate sur le terrain. NO₃⁻, NO₂⁻ : filtration + congélation (-18°C), 7 jours. PO₄³⁻ : filtration + H₂SO₄ pH < 2, 24h (sans acide : 24h à 4°C). NH₄⁺ : H₂SO₄ pH < 2, 7 jours. DBO₅ : 4°C, 24h (maximum 48h). DCO : H₂SO₄ pH < 2, 7 jours. Métaux : HNO₃ pH < 2, 1-6 mois selon le métal. COT : H₃PO₄ pH < 2, 7 jours. Le non-respect des délais est la première cause de résultats erronés dans les analyses de terrain." }
        ]},
        { titre: "Interprétation statistique des données de qualité de l'eau", sous_sections: [
          { titre: "Tests statistiques et tendances temporelles", contenu: "L'analyse statistique des séries chronologiques de qualité de l'eau utilise : tests paramétriques (Student, ANOVA) si les données suivent une distribution normale (test de Shapiro-Wilk ou Kolmogorov-Smirnov préalable). Tests non-paramétriques (Mann-Whitney, Kruskal-Wallis) si non normale. Détection de tendances : test de Mann-Kendall (non-paramétrique, robust aux valeurs aberrantes) pour détecter une tendance croissante ou décroissante dans une série temporelle (trend analysis). Estimation de la magnitude : test de Sen's slope (pente médiane). Ces méthodes sont les standards des réseaux de surveillance DCE (Water Framework Directive) pour l'évaluation des tendances des nitrates, des pesticides et des métaux dans les masses d'eau." },
          { titre: "Valeurs aberrantes, limites de quantification et données censurées", contenu: "La limite de détection (LD, LOD) est la plus petite concentration distinguable du blanc (3σ_blanc). La limite de quantification (LQ, LOQ) = 10σ_blanc. Les données sous la LQ (< LOQ) sont des données censurées. Méthodes statistiques pour les données censurées : substitution par LOQ/2 (simple mais biaisé), méthode de Kaplan-Meier (non-paramétrique), régression sur ordre normal. Les valeurs aberrantes sont identifiées par la boîte à moustaches (boxplot) : valeur > Q3 + 1,5×IQR ou < Q1 - 1,5×IQR. La méthode de Grubbs ou de Dixson teste statistiquement l'appartenance d'une valeur à la distribution. La vérification de la balance ionique (Σcations = Σanions en meq/L, erreur < 5%) est un contrôle qualité de base sur les analyses d'eau complètes." }
        ]}
      ],
      points: ["pH, O₂, conductivité : mesure obligatoire sur le terrain (instables).", "ISO 17025 (COFRAC) : accréditation obligatoire pour les analyses réglementaires.", "Blanc de réactif, blanc terrain, CIQ, duplicat : contrôle qualité interne.", "NO₃⁻ par CI : U ≈ ±5-10%. Métaux ICP-MS : U ≈ ±10-20%.", "Délais conservation : DBO₅ 24h, NO₂⁻ 7j (congelé), métaux 1-6 mois (HNO₃).", "LQ = 10σ_blanc. Données sous LQ = données censurées.", "Mann-Kendall : test non-paramétrique de tendance temporelle (DCE).", "Balance ionique : Σcat = Σanions en meq/L, erreur < 5%.", "Données censurées : méthode Kaplan-Meier ou substitution LOQ/2.", "Sen's slope : estimation de la pente médiane d'une tendance temporelle."],
      formules: [
        { nom: "Limite de détection (LD)", expression: "LD = 3 × σ_blanc",  variables: "σ_blanc = écart-type des mesures de blanc. LQ = 10 × σ_blanc" },
        { nom: "Coefficient de variation (précision)", expression: "CV = (s / x̄) × 100",  variables: "s = écart-type des réplicats, x̄ = moyenne. CV < 10% acceptable, < 5% bon" },
        { nom: "Balance ionique (vérification)", expression: "BE = (Σcat - Σan) / (Σcat + Σan) × 100",  variables: "Somme en meq/L. BE < ±5% : analyse acceptable. BE > ±10% : erreur analytique probable" },
        { nom: "Incertitude composée (GUM)", expression: "U_composée = k × √(u₁² + u₂² + ... + uₙ²)",  variables: "uᵢ = contributions d'incertitude individuelles, k = facteur de couverture (k=2 pour 95% confiance)" },
        { nom: "Droite d'étalonnage (régression linéaire)", expression: "y = a × x + b, r² = (Σ(x-x̄)(y-ȳ))² / [Σ(x-x̄)² Σ(y-ȳ)²]",  variables: "r² > 0,999 requis pour une bonne linéarité. a = pente, b = ordonnée à l'origine" }
      ],
      retenir: "La qualité analytique repose sur : protocoles de prélèvement, conservation, blancs de réactif et de terrain, étalonnage, CIQ, duplicats. L'accréditation COFRAC (ISO 17025) est obligatoire pour les analyses réglementaires. La balance ionique vérifie la cohérence d'une analyse complète. Mann-Kendall détecte les tendances dans les séries chronologiques. Les données sous la LQ sont censurées et traitées par des méthodes spécifiques."
    },
    exercices: [
      { id: 1, enonce: "Analyse d'eau : Ca²⁺ = 2,8 mmol/L, Mg²⁺ = 1,2 mmol/L, Na⁺ = 0,5 mmol/L, K⁺ = 0,1 mmol/L, HCO₃⁻ = 5,8 meq/L, SO₄²⁻ = 0,8 mmol/L, Cl⁻ = 1,0 mmol/L. Calculez la balance ionique.", correction: "Cations (meq/L) : Ca²⁺ = 2,8×2 = 5,6, Mg²⁺ = 1,2×2 = 2,4, Na⁺ = 0,5×1 = 0,5, K⁺ = 0,1×1 = 0,1. Σcat = 8,6 meq/L. Anions (meq/L) : HCO₃⁻ = 5,8, SO₄²⁻ = 0,8×2 = 1,6, Cl⁻ = 1,0×1 = 1,0. Σan = 8,4 meq/L. BE = (8,6-8,4)/(8,6+8,4) × 100 = 0,2/17,0 × 100 = 1,2%. BE < 5% → analyse acceptable." },
      { id: 2, enonce: "Blanc analysé 10 fois : σ = 0,0015 mg/L NO₃⁻-N. Calculez LD et LQ. Un échantillon donne 0,008 mg/L. Que concluez-vous ?", correction: "LD = 3 × σ = 3 × 0,0015 = 0,0045 mg/L. LQ = 10 × σ = 0,015 mg/L. Échantillon = 0,008 mg/L. LD < 0,008 < LQ → signal détecté mais non quantifiable de façon fiable. Cette valeur doit être reportée comme '< LQ' (0,015 mg/L) ou '0,008 mg/L (< LQ)' selon le protocole. Elle ne peut pas être utilisée pour des calculs statistiques sans méthode adaptée aux données censurées." },
      { id: 3, enonce: "Duplicat d'un échantillon NO₃⁻ : 15,2 et 16,4 mg/L. Calculez le CV et évaluez la précision.", correction: "Moyenne = (15,2+16,4)/2 = 15,8 mg/L. Écart = 16,4-15,2 = 1,2 mg/L. s = 1,2/√2 = 0,849. CV = 0,849/15,8 × 100 = 5,37%. CV ≈ 5% : précision acceptable pour la plupart des applications, à la limite supérieure de l'objectif (<5% pour les méthodes de référence). Vérifier si le duplicat est fait en analyse (duplicat analytique) ou en prélèvement (duplicat terrain). Pour un duplicat analytique, CV < 5% est l'objectif standard." },
      { id: 4, enonce: "Citez 4 erreurs possibles lors du prélèvement d'un échantillon d'eau pour l'analyse des métaux en traces.", correction: "1. Contamination du flacon (rinçage insuffisant avec l'eau du site avant prélèvement → apport de métaux des prélèvements précédents). 2. Contact avec l'atmosphère (aération → oxydation de Fe²⁺ → précipitation de Fe(OH)₃ → co-précipitation d'autres métaux → perte). 3. Oubli de filtration sur 0,45 μm → matière en suspension avec métaux adsorbés inclus (mesure de métal total ≠ métal dissous). 4. Oubli d'acidification → métaux adsorbés sur les parois du flacon à pH neutre → perte progressive. 5. (bonus) Contamination par les mains (Pb, Zn de la transpiration) ou par les matériaux des seringues (Si, Al)." },
      { id: 5, enonce: "Le test de Mann-Kendall sur une série de NO₃⁻ mensuelle sur 10 ans donne p = 0,02. Que signifie ce résultat ?", correction: "p = 0,02 < 0,05 (seuil de signification standard). La tendance détectée est statistiquement significative au niveau 5%. La série temporelle de NO₃⁻ présente une tendance (croissante ou décroissante) qui n'est pas due au hasard. Pour connaître le sens (hausse ou baisse) : regarder le signe de la statistique S de Mann-Kendall (S > 0 = tendance à la hausse). La pente de la tendance est estimée par Sen's slope (médiane des pentes entre toutes les paires de points). Ce résultat doit être interprété en lien avec les pressions agricoles, les changements climatiques et les mesures de réduction des intrants dans le bassin versant." },
      { id: 6, enonce: "Citez les avantages de la chromatographie ionique (CI) pour l'analyse des anions dans les eaux.", correction: "1. Analyse simultanée de tous les anions inorganiques (F⁻, Cl⁻, NO₂⁻, NO₃⁻, PO₄³⁻, SO₄²⁻) en une seule injection de 20-30 min. 2. Sensibilité élevée (LQ = 0,01-0,1 mg/L selon l'ion et la colonne). 3. Faible volume d'échantillon (25-100 μL). 4. Haute sélectivité (séparation chromatographique évite les interférences). 5. Automatisable (injecteur automatique, traitement des données logiciel). 6. Méthode de référence normée ISO 10304. Limitation : ne mesure pas les anions organiques (acétate, oxalate) sans colonne spécifique, et ne convient pas aux échantillons très chargés en matrice organique (dilution nécessaire)." },
      { id: 7, enonce: "Qu'est-ce que l'accréditation COFRAC ISO 17025 et pourquoi est-elle nécessaire pour les analyses de surveillance de l'eau potable ?", correction: "ISO 17025 = norme internationale sur la compétence des laboratoires d'essais et d'étalonnage. COFRAC = Comité Français d'Accréditation (organisme national). L'accréditation certifie que le laboratoire : utilise des méthodes validées et normées, maintient ses équipements étalonnés, forme et qualifie son personnel, réalise des CIQ réguliers, participe à des essais inter-laboratoires (EIL), peut calculer et déclarer ses incertitudes de mesure. Obligation réglementaire en France (décret 2007 sur l'AEP) pour tous les laboratoires qui font des analyses dans le cadre du contrôle sanitaire ou de la surveillance DCE. Garantit la comparabilité des résultats entre laboratoires et la confiance des décisions réglementaires." },
      { id: 8, enonce: "Données sous la LQ pour le Pb²⁺ dans une série de 20 analyses : 15 résultats < LQ (0,5 μg/L). Comment calculer la concentration moyenne ?", correction: "15/20 = 75% de données censurées → ne pas utiliser la substitution LOQ/2 (trop biaisée pour > 50% de données censurées). Méthodes adaptées : 1. Méthode de Kaplan-Meier (non-paramétrique) : calcule la distribution empirique en tenant compte de la censure → estimateur robuste de la médiane et des percentiles. 2. Régression sur ordre normal (ROS) : ajuste une distribution log-normale ou normale aux données non-censurées pour estimer les données censurées. 3. Maximum Likelihood Estimation (MLE) : ajuste une loi statistique sur les données observées. Pour 75% de données censurées, la médiane est de toute façon < LQ. Rapporter [Pb] médiane < 0,5 μg/L (non quantifiable de façon fiable)." }
    ],
    flashcards: [
      { question: "Paramètres à mesurer sur le terrain : pourquoi ?", reponse: "pH, O₂ dissous, conductivité, T, Eh : doivent être mesurés immédiatement sur le terrain car ils évoluent rapidement après le prélèvement (dégazage CO₂ → ↑ pH; dissolution O₂ atmosphérique ou désorption → ↑ ou ↓ DO; dissolution ou précipitation de CaCO₃; oxydation de Fe²⁺). Délai maximal : 15 min pour pH, 30 min pour DO (sinon en flacon hermétique avec sonde). La turbidité peut aussi être mesurée sur le terrain pour les décisions de filtration." },
      { question: "Balance ionique : principe et critère d'acceptation", reponse: "BE = (Σcat - Σan)/(Σcat + Σan) × 100. Sommes en meq/L. BE = 0 : équilibre électroneutralité respecté. BE < ±5% : analyse acceptable (erreur analytique normale). BE 5-10% : vérifier les ions manquants (NH₄⁺, Fe²⁺ en eaux réductrices, Al³⁺ en eaux acides). BE > 10% : erreur analytique probable → reanalyse. Vérification systématique sur les analyses d'eau complètes (hydrogéologie, qualité, traitement)." },
      { question: "Blanc de réactif, blanc de terrain, CIQ", reponse: "Blanc de réactif : eau ultra-pure + réactifs → mesure les contaminations chimiques des réactifs. Blanc de terrain : eau ultra-pure + manipulation identique aux échantillons → mesure les contaminations lors du prélèvement et transport. CIQ (Contrôle Interne de Qualité) : solution à concentration connue préparée en interne → vérification quotidienne de la dérive et de la précision. Critères : CIQ dans ±10% de la valeur attendue. Duplicat : CV < 5-10%. Ces éléments sont obligatoires pour l'accréditation COFRAC." },
      { question: "Mann-Kendall test : principe et usage", reponse: "Test non-paramétrique de tendance monotone dans une série temporelle. Hypothèse H₀ : pas de tendance. Statistique S = nombre de paires croissantes - paires décroissantes. p < 0,05 : tendance significative. Avantages : non-paramétrique (pas d'hypothèse de normalité), robuste aux valeurs aberrantes et aux données manquantes, applicable aux données censurées. Utilisé par les agences de l'eau (DCE) pour l'évaluation des tendances des nitrates, pesticides et métaux dans les masses d'eau. Sen's slope : pente médiane (robuste)." },
      { question: "LQ, LD et données censurées", reponse: "LD = 3σ_blanc (limite de détection). LQ = 10σ_blanc (limite de quantification). Données < LQ : données censurées (valeur détectée mais pas quantifiable de façon fiable). Problème statistique : on sait que x < LQ mais on ne connaît pas x. Méthodes : substitution LOQ/2 (si < 15% de censure), Kaplan-Meier (si > 50% de censure), MLE ou ROS pour les cas intermédiaires. Ne jamais substituer 0 ou mettre la valeur dans la moyenne sans traitement. Standard EPA et DCE pour les données de surveillance." }
    ]
  }

,

  'MASTER-EAU-072': {
    id: 'MASTER-EAU-072',
    titre: 'Qualité des eaux naturelles et signatures géochimiques',
    fiche: {
      intro: "La chimie des eaux naturelles (fluviales, lacustres, souterraines, marines) reflète les processus géochimiques qui ont façonné leur composition : altération des roches, échanges atmosphériques, processus biologiques et apports anthropiques. Les signatures géochimiques (isotopiques, ioniques, moléculaires) permettent de tracer l'origine des eaux et d'identifier les processus qui les contrôlent.",
      sections: [
        { titre: "Composition ionique des eaux naturelles", sous_sections: [
          { titre: "Principaux ions majeurs et leur origine", contenu: "Les ions majeurs des eaux naturelles (> 1 mg/L) sont : Ca²⁺, Mg²⁺, Na⁺, K⁺ (cations), HCO₃⁻, SO₄²⁻, Cl⁻ (anions). Origine des ions : Ca²⁺ et HCO₃⁻ proviennent de l'altération des carbonates (calcite CaCO₃ + CO₂ + H₂O → Ca²⁺ + 2HCO₃⁻) et des feldspaths calco-sodiques. Ca²⁺ et Mg²⁺ aussi de l'altération des silicates magnésiens (olivines, pyroxènes). Na⁺ et Cl⁻ : halite (NaCl) et apports atmosphériques (sels marins). SO₄²⁻ : altération de la pyrite (FeS₂ + 3,75 O₂ + 2,5 H₂O → Fe²⁺ + 2SO₄²⁻ + 4H⁺) et évaporites (gypse CaSO₄). Le diagramme de Piper (triangles ternaires + losange) représente la composition en ions majeurs de nombreuses eaux pour classer les faciès hydrochimiques." },
          { titre: "Classification des faciès hydrochimiques (Piper, Stiff)", contenu: "Le diagramme de Piper est l'outil graphique de référence pour la classification des eaux. Il combine deux triangles ternaires (cations Ca-Mg-Na+K, anions HCO₃-SO₄-Cl) et un losange central. Chaque point du losange représente le faciès global d'une eau. Faciès bicarbonaté calcique (eaux douces de karsts et calcaires) : Ca-HCO₃. Faciès chloruré sodique (eaux marines, eaux très évoluées) : Na-Cl. Faciès sulfaté calcique (gypse, eaux industrielles) : Ca-SO₄. Le diagramme de Stiff représente une eau individuelle par un hexagone dont les branches sont proportionnelles aux concentrations en meq/L. L'évolution hydrochimique des eaux souterraines suit le chemin de Chebotarev : Ca-HCO₃ → Ca-SO₄ → Na-Cl en augmentant la profondeur et l'âge." }
        ]},
        { titre: "Signatures isotopiques des eaux naturelles", sous_sections: [
          { titre: "Isotopes stables de l'eau : δ¹⁸O et δD", contenu: "L'eau (H₂O) comporte des isotopes stables : ¹H, ²H (D = deutérium), ¹⁶O, ¹⁸O. Les rapports isotopiques se mesurent en notation δ : δ¹⁸O (‰) = (R_échantillon/R_VSMOW - 1) × 1000, où R = ¹⁸O/¹⁶O, VSMOW = eau de mer standard. La droite des eaux météoriques mondiales (Global Meteoric Water Line, Craig 1961) : δD = 8 × δ¹⁸O + 10. Les eaux de pluie deviennent plus négatives avec l'altitude (effet d'altitude : -0,15 à -0,5 ‰ δ¹⁸O/100 m), la latitude et la continentalité. L'évaporation enrichit les eaux en ¹⁸O et D → déplacement vers des δ positifs, sous-dessous de la GMWL. Ces signatures permettent de dater et tracer les eaux souterraines, identifier les mélanges et détecter les recharges fossiles." },
          { titre: "Isotopes radioactifs : tritium, C-14, He-3", contenu: "Le tritium (³H, T) : isotope radioactif de l'hydrogène, T₁/₂ = 12,3 ans. Produit naturellement (réaction cosmique N + n → ³H) et par les essais nucléaires atmosphériques (pic en 1963, 1000 TU). Traceur des eaux récentes (< 50 ans). ³H > 0,1 TU = eau post-1950. ³H = 0 = eau ancienne (> 100 ans). Le carbone-14 (¹⁴C, T₁/₂ = 5730 ans) date les eaux souterraines jusqu'à ~40 000 ans. L'activité initiale A₀ = 100 pmc (percent modern carbon) est modifiée par l'échange isotopique avec les carbonates de la matrice. L'He-3 (fils du tritium) et l'³H/³He permettent de dater précisément les eaux jeunes (1-100 ans). Le CF3 (chlorofluorocarbures) et le SF6 datent les eaux des dernières décennies." }
        ]},
        { titre: "Signatures géochimiques des eaux souterraines", sous_sections: [
          { titre: "Évolution hydrochimique et chemin de Chebotarev", contenu: "Les eaux souterraines évoluent chimiquement le long de leur trajet dans l'aquifère (augmentation de TDS, minéralisation croissante). Le chemin de Chebotarev décrit la succession des faciès hydrochimiques avec la profondeur : eaux jeunes → faciès Ca-HCO₃ (altération des carbonates) ; eaux intermédiaires → faciès Ca-SO₄ ou Na-HCO₃ ; eaux profondes → faciès Na-Cl (lessivage des évaporites, échanges ioniques). La concentration en Cl⁻ augmente régulièrement avec le temps de résidence (Cl⁻ est un traceur conservatif). Le rapport Cl/Br est un traceur de la source des chlorures (halite : Cl/Br ≈ 10 000, eau de mer : Cl/Br ≈ 300, eaux météoriques : Cl/Br variable)." },
          { titre: "Traceurs d'origine anthropique dans les eaux naturelles", contenu: "Les indicateurs de contamination anthropique dans les eaux naturelles incluent : NO₃⁻ (agriculture, eaux usées ; signal δ¹⁵N distinctif pour les engrais vs déjections animales), NH₄⁺ (anaérobie, eaux usées), PO₄³⁻ (détergents, engrais), Cl⁻ (NaCl de déneigement, eaux usées), δ¹³C de la matière organique dissoute (C3 vs C4 végétales). Les isotopes du bore (δ¹¹B) distinguent les apports agricoles (borates des engrais) des eaux usées. Les isotopes du soufre (δ³⁴S) tracent les sources de SO₄²⁻. Le rapport nitrate-15N isotopique (δ¹⁵N-NO₃⁻) : engrais chimiques δ¹⁵N = 0-5‰, déjections animales δ¹⁵N = 10-25‰, effluents d'eaux usées δ¹⁵N = 10-30‰." }
        ]},
        { titre: "Qualité des eaux fluviales et lacustres", sous_sections: [
          { titre: "Paramètres de qualité physico-chimique des cours d'eau", contenu: "La qualité physico-chimique des cours d'eau est décrite par les paramètres : T (°C), O₂ dissous (mg/L ou % sat.), pH, conductivité (μS/cm), turbidité (NTU), DBO₅, DCO, NO₃⁻, NO₂⁻, NH₄⁺, PO₄³⁻, MES (mg/L). La norme DCE classe les masses d'eau de surface en 5 états (très bon, bon, moyen, médiocre, mauvais) selon les paramètres biologiques (phytoplancton, macrophytes, diatomées, macroinvertébrés, poissons) et physico-chimiques (NH₄⁺, PO₄³⁻, O₂, pH, T). La grille de qualité SEQ-Eau (ancienne méthode FR, remplacée par la DCE) évaluait l'aptitude aux usages (AEP, loisirs, irrigation, vie aquatique). L'objectif de bon état écologique et chimique doit être atteint au plus tard en 2027 en France (DCE 2000)." },
          { titre: "Chimie des lacs et stratification thermique", contenu: "Les lacs se stratifient thermiquement en été (épilimnion chaud + thermocline + hypolimnion froid). La stratification contrôle la chimie : l'hypolimnion devient anoxique (O₂ consommé par la dégradation de la MO sédimentée) → conditions réductrices → Fe²⁺ et Mn²⁺ libérés des sédiments (réduction de FeOOH et MnO₂) → PO₄³⁻ libéré (car l'adsorption sur FeOOH disparaît) → eutrophisation interne (charge interne). Le brassage automnal (refroidissement de l'épilimnion → homogénéisation de la colonne d'eau) ramène Fe²⁺, Mn²⁺ et NH₄⁺ vers la surface. La chimie du lac résulte d'un bilan entrées-sorties en nutriments et d'un bilan biogéochimique interne (production primaire, respiration, sédimentation)." }
        ]}
      ],
      points: ["Faciès Ca-HCO₃ : eaux douces de karsts. Na-Cl : eaux profondes, marines.", "Piper diagram : deux triangles ternaires + losange pour classer les faciès.", "GMWL : δD = 8 × δ¹⁸O + 10. Traceur météorique universel.", "Effet altitude : δ¹⁸O diminue de -0,15 à -0,5 ‰/100 m.", "Tritium (T₁/₂ = 12,3 ans) : traceur des eaux récentes. ³H > 0,1 TU = post-1950.", "¹⁴C (T₁/₂ = 5730 ans) : datation eaux souterraines jusqu'à 40 000 ans.", "Chemin de Chebotarev : Ca-HCO₃ → Ca-SO₄ → Na-Cl en profondeur.", "Cl/Br : halite ≈ 10 000, eau de mer ≈ 300. Traceur de sources de chlorures.", "δ¹⁵N-NO₃⁻ : engrais chimiques 0-5 ‰, déjections animales 10-25 ‰.", "Stratification thermique lacs : hypolimnion anoxique → charge interne en PO₄."],
      formules: [
        { nom: "Notation δ isotopique", expression: "δ (‰) = (R_éch / R_std - 1) × 1000", variables: "R = rapport isotopique (ex: ¹⁸O/¹⁶O). Standard : VSMOW pour O et H, VPDB pour C" },
        { nom: "Droite des eaux météoriques mondiales (GMWL)", expression: "δD = 8 × δ¹⁸O + 10 (‰)", variables: "Craig (1961). Pente 8 : fractionnement cinétique. Deuterium excess d = δD - 8 δ¹⁸O ≈ 10" },
        { nom: "Décroissance radioactive (tritium, ¹⁴C)", expression: "A(t) = A₀ × e^(-λt), λ = ln2/T₁/₂", variables: "T₁/₂(³H) = 12,3 ans; T₁/₂(¹⁴C) = 5730 ans. Âge : t = -ln(A/A₀)/λ" },
        { nom: "Altération des carbonates", expression: "CaCO₃ + CO₂ + H₂O → Ca²⁺ + 2HCO₃⁻", variables: "Réaction principale de dissolution des calcaires (karsts, aquifères crayeux)" },
        { nom: "Balance ionique", expression: "BE (%) = (Σcat - Σan) / (Σcat + Σan) × 100", variables: "Sommes en meq/L. BE < 5% : analyse acceptable. Vérification de cohérence analytique" }
      ],
      retenir: "Les signatures ioniques (Piper) et isotopiques (δ¹⁸O, δD, tritium, ¹⁴C) permettent de classer les eaux, tracer leur origine et les dater. Le chemin de Chebotarev décrit l'évolution hydrochimique des eaux souterraines. La GMWL est la référence des eaux météoriques. Les isotopes du N tracent les sources de nitrates. La stratification thermique des lacs génère une charge interne en phosphore."
    },
    exercices: [
      { id: 1, enonce: "Eau avec Ca²⁺ = 3 meq/L, Mg²⁺ = 1 meq/L, Na⁺ = 0,5 meq/L, HCO₃⁻ = 4 meq/L, SO₄²⁻ = 0,8 meq/L, Cl⁻ = 0,3 meq/L. Quel est le faciès hydrochimique ?", correction: "Cations dominants : Ca²⁺ = 3/(3+1+0,5) × 100 = 66% → Ca dominant. Anions dominants : HCO₃⁻ = 4/(4+0,8+0,3) × 100 = 78% → HCO₃⁻ dominant. Faciès : Ca-HCO₃ (bicarbonaté calcique). Ce faciès est typique des eaux douces de calcaires et de karsts, avec altération dominante CaCO₃ + CO₂ → Ca²⁺ + 2HCO₃⁻. Balance ionique : Σcat = 4,5 meq/L, Σan = 5,1 meq/L, BE = (4,5-5,1)/9,6 × 100 = -6,25%. BE légèrement au-delà de 5% → vérifier si SiO₂ ou K⁺ manquant." },
      { id: 2, enonce: "δ¹⁸O d'une eau de pluie = -8 ‰. Station météo à 400 m d'altitude. Estimez δ¹⁸O à 1200 m (gradient -0,3 ‰/100 m).", correction: "Différence d'altitude : 1200 - 400 = 800 m. Correction isotopique : Δδ¹⁸O = -0,3 × (800/100) = -2,4 ‰. δ¹⁸O à 1200 m = -8 - 2,4 = -10,4 ‰. Cette valeur négative plus forte reflète un fractionnement plus important lors de la condensation à haute altitude (températures plus froides → enrichissement préférentiel en ¹⁶O dans la vapeur condensée). Cette méthode est utilisée pour estimer la zone de recharge des sources de montagne et des aquifères karstiques." },
      { id: 3, enonce: "Tritium d'une eau souterraine = 1,2 TU. L'activité atmosphérique actuelle est de 2 TU. Estimez l'âge en utilisant la décroissance simple.", correction: "Activité initiale A₀ = 2 TU (eau récente en équilibre avec l'atmosphère). Activité mesurée A = 1,2 TU. λ(³H) = ln2/12,3 = 0,0564 an⁻¹. Âge : t = -ln(A/A₀)/λ = -ln(1,2/2)/0,0564 = -ln(0,6)/0,0564 = 0,511/0,0564 = 9,0 ans. L'eau a environ 9 ans. Interprétation : eau très récente, rechargée dans les années 2010. Attention : cette estimation est simplifiée (mélange d'eaux d'âges différents, A₀ variable dans le passé). En réalité, utiliser la méthode ³H/³He pour une datation plus précise." },
      { id: 4, enonce: "Citez 3 indicateurs géochimiques permettant de distinguer une contamination par les engrais chimiques d'une contamination par les déjections animales.", correction: "1. δ¹⁵N-NO₃⁻ : engrais chimiques (urée, NH₄NO₃) → δ¹⁵N = 0-5 ‰ (proche du N₂ atmosphérique). Déjections animales (fumier, lisier) → δ¹⁵N = 10-25 ‰ (enrichissement microbien en ¹⁵N). 2. δ¹⁸O-NO₃⁻ : permet de distinguer nitrification de NO₃⁻ atmosphérique (δ¹⁸O élevé) de NO₃⁻ produit par nitrification de NH₄⁺ (δ¹⁸O bas). 3. Cl/NO₃⁻ molaire : rapport élevé dans les eaux usées (Cl⁻ élevé des détergents), faible dans les zones à engrais chimiques. 4. (bonus) Carbamazépine, caféine, stéroïdes (traceurs des eaux usées) absents en contexte agricole pur." },
      { id: 5, enonce: "Un lac de 10 km² et 10 m de profondeur se stratifie en été. L'hypolimnion (60% du volume) devient anoxique. Estimer la libération de PO₄ si les sédiments libèrent 0,5 mg P/m² jour pendant 90 jours.", correction: "Volume du lac = 10 × 10⁶ m² × 10 m = 10⁸ m³. Surface des sédiments ≈ 10 km² = 10⁷ m². Libération de P : 0,5 mg P/m²/j × 10⁷ m² × 90 j = 4,5 × 10⁹ mg P = 4500 kg P. Volume hypolimnion = 0,6 × 10⁸ m³ = 6 × 10⁷ m³ = 6 × 10¹⁰ L. Concentration PO₄ accumulée = 4,5 × 10⁹ mg / 6 × 10¹⁰ L = 0,075 mg/L = 75 μg/L. 75 μg P/L >> 35 μg/L (seuil eutrophe) → charge interne très importante qui entretient l'eutrophisation même après réduction des apports externes." },
      { id: 6, enonce: "Expliquez le concept de 'deuterium excess' et son utilité géochimique.", correction: "Le deuterium excess (d) = δD - 8 × δ¹⁸O. Pour la GMWL, d = 10 ‰ (Craig 1961). Ce paramètre reflète les conditions d'évaporation à la source des masses d'air (humidité relative, température de la surface de la mer). Méditerranée (humidité faible, T élevée) : d = 20-22 ‰. Atlantique : d = 10-12 ‰. Les eaux évaporées : d < 10 (perte de D par évaporation cinétique). Utilités : 1. Identifier l'origine des masses d'air (méditerranéenne vs atlantique) → différencier les zones de recharge. 2. Détecter les eaux évaporées avant infiltration (d < 10 ‰). 3. Identifier les pluies convectives vs frontales. Les aquifères du sud de la France ont souvent d > 10 (influence méditerranéenne)." },
      { id: 7, enonce: "Qu'est-ce que l'altération de la pyrite et quelles sont ses conséquences sur la qualité des eaux ?", correction: "Altération de la pyrite (FeS₂) : FeS₂ + 3,75 O₂ + 2,5 H₂O → Fe²⁺ + 2SO₄²⁻ + 4H⁺. Réaction catalysée par Acidithiobacillus ferrooxidans à pH < 4. Conséquences sur la qualité : 1. Production d'acidité (H⁺) → Drainage Minier Acide (DMA, AMD en anglais) : eau très acide (pH 2-4). 2. Libération de Fe²⁺ → oxydation en Fe³⁺ → précipitation de Fe(OH)₃ (oxydes de fer rouges caractéristiques des anciens sites miniers). 3. Libération de SO₄²⁻ (eau sulfatée ferrugineuse). 4. Solubilisation des métaux lourds associés à la pyrite (As, Cd, Pb, Zn, Cu, Co) → contamination des eaux. DMA : problème majeur dans les mines abandonnées de charbon et de métaux en France (Nord-Pas-de-Calais, Lorraine, Massif Central)." },
      { id: 8, enonce: "Citez les 3 principales techniques de datation des eaux souterraines et leurs gammes d'âge.", correction: "1. Tritium (³H, T₁/₂ = 12,3 ans) : eaux post-1950 (si ³H > 0,1 TU) ou pré-1950 (³H indétectable). Méthode ³H/³He : âge 1-50 ans. 2. CFC (chlorofluorocarbures : CFC-11, CFC-12, CFC-113) et SF6 : eaux 0-50 ans. Basé sur la courbe d'enrichissement atmosphérique depuis 1940. Problème : contamination locale des CFC. 3. Carbone-14 (¹⁴C, T₁/₂ = 5730 ans) : eaux 100-40 000 ans. ¹⁴C du carbone inorganique dissous (CID). Correction nécessaire pour l'échange isotopique avec les carbonates de la matrice (dilution du ¹⁴C → vieillissement apparent). Méthodes de correction : Tamers, Evans, Fontes-Garnier. 4. (bonus) Krypton-81 (K-81, T₁/₂ = 230 000 ans) : eaux 10 000-1 000 000 ans (eaux fossiles des grands aquifères sahariens)." }
    ],
    flashcards: [
      { question: "Diagramme de Piper : interprétation", reponse: "Deux triangles ternaires (cations Ca-Mg-Na+K, anions HCO₃-SO₄-Cl) + losange central. Chaque point = faciès d'une eau. Ca-HCO₃ : eaux douces de calcaires. Na-Cl : eaux profondes ou marines. Ca-SO₄ : eaux de gypse. Mélange : point entre deux end-members. Évolution : Ca-HCO₃ → Na-HCO₃ → Na-Cl (chemin de Chebotarev). Utile pour : identification des faciès, détection de mélanges, identification de sources de contamination. Alternative : diagramme de Stiff (eau individuelle sous forme d'hexagone)." },
      { question: "GMWL et isotopes stables de l'eau", reponse: "GMWL (Global Meteoric Water Line) = droite des eaux météoriques mondiales. δD = 8 × δ¹⁸O + 10. Pente 8 = fractionnement cinétique évaporation. Ordonnée 10 = deuterium excess (d). Eau de mer : δ¹⁸O = 0, δD = 0 ‰ (VSMOW). Eau de pluie typique FR : δ¹⁸O ≈ -5 à -10 ‰, δD ≈ -30 à -70 ‰. Eau évaporée : sous la GMWL (d < 10). Eau de fonte glaciaire : très négatif. Usage : tracer les recharges, identifier les mélanges, dater les paléoclimats (carottes de glace)." },
      { question: "Tritium et datation des eaux jeunes", reponse: "³H (tritium) : T₁/₂ = 12,3 ans. Produit naturellement + bombes nucléaires (pic 1963 : 1000 TU). Traceur des eaux récentes : ³H > 1 TU → eau < 50 ans. ³H ≈ 0,1 TU → eau pré-1950 (> 70 ans). Méthode ³H/³He : ³H → ³He par désintégration → âge = (1/λ) × ln(1 + ³He*/³H). Datation précise 1-50 ans. CFC (CFC-12, SF6) complètent pour les eaux récentes. Utile pour : valider les modèles de recharge, estimer les temps de résidence, détecter les contaminations récentes." },
      { question: "Charge interne en phosphore dans les lacs eutrophes", reponse: "Sous la thermocline estivale (hypolimnion), l'O₂ est consommé par la minéralisation de la MO → anoxie. FeOOH des sédiments est réduit en Fe²⁺ → libération de PO₄ adsorbé sur FeOOH. PO₄ accumulé dans l'hypolimnion anoxique. Au brassage automnal → PO₄ redistribué dans tout le lac → eutrophisation interne. Consequence : même si les apports externes sont réduits, l'eutrophisation peut persister pendant des décennies (mémoire sédimentaire). Remédiation : aération de l'hypolimnion, injection de CaO (précipitation) ou de Fe (maintien oxydant des sédiments)." },
      { question: "δ¹⁵N des nitrates : traçage des sources", reponse: "δ¹⁵N-NO₃⁻ distingue les sources d'azote : engrais synthétiques (urée, NH₄NO₃, KNO₃) : δ¹⁵N = 0-5 ‰. Effluents d'élevage (fumier, lisier) : δ¹⁵N = 10-25 ‰ (volatilisation de ¹⁴N sous forme NH₃ → enrichissement résiduel en ¹⁵N). Eaux usées domestiques : δ¹⁵N = 10-30 ‰. Dépôts atmosphériques : δ¹⁵N = -5 à +5 ‰. Couplage δ¹⁵N + δ¹⁸O-NO₃⁻ augmente la résolution des traceurs. Application DCE : identifier les bassins à dominante agricole vs urbaine." }
    ]
  },

  'MASTER-EAU-073': {
    id: 'MASTER-EAU-073',
    titre: 'Métaux et métalloïdes dans les systèmes aquatiques',
    fiche: {
      intro: "Les métaux (Cu, Pb, Zn, Cd, Ni, Cr, Hg, As) et métalloïdes (As, Se, Sb) présents dans les eaux naturelles proviennent à la fois de sources naturelles (altération géochimique, géothermisme) et anthropiques (mines, fonderies, effluents industriels, agriculture). Leur spéciation chimique (forme ionique, complexée ou colloïdale) conditionne leur biodisponibilité, leur toxicité et leur comportement dans les systèmes aquatiques.",
      sections: [
        { titre: "Sources et concentrations naturelles des métaux", sous_sections: [
          { titre: "Origine géochimique et concentrations de fond", contenu: "Les concentrations en métaux des eaux naturelles reflètent la géologie des bassins versants (fond géochimique). Concentrations typiques des eaux de rivière non contaminées (μg/L) : Cu = 1-10, Pb = 0,1-1, Zn = 1-50, Cd = 0,01-0,1, Ni = 1-5, Hg = 0,01-0,1, As = 0,5-5 (variable). Certaines zones géologiques naturellement enrichies : As en Massif Central (volcanisme), Cr et Ni sur roches ultrabasiques (ophiolites), Hg sur cinabres. Les sédiments concentrent les métaux (facteur 100-10 000 par rapport à l'eau) → indicateurs de la pollution historique. Indices de contamination sédimentaire : facteur d'enrichissement EF = (métal/Al)_sédiment / (métal/Al)_fond_géochimique. EF > 5 : contamination significative." },
          { titre: "Sources anthropiques et cycle des métaux", contenu: "Sources anthropiques des métaux en eau : mines et fonderies (drainage acide minier, retombées atmosphériques), trafic routier (Pb des freins, Zn des pneus, Cu des plaquettes de frein), agriculture (Cu des fongicides, Zn des effluents d'élevage), eaux usées industrielles (galvanoplastie, traitement de surface), peintures antifouling marines (Cu, TBT), câbles et canalisations (Cu, Pb des vieilles canalisations). Le Pb dans les eaux : apports historiques (plomb tétraéthyle des carburants jusqu'en 2000, canalisations Pb des réseaux anciens), déclin marqué après l'interdiction. Le Cu dans les eaux urbaines : lixiviation des canalisations Cu et des toitures Cu (pH acide < 7 → dissolution). La contamination diffuse (non-ponctuelle) est difficile à traiter → bassin-versant." }
        ]},
        { titre: "Spéciation chimique et biodisponibilité des métaux", sous_sections: [
          { titre: "Espèces chimiques des métaux en solution", contenu: "Un métal en solution peut exister sous plusieurs formes (espèces chimiques) selon les conditions (pH, Eh, ligands) : ions libres (Pb²⁺, Cu²⁺) : les plus biodisponibles et toxiques. Complexes inorganiques (CuCO₃⁰, PbSO₄⁰, CuOH⁺) : moins biodisponibles. Complexes organiques (métal-acides humiques, métal-EDTA) : biodisponibilité variable (souvent réduite). Colloïdes et nanoparticules (FeOOH, MnO₂, matière organique colloïdale) avec métaux adsorbés. La spéciation est calculée par des logiciels géochimiques (MINTEQ, PHREEQC, Visual MINTEQ). La règle générale : seuls les ions libres (et certains complexes lipophiles) traversent les membranes biologiques. Le modèle de l'ion libre (Free Ion Activity Model, FIAM) corrèle la toxicité à l'activité de l'ion libre." },
          { titre: "Modèle BLM (Biotic Ligand Model)", contenu: "Le Biotic Ligand Model (BLM) est le modèle actuellement recommandé pour évaluer la toxicité des métaux aux organismes aquatiques. Il prédit la toxicité d'un métal en tenant compte de la compétition ionique à la surface biologique (branchies du poisson, etc.) : H⁺, Ca²⁺, Mg²⁺, Na⁺ compétitent avec Cu²⁺, Zn²⁺ pour les sites de liaison. Eau dure (Ca²⁺ élevé) → moins toxique (Cu) car Ca²⁺ compétiteur. pH élevé → Cu moins toxique (moins d'ions libres Cu²⁺). Le BLM est intégré dans la réglementation européenne pour les NQE (Normes de Qualité Environnementale) des métaux (Cu, Zn, Ni, Pb, Cd) : NQE = f(dureté, pH, DOC). Exemple : NQE-MA Cu = 1 μg/L en eau très molle, 20 μg/L en eau très dure." }
        ]},
        { titre: "Méthodes de spéciation et analyse des métaux", sous_sections: [
          { titre: "Techniques d'analyse des métaux en traces", contenu: "L'analyse des métaux en traces dans les eaux requiert des techniques ultrasensibles : ICP-MS (Inductively Coupled Plasma - Mass Spectrometry) : technique de référence. Analyse simultanée de tous les métaux. LQ = 0,001-0,1 μg/L selon le métal. Interférences isobariques (ex. ⁴⁰Ar¹⁶O⁺ interfère avec ⁵⁶Fe⁺) → correction par cellule de collision ou réaction. ICP-AES (Atomic Emission Spectrometry) : moins sensible (LQ ≈ 0,1-10 μg/L), moins d'interférences, moins coûteux. SAA (Spectrométrie d'Absorption Atomique) four graphite (GF-AAS) : pour certains métaux (Pb, Cd, Cr). Hg : CVAAS (Cold Vapour AAS) ou CVAFS (fluorescence). La filtration sur 0,45 μm sépare le dissous du particulaire. L'acidification (HNO₃) conserve les métaux dissous." },
          { titre: "DGT et électrochimie pour la spéciation in situ", contenu: "La DGT (Diffusive Gradients in Thin films) est une technique passive de speciation in situ. Elle mesure la fraction biodisponible (ions libres + petits complexes labiles) en déployant une résine échangeuse de cations derrière un gel de diffusion (agarose ou polyacrylamide) pendant plusieurs jours. Principe : CDGT = M/(D×A×t) × Δg, où M = masse adsorbée, D = coefficient de diffusion dans le gel, A = aire, t = temps. La DGT intègre les variations temporelles et mesure la fraction biodisponible. Les voltamétries (ASV, AdSV) mesurent les métaux labiles électroactifs (Pb²⁺, Cd²⁺, Cu²⁺, Zn²⁺) directement dans l'eau. L'ultrafiltration séquentielle et la dialyse séparent les fractions colloïdales et dissoutes." }
        ]},
        { titre: "Comportement des métaux dans les sédiments", sous_sections: [
          { titre: "Partage sédiment-eau et diagenèse précoce", contenu: "Les sédiments sont les principaux puits des métaux dans les écosystèmes aquatiques. La diagenèse précoce (transformation biogéochimique dans les 10-50 premiers cm de sédiment) contrôle la mobilité des métaux. Dans les sédiments anoxiques : SO₄²⁻ réduit en H₂S (par les bactéries sulfato-réductrices) → précipitation des métaux sous forme de sulfures peu solubles (FeS, ZnS, CdS, PbS) → immobilisation. SEM-AVS (Simultaneously Extracted Metals - Acid Volatile Sulfide) : si ΣSEMi/AVS < 1, les métaux sont immobilisés par les sulfures. Si ΣSEMi/AVS > 1, les métaux en excès sont potentiellement toxiques. Les eaux interstitielles des sédiments (porewater) reflètent l'équilibre avec les phases solides et contrôlent les flux benthiques de métaux vers la colonne d'eau." },
          { titre: "Arsenic dans les aquifères alluviaux : mécanismes de mobilisation", contenu: "La contamination naturelle à l'arsenic (As) des aquifères alluviaux (Bangladesh, Vietnam, Inde, Chine) est liée à des conditions réductrices. Mécanismes : 1. Réduction des oxydes de Fe (FeOOH) : FeOOH réduit en Fe²⁺ par les bactéries ferroreductrices → libération de l'As adsorbé sur FeOOH. 2. Réduction de As(V) → As(III) : As(V) adsorbé est réduit → As(III) moins retenu → libéré en solution. Les sédiments jeunes (Holocène) riches en matière organique déclenchent la réduction microbienne : MO → CO₂ + e⁻ → réduction de Fe³⁺ et As(V). Facteur déclencheur : pompage intensif des eaux souterraines → modification des gradients redox. Concentrations As en eaux souterraines : Bangladesh jusqu'à 500-1000 μg/L (norme OMS = 10 μg/L). Problème de santé publique majeur (cancers de la peau, poisoning chronique)." }
        ]}
      ],
      points: ["ICP-MS : technique de référence pour les métaux en traces (LQ < 0,1 μg/L).", "BLM : toxicité Cu, Zn, Ni corrigée par la dureté, le pH et le DOC.", "NQE-MA Cu : 1 μg/L en eau très molle → 20 μg/L en eau très dure.", "EF = (métal/Al)_séd / (métal/Al)_géochimique. EF > 5 : contamination.", "FIAM : seuls les ions libres traversent les membranes biologiques.", "DGT : spéciation in situ. Mesure la fraction labile biodisponible.", "SEM/AVS < 1 : métaux immobilisés par les sulfures dans les sédiments.", "As alluviaux Bangladesh : réduction FeOOH → libération As(V) adsorbé.", "Cu et Zn : sources diffuses (trafic, toitures, fongicides) = défi réglementaire.", "Filtration 0,45 μm + HNO₃ : standard pour les métaux dissous."],
      formules: [
        { nom: "Facteur d'enrichissement sédimentaire (EF)", expression: "EF = (métal/Al)_sédiment / (métal/Al)_fond_géochimique", variables: "Al = aluminium (traceur lithogénique). EF > 5 : contamination significative. EF > 10 : contamination forte" },
        { nom: "NQE Cu (eau douce, dépendante de la dureté)", expression: "NQE_Cu = e^(0,8545 × ln(dureté) - 1,702)", variables: "Dureté en mg CaCO₃/L. NQE-MA (moyenne annuelle). Modèle BLM simplifié européen" },
        { nom: "Modèle BLM simplifié", expression: "EC50 = EC50_ref × (1 + K_Ca × [Ca²⁺] + K_Mg × [Mg²⁺] + ...)", variables: "K_i = constantes de compétition ionique. EC50 = concentration sans effet 50% pour l'organisme cible" },
        { nom: "DGT (Diffusive Gradients in Thin films)", expression: "C_DGT = M × Δg / (D × A × t)", variables: "M = masse adsorbée (ng), Δg = épaisseur gel (cm), D = diffusivité (cm²/s), A = aire, t = temps (s)" },
        { nom: "Critère SEM-AVS (sédiments)", expression: "ΣSEMi / AVS < 1 → pas de toxicité. > 1 → risque", variables: "SEM = métaux extractibles acides (Zn, Cd, Cu, Ni, Pb, Hg) en μmol/g. AVS = sulfures volatils acides en μmol/g" }
      ],
      retenir: "Les métaux en trace sont analysés par ICP-MS après filtration et acidification. Leur toxicité dépend de la spéciation (ion libre = le plus toxique). Le BLM corrige la toxicité selon la dureté, pH et DOC → NQE variables. Les sédiments accumulent et peuvent libérer les métaux (diagenèse, réduction). L'As dans les aquifères alluviaux résulte de la réduction de FeOOH sous conditions anoxiques."
    },
    exercices: [
      { id: 1, enonce: "Calculer l'EF du plomb (Pb) dans un sédiment : (Pb/Al)_séd = 0,0045, (Pb/Al)_géochimique = 0,0004. Interpréter.", correction: "EF(Pb) = 0,0045 / 0,0004 = 11,25. EF > 10 → contamination forte en Pb. Ce sédiment a une concentration en Pb 11× supérieure au fond géochimique. Sources probables : trafic automobile historique (Pb des carburants), canalisations en Pb, peintures au minium. Depuis l'interdiction du plomb dans l'essence (1990-2000), les apports ont diminué mais les sédiments restent contaminés (mémoire sédimentaire). EF > 10 signale généralement une contamination industrielle ou urbaine significative nécessitant surveillance." },
      { id: 2, enonce: "Eau avec dureté = 50 mg CaCO₃/L et Cu dissous = 3 μg/L. Calculez la NQE-MA simplifiée et évaluez la conformité.", correction: "NQE_Cu = e^(0,8545 × ln(50) - 1,702) = e^(0,8545 × 3,912 - 1,702) = e^(3,342 - 1,702) = e^(1,64) = 5,15 μg/L. Cu mesuré = 3 μg/L < NQE = 5,15 μg/L → conforme à la NQE-MA. Si la dureté était plus faible (10 mg/L) : NQE = e^(0,8545 × ln10 - 1,702) = e^(1,966 - 1,702) = e^(0,264) = 1,30 μg/L → Cu = 3 μg/L > NQE = 1,30 μg/L → non conforme. Cette approche illustre pourquoi les NQE des métaux dépendent de la chimie de l'eau." },
      { id: 3, enonce: "Expliquez pourquoi une eau douce et peu tamponnée (pH 6, dureté 20 mg/L) est plus toxique pour les poissons vis-à-vis du Cu qu'une eau dure et alcaline (pH 8, dureté 300 mg/L), à concentrations totales de Cu identiques.", correction: "En eau douce acide, pH 6, dureté faible : 1. Spéciation : pH faible → Cu²⁺ libre > Cu²⁺ en eau alcaline (moins de CuCO₃⁰, CuOH⁺). 2. Compétition ionique réduite : Ca²⁺ faible (20 mg/L CaCO₃ ≈ 0,2 mmol/L Ca²⁺) → peu de compétition avec Cu²⁺ sur les branchies. 3. Résultat BLM : fraction toxique (Cu²⁺ lié aux branchies) élevée. En eau dure alcaline pH 8 : 1. Cu²⁺ libre faible (Cu complexé en CuCO₃⁰ à pH 8). 2. Ca²⁺ élevé (300 mg CaCO₃/L ≈ 3 mmol/L) → forte compétition avec Cu²⁺ sur les branchies. 3. Toxicité très réduite. Conclusion : la même concentration totale de Cu peut être toxique dans une eau et sans effet dans l'autre → raison pour laquelle NQE Cu varie de 1 à 20 μg/L selon la dureté." },
      { id: 4, enonce: "Citez les 5 facteurs qui contrôlent la mobilisation de l'arsenic dans les aquifères alluviaux réducteurs.", correction: "1. Teneur en oxydes de fer (FeOOH, ferrihydrite) dans les sédiments : c'est le principal porteur d'As(V) adsorbé. 2. Teneur en matière organique (MO) des sédiments : MO = donneur d'électrons pour la réduction de Fe³⁺ → dissolution de FeOOH → libération d'As. 3. Conditions redox (Eh) : Eh < 0 mV → conditions ferroreductrices. O₂ dissous < 0,1 mg/L → anoxie. 4. pH : pH > 8 → désorption de HAsO₄²⁻ des oxydes de Fe par compétition OH⁻. 5. Pompage intensif des eaux souterraines : modifie les gradients hydrauliques et redox, peut favoriser l'infiltration d'eaux riches en MO vers les zones ferroreductrices." },
      { id: 5, enonce: "Sédiments avec ΣSEMi = 15 μmol/g (Zn=10, Cd=1, Cu=4), AVS = 8 μmol/g. Évaluer le risque écotoxicologique.", correction: "ΣSEMi = 15 μmol/g. AVS = 8 μmol/g. ΣSEMi/AVS = 15/8 = 1,875 > 1. Les sulfures sont insuffisants pour immobiliser tous les métaux. Excès = ΣSEMi - AVS = 7 μmol/g de métaux non immobilisés par les sulfures → potentiellement biodisponibles et toxiques pour les organismes benthiques. Les 7 μmol/g excédentaires se distribuent sur le carbone organique (rôle tampon secondaire). Si COT > 0,5% (5 g/kg), l'adsorption sur la MO peut compenser. Conclusion : risque écotoxicologique potentiel, notamment pour Zn (dominant). Recommandation : analyse de la biodisponibilité sur la faune benthique (test toxicologique sur Chironomus, Lumbriculus)." },
      { id: 6, enonce: "Citez les avantages de la DGT pour mesurer les métaux dans les eaux naturelles par rapport à l'ICP-MS sur échantillon prélevé.", correction: "DGT avantages vs prélèvement ponctuel + ICP-MS : 1. Intégration temporelle : mesure en continu sur 1-7 jours (DGT) vs mesure ponctuelle (prélevé). Évite les biais des pics de crue ou des variations diurnes. 2. Spéciation labile : mesure la fraction labile (ions libres + petits complexes) ≈ fraction biodisponible. L'ICP-MS mesure la concentration totale après digestion acide. 3. In situ : pas de transport, pas d'artefacts de conservation (re-équilibre des complexes dans le flacon, adsorption sur parois). 4. Faibles concentrations : accumulation dans la résine → LQ < 1 ng/L pour certains métaux. Limitation DGT : pas de speciation isotopique, interférences par colloïdes, nécessite calibration préalable." },
      { id: 7, enonce: "Qu'est-ce que le drainage minier acide (DMA) et comment est-il traité ?", correction: "DMA = eaux acides (pH 2-4) chargées en SO₄²⁻, Fe, et métaux (Zn, Cd, As, Pb, Cu, Al) issues de l'altération de la pyrite dans les mines abandonnées. Formation : FeS₂ + O₂ + H₂O → Fe²⁺ + SO₄²⁻ + H⁺ (catalysé par Acidithiobacillus). Fe²⁺ + O₂ → Fe³⁺ → Fe(OH)₃ (précipité rouille caractéristique). Fe³⁺ oxyde FeS₂ (cycle auto-entretenu). Traitement : 1. Traitement passif : zones humides artificielles à compost (réduction sulfato-bactérienne : SO₄²⁻ → H₂S → précipitation ZnS, CdS), calcaire actif. 2. Traitement actif : neutralisation à la chaux (Ca(OH)₂) → pH 8-9 → précipitation Fe(OH)₃ et métaux → décantation → boues à valoriser. 3. Prévention : recouvrement des stériles (exclusion O₂)." },
      { id: 8, enonce: "Calculez la concentration maximale de Cu non toxique pour un lac (truite commune : NOEC = 2 μg Cu²⁺ libre/L). Eau : pH 7, dureté 100 mg CaCO₃/L, DOC = 5 mg/L.", correction: "Avec le BLM : NOEC basé sur Cu²⁺ libre = 2 μg/L. Dans ces conditions d'eau, le % de Cu²⁺ libre dépend du pH, de la dureté et du DOC. Estimation simplifiée : à pH 7, dureté 100 mg/L, DOC 5 mg/L, environ 20-30% du Cu total est sous forme Cu²⁺ libre (reste complexé en CuCO₃, Cu-MO). En prenant f(Cu²⁺) = 0,25 (25%) : [Cu total] = [Cu²⁺ libre] / f = 2 / 0,25 = 8 μg Cu total/L. La NQE officielle pour ces conditions (BLM) serait de l'ordre de 5-8 μg/L. Conclusion : la dureté et le DOC 'protègent' les poissons → la réglementation DCE utilise des NQE variables selon la chimie de l'eau (Pb, Cu, Ni, Zn, Cd)." }
    ],
    flashcards: [
      { question: "BLM (Biotic Ligand Model) : principe", reponse: "Modèle de toxicité des métaux aux organismes aquatiques. La toxicité = fixation du métal sur le ligand biotique (branchies). Compétition entre métal toxique (Cu²⁺, Zn²⁺) et Ca²⁺, Mg²⁺, H⁺ sur les sites biologiques. Eau dure (Ca²⁺ élevé) → moins de sites disponibles → moins toxique. pH élevé → Cu complexé → moins d'ions libres → moins toxique. DOC → Cu complexé → moins toxique. NQE-MA des métaux (Cu, Zn, Ni, Cd, Pb) dépendent de la dureté, pH, DOC → calculées eau par eau avec modèle BLM simplifié. Standard DCE depuis 2013." },
      { question: "Spéciation des métaux en solution", reponse: "Un métal peut exister sous forme : ions libres (Cu²⁺ : le plus toxique, traverse membranes). Complexes inorganiques (CuCO₃⁰, CuOH⁺ : partiellement disponibles). Complexes organiques (Cu-humiques : peu disponibles). Colloïdes (adsorbé sur FeOOH, MnO₂ : non disponible). La spéciation est calculée par PHREEQC, MINTEQ (thermodynamique + activités). La filtration 0,45 μm sépare dissous (ions + complexes + colloïdes < 0,45 μm) du particulaire. L'ultrafiltration (< 1 kDa) isole les ions libres + petits complexes." },
      { question: "Arsenic dans les aquifères alluviaux réducteurs", reponse: "Problème de santé publique : Bangladesh, Inde, Vietnam (10-100 M personnes exposées). NQE OMS eau potable = 10 μg/L. Mécanisme : sédiments alluviaux contiennent FeOOH avec As(V) adsorbé. Conditions réductrices (MO élevée, absence O₂) → bactéries ferroreductrices réduisent Fe³⁺ → dissolution FeOOH → As libéré. As(V) réduit en As(III) (moins retenu). Facteur anthropique : pompage intensif → modification redox. Solutions : puits artésiens profonds (aquifères plus anciens sans As), filtration sur FeOOH ou ZVI, déférrisation." },
      { question: "SEM-AVS : critère de toxicité sédimentaire", reponse: "SEM (Simultaneously Extracted Metals) = Zn, Cd, Cu, Ni, Pb, Hg extractibles par HCl 1N (fraction potentiellement mobile). AVS (Acid Volatile Sulfide) = sulfures (FeS, ZnS, CdS) du sédiment, dissous par HCl. Si ΣSEMi/AVS < 1 : métaux immobilisés par les sulfures → pas de biodisponibilité → pas de toxicité. Si ΣSEMi/AVS > 1 : métaux en excès → potentiellement biodisponibles et toxiques. Standard EPA/ASTM pour évaluer les sédiments contaminés. Complété par le carbone organique (COT) comme tampon secondaire." }
    ]
  },

  'MASTER-EAU-074': {
    id: 'MASTER-EAU-074',
    titre: 'Pesticides et contaminants organiques',
    fiche: {
      intro: "Les pesticides (herbicides, insecticides, fongicides) et les polluants organiques persistants (HAP, PCB) sont des contaminants prioritaires de la Directive Cadre sur l'Eau. Leur comportement dans l'environnement aquatique est gouverné par leurs propriétés physicochimiques (Kow, solubilité, pKa, stabilité) et par les processus de dégradation (hydrolyse, photolyse, biodégradation). La réglementation impose des normes de qualité environnementale (NQE) très strictes pour les 45 substances prioritaires.",
      sections: [
        { titre: "Pesticides : classes, usages et propriétés", sous_sections: [
          { titre: "Principales familles de pesticides en usage agricole", contenu: "Les herbicides sont les pesticides les plus utilisés en France (> 60% des tonnages). Triazines (atrazine, simazine, terbuthylazine) : inhibiteurs du photosystème II, utilisées en maïs, maintenant interdites (atrazine bannie en France en 2003). Sulfonylurées (nicosulfuron, metsulfuron) : inhibiteurs de l'acétolactate synthase (ALS), actives à très faibles doses (1-10 g/ha). Glyphosate (Roundup) : inhibiteur de l'EPSP synthase, le plus vendu au monde, controversé. Les insecticides : organophosphorés (chlorpyriphos, diméthoate) et néonicotinoïdes (imidaclopride, clothianidine, thiamethoxam) sont les plus utilisés. Néonicotinoïdes : systémiques, très solubles dans l'eau, mobiles dans les aquifères, toxiques pour les pollinisateurs. Les fongicides : triazoles (tebuconazole, propiconazole) sont les plus utilisés en céréales." },
          { titre: "Propriétés physico-chimiques déterminantes", contenu: "Les propriétés physico-chimiques d'un pesticide conditionnent son comportement environnemental : Kow (coefficient de partage octanol-eau) : hydrophobicité. Kow > 10⁴ → fortement adsorbé sur MO et bioaccumulable. Kow < 100 → mobile en solution. Solubilité dans l'eau : S < 1 mg/L (fortement hydrophobe), S > 1000 mg/L (très hydrosoluble). pKa : pour les acides faibles (sulfonylurées, acides phénoxyacétiques comme le MCPA) et les bases faibles (amines). La charge change avec pH → effet sur l'adsorption. DT50 (demi-vie dans le sol) : 10-500 j selon le composé et le sol. DT50 > 100 j → persistant. Les pesticides prioritaires de la DCE (atrazine, diuron, chlorpyriphos, isoproturon, lindane, etc.) ont des NQE de l'ordre du ng/L à μg/L." }
        ]},
        { titre: "Comportement dans les eaux et les sols", sous_sections: [
          { titre: "Lessivage vers les eaux de surface et souterraines", contenu: "Le transfert des pesticides vers les eaux dépend de leurs propriétés (Koc, DT50) et des caractéristiques du sol et des événements climatiques. Coefficient de Groundwater Ubiquity Score (GUS) = log(DT50) × (4 - log Koc) : GUS > 2,8 → potentiel de lixiviation élevé. GUS < 1,8 → potentiel faible. Les molécules ayant un Koc < 500 et DT50 > 60 jours sont classées 'leachable' par les agences réglementaires (FOCUS, EU). Les pics de concentration dans les rivières lors des premières pluies après les applications (effet 'first flush') sont le principal mécanisme de transfert. Les drains agricoles souterrains exportent directement les pesticides vers les rivières (bypass du sol). La concentration maximale admissible (CMA) en eau potable = 0,1 μg/L par pesticide et 0,5 μg/L total." },
          { titre: "Dégradation : hydrolyse, photolyse, biodégradation", contenu: "Les trois voies de dégradation des pesticides en milieu aquatique : 1. Hydrolyse : rupture de liaisons C-X par l'eau. pH et T dépendant. Esters, phosphates, halogénures d'alkyle, sulfonylurées : sensibles à l'hydrolyse. t₁/₂ hydrolyse à pH 7, 25°C : chlorpyriphos ≈ 100 jours, atrazine ≈ plusieurs années. 2. Photolyse directe : absorption du rayonnement UV (λ < 400 nm) → rupture de liaisons. Photolyse indirecte : radicaux OH● (eau oxygénée, triplet d'état excité de matière organique) → oxydation. Les pesticides absorbant à λ 280-400 nm sont photosensibles. 3. Biodégradation : métabolisme microbien (bactéries du sol et de l'eau). Cinétique d'ordre 1 dans la plupart des cas. DT50 varie de 1 (très dégradable) à > 1000 j (persistant). Les métabolites de biodégradation peuvent être plus toxiques que le parent (ex. : ESA-métolachlore)." }
        ]},
        { titre: "Polluants Organiques Persistants (POP)", sous_sections: [
          { titre: "PCB, dioxines, furanes et HAP", contenu: "Les Polluants Organiques Persistants (POP) sont définis par la Convention de Stockholm (2001) : persistance (DT50 > 180 j eau), bioaccumulation (BCF > 5000, log Kow > 5), longue distance de transport atmosphérique. Les PCB (PolyChloroBiphényles, 209 congénères) : anciens transformateurs électriques, fluides hydrauliques, peintures. log Kow = 4-8 selon le degré de chloration. Interdits en France en 1987 mais encore présents dans les sédiments. Les dioxines (PCDD) et furanes (PCDF) : sous-produits de combustion et de synthèse chimique. Très lipophiles (log Kow = 6-9). Les HAP (Hydrocarbures Aromatiques Polycycliques, 16 HAP prioritaires EPA) : issus des combustions incomplètes (trafic, chauffage, feux), des huiles minérales, du charbon. Benzo[a]pyrène : cancérogène avéré (groupe 1 CIRC), NQE eau = 0,00017 μg/L." },
          { titre: "Bioaccumulation et bioamplification trophique", contenu: "La bioaccumulation est l'accumulation d'un contaminant lipophile dans un organisme par rapport à l'eau environnante. BCF (Bioconcentration Factor) = concentration organisme / concentration eau. BCF est corrélé à Kow : log BCF ≈ 0,76 × log Kow (Mackay 1982). BCF(PCB 153) ≈ 10⁵ L/kg. La bioamplification trophique (biomagnification) : concentration croissante le long de la chaîne alimentaire (phytoplancton → zooplancton → poissons → oiseaux piscivores → mammifères marins). Le facteur de biomagnification (BMF) = concentration prédateur / concentration proie. Pour les PCB dans les cétacés (baleines à fanons, dauphins) et les oiseaux piscivores (hérons, balbuzards) : concentrations plasmatiques 10⁶× supérieures à l'eau. Les NQE biota (NQE-b, dans les tissus de poissons) sont souvent plus contraignantes que les NQE-eau pour les POP (ex. : NQE-b mercure = 20 μg/kg dans le biota)." }
        ]},
        { titre: "Réglementation et surveillance des pesticides", sous_sections: [
          { titre: "Surveillance DCE : réseaux et méthodes", contenu: "La Directive Cadre sur l'Eau (DCE, 2000/60/CE) établit une liste de 45 substances prioritaires (SP) et 8 substances prioritaires dangereuses (SPD) soumises à un objectif de suppression des rejets. Les réseaux de surveillance DCE en France (réseaux RAEPA, RCS, RCO, RCB) mesurent les SP dans les eaux de surface et souterraines. La fréquence de surveillance : surveillance de contrôle (1×/an aux eaux de surface), surveillance opérationnelle (4-12×/an aux masses d'eau à risque). Les analyses des SP requièrent des techniques analytiques de pointe (LC-MS/MS pour les pesticides polaires, GC-MS pour les composés organochlorés) avec des LQ < NQE. L'évaluation du bon état chimique repose sur le dépassement des NQE-MA (moyenne annuelle) ou NQE-CMA (concentration maximale admissible)." },
          { titre: "Phytosanitaires en eau potable : réglementation française", contenu: "Les limites de qualité pour les pesticides en eau potable (arrêté du 11/01/2007) : 0,1 μg/L par substance active (SA) et 0,5 μg/L pour le total des SA. Exceptions : aldrine, dieldrine, heptachlore, heptachlorépoxyde → 0,03 μg/L. Ces limites (0,1 μg/L) ne sont pas basées sur la toxicité (elles sont souvent très en dessous des NOEC toxicologiques) mais sur le principe de précaution et la détectabilité analytique. Environ 15% des captages d'AEP en France ont des teneurs en pesticides dépassant 0,1 μg/L (atrazine et métabolites historiquement, aujourd'hui néonicotinoïdes, sulfonylurées). Les plans d'action Captages Grenelle ciblent les 500 captages les plus menacés par les pesticides." }
        ]}
      ],
      points: ["GUS = log(DT50) × (4 - log Koc). GUS > 2,8 → lixiviation probable.", "Kow > 10⁴ : fortement adsorbé sur MO, bioaccumulable. Kow < 100 : mobile.", "NQE eau potable : 0,1 μg/L/substance, 0,5 μg/L total (arrêté 2007).", "PCB, dioxines : log Kow = 4-9. POP : persistants, bioaccumulables.", "log BCF ≈ 0,76 × log Kow. BCF(PCB 153) ≈ 10⁵.", "Benzo[a]pyrène (HAP) : NQE eau = 0,00017 μg/L.", "Atrazine : interdite en France depuis 2003, encore détectée (métabolites).", "Néonicotinoïdes : systémiques, mobiles, toxiques pour pollinisateurs.", "DCE : 45 substances prioritaires, NQE-MA et NQE-CMA.", "Biodégradation : cinétique ordre 1. DT50 > 100 j → persistant."],
      formules: [
        { nom: "GUS (Groundwater Ubiquity Score)", expression: "GUS = log(DT50_sol) × (4 - log Koc)", variables: "GUS > 2,8 : lixiviation probable. GUS < 1,8 : non lixiviable. DT50 en jours, Koc en L/kg" },
        { nom: "Coefficient de partage octanol-eau", expression: "Kow = [composé dans n-octanol] / [composé dans eau]",  variables: "log Kow : 0-2 (hydrophile), 2-4 (intermédiaire), > 4 (lipophile, bioaccumulable)" },
        { nom: "Bioconcentration Factor", expression: "BCF = C_organisme / C_eau",  variables: "log BCF ≈ 0,76 × log Kow (Mackay). BCF > 5000 → bioaccumulable (critère POP)" },
        { nom: "Coefficient de partage sol-eau normalisé", expression: "Koc = Kd / foc",  variables: "foc = fraction en carbone organique du sol. log Koc ≈ log Kow - 0,2" },
        { nom: "Cinétique de dégradation ordre 1", expression: "c(t) = c₀ × e^(-k × t), DT50 = ln2/k",  variables: "k = constante cinétique (j⁻¹). DT50 en jours. DT50 > 100 j → persistant" }
      ],
      retenir: "Les pesticides mobiles (faible Koc, long DT50 → GUS élevé) contaminent les aquifères. Les POP (PCB, HAP, dioxines) sont lipophiles (Kow > 10⁴) et bioaccumulables. La bioamplification trophique concentre les POP dans les prédateurs sommitaux. La réglementation DCE impose des NQE de l'ordre du ng/L pour les substances les plus toxiques. L'eau potable est limitée à 0,1 μg/L par pesticide."
    },
    exercices: [
      { id: 1, enonce: "Calculez le GUS pour l'atrazine (DT50 = 60 j, Koc = 100 L/kg) et pour le benzo[a]pyrène (DT50 = 100 j, Koc = 100 000 L/kg).", correction: "Atrazine : GUS = log(60) × (4 - log 100) = 1,778 × (4 - 2) = 1,778 × 2 = 3,56. GUS > 2,8 → potentiel de lixiviation élevé → risque pour les eaux souterraines (confirmé par sa présence historique dans les aquifères). Benzo[a]pyrène : GUS = log(100) × (4 - log 100000) = 2 × (4 - 5) = 2 × (-1) = -2. GUS < 1,8 (très négatif) → non lixiviable, retenu dans le sol par les particules (Koc très élevé). Risque principalement pour les eaux de surface (ruissellement avec sédiments) et non pour les eaux souterraines." },
      { id: 2, enonce: "log Kow (PCB 153) = 6,9. Calculez BCF et estimez la concentration dans les graisses d'un grand dauphin si C_eau = 0,1 ng/L.", correction: "log BCF ≈ 0,76 × log Kow = 0,76 × 6,9 = 5,24. BCF = 10^5,24 = 174 000 L/kg. C_dauphin = BCF × C_eau = 174 000 × 0,1 × 10⁻⁶ g/L = 0,0174 g/kg = 17,4 mg/kg. Cette valeur est en accord avec les données mesurées dans les cétacés méditerranéens (10-100 mg/kg poids humide de graisse pour PCB totaux). Rappel : la bioamplification trophique (phytoplancton → zooplancton → poisson → dauphin) peut encore multiplier cette valeur par 10-100 en remontant la chaîne alimentaire, soit 100-1000 mg PCB/kg de graisse." },
      { id: 3, enonce: "Une eau potable analyse 0,08 μg/L d'atrazine + 0,04 μg/L de terbuthylazine + 0,05 μg/L de déséthylatrazine. Est-elle conforme ?", correction: "Chaque substance : atrazine 0,08 < 0,1 μg/L ✓, terbuthylazine 0,04 < 0,1 μg/L ✓, déséthylatrazine (métabolite) 0,05 < 0,1 μg/L ✓. Somme totale = 0,08 + 0,04 + 0,05 = 0,17 μg/L > 0,5 μg/L ? Non, 0,17 < 0,5 ✓. Conforme aux deux critères (0,1 μg/L par substance et 0,5 μg/L total). Note : depuis 2023, en France, les 'métabolites non pertinents' (sans activité pesticide et sans risque) comme la déséthylatrazine ont un seuil distinct de 0,9 μg/L. Mais la déséthylatrazine ayant une activité herbicide résiduelle est toujours soumise à la limite de 0,1 μg/L." },
      { id: 4, enonce: "Citez 3 mécanismes par lesquels les néonicotinoïdes contaminent les eaux souterraines.", correction: "1. Lixiviation directe : les néonicotinoïdes (imidaclopride, clothianidine, thiamethoxam) ont un Koc = 100-300 L/kg (faible → peu retenus par la MO) et DT50 = 100-500 jours → GUS > 3 → lixiviation probable. Ils percolent avec l'eau et atteignent la nappe en quelques mois. 2. Enrobage des semences : les grains traités libèrent progressivement le néonicotinoïde lors de la germination et de la croissance → apport continu au sol et à la nappe pendant toute la culture. 3. Ruissellement et drainage : lors des pluies, les néonicotinoïdes dissous dans l'eau du sol sont exportés rapidement par les drains agricoles vers les rivières et ensuite infiltrent vers les aquifères alluviaux." },
      { id: 5, enonce: "Expliquez pourquoi les NQE de substances comme le benzo[a]pyrène (0,00017 μg/L) sont si basses et comment les mesurer.", correction: "NQE très basse (0,17 ng/L) car : toxicité élevée (benzo[a]pyrène = cancérogène avéré, groupe 1 CIRC). La NQE est calculée pour protéger 95% des espèces aquatiques × facteur de sécurité (PNEC = HC5/ASF). Pour des substances CMR (cancérogènes, mutagènes, reprotoxiques), les NQE sont calculées sur la base de la concentration totale acceptable pour l'environnement et l'humain (ingestion de poissons). Méthodes analytiques : extraction liquide-liquide ou SPE (solid phase extraction) sur cartouche C18, puis GC-MS/MS (chromatographie gazeuse - spectrométrie de masse en tandem) ou HPLC-FLD (fluorimétrie). LQ atteignable : 0,05-0,01 ng/L avec extraction et GC-MS/MS. Concentration de travail élevée (1 L → 1 mL extrait) → facteur de concentration ×1000." },
      { id: 6, enonce: "Qu'est-ce que l'effet 'first flush' pour les pesticides et comment l'exploiter pour la surveillance ?", correction: "L'effet 'first flush' (premier rinçage) est le phénomène par lequel la première pluie après une application de pesticides exporte la concentration maximale en pesticides vers les eaux de surface. Mécanisme : les pesticides appliqués en surface (ou en profondeur en cas de travaux du sol) sont dissous par les premières pluies → ruissellement et drainage → concentration élevée dans les rivières (pic en quelques heures). Le premier flush peut représenter 50-80% de l'export annuel de pesticides en quelques jours. Exploitation pour la surveillance : positionnement des prélèvements lors des premières pluies après les périodes d'application (printemps pour les herbicides de printemps, automne pour les herbicides de pré-levée). Préleveurs automatiques déclenchés par les événements de pluie (préleveurs à seuil). Surveillance continue par des capteurs (fluorimétrie, spectroscopie UV)." },
      { id: 7, enonce: "Citez les 5 critères définissant un Polluant Organique Persistant (POP) selon la Convention de Stockholm.", correction: "La Convention de Stockholm (2001) définit 5 critères pour les POP : 1. Persistance : DT50 > 60 j dans l'eau ou > 180 j dans les sédiments/sols. Les POP résistent à la dégradation photolytique, chimique et biologique. 2. Bioaccumulation : BCF > 5000 ou log Kow > 5 (lipophilicité élevée). 3. Transport à longue distance : détectés dans des régions éloignées de toute source (pôles, Himalaya, Arctique). Transport atmosphérique (semi-volatilité). 4. Effets néfastes : toxiques, cancérogènes, perturbateurs endocriniens, immunotoxiques. 5. Présence confirmée dans l'environnement dans des régions éloignées. Les POP originaux (dirty dozen) : PCB, DDT, dioxines, furanes, hexachlorobenzène, mirex, aldrine, dieldrine, endrine, chlordane, heptachlore, toxaphène." },
      { id: 8, enonce: "Calculez la DT50 d'un insecticide dont la constante de dégradation k = 0,023 j⁻¹. Est-il 'persistant' ?", correction: "DT50 = ln2/k = 0,693/0,023 = 30,1 jours. DT50 ≈ 30 jours < 100 jours → non classé 'persistant' selon les critères FOCUS (> 100 jours dans le sol pour l'évaluation du risque lixiviation). Non POP (DT50 < 60 jours eau, POP demande > 180 j sédiments). GUS = log(30) × (4 - log Koc). Si Koc = 2000 L/kg : GUS = 1,477 × (4 - 3,3) = 1,477 × 0,7 = 1,03 < 1,8 → non lixiviable. L'insecticide est modérément dégradable (30 j) et peu mobile si Koc élevé. Il reste présent en surface plusieurs semaines → risque pour les insectes pollinisateurs (exposition foliaire ou florale)." }
    ],
    flashcards: [
      { question: "GUS : lixiviation des pesticides", reponse: "GUS (Groundwater Ubiquity Score) = log(DT50) × (4 - log Koc). GUS > 2,8 : potentiel de lixiviation élevé (atrazine 3,6, sulfonylurées 4-6). GUS < 1,8 : non lixiviable (HAP, PCB). GUS 1,8-2,8 : intermédiaire. Molécules à risque pour les aquifères : Koc < 500 ET DT50 > 60 j. Critère FOCUS (EU) : simulation PELMO/PEARL pour autorisation. Les néonicotinoïdes ont souvent GUS > 3 → présents dans les eaux souterraines françaises." },
      { question: "POP (Polluants Organiques Persistants) : définition", reponse: "5 critères Convention de Stockholm : 1. Persistant (DT50 > 180 j sédiments). 2. Bioaccumulable (BCF > 5000, log Kow > 5). 3. Transport longue distance. 4. Effets néfastes. 5. Présence dans régions éloignées. Exemples : PCB (transformateurs), dioxines (combustion), DDT (insecticide agricole), HCB, lindane, HAP (combustion). Stockés dans les graisses → bioamplification trophique. Trouvés dans toutes les graisses animales, même polaires (ours, phoques, baleines). Convention de Stockholm → interdiction progressive." },
      { question: "Eau potable et pesticides : limites françaises", reponse: "Arrêté du 11/01/2007 : 0,1 μg/L par substance active (y compris métabolites pertinents). 0,5 μg/L pour le total. Exceptions : aldrine/dieldrine/heptachlore = 0,03 μg/L. Ces limites < toxicité → principe de précaution. Deux grandes listes 2023-2024 : métabolites non pertinents (chlorothalonil-R471811 par exemple) = 0,9 μg/L. Données SISE-Eaux (ARS/DGCCRF) : environ 15% des captages dépassent 0,1 μg/L. Substances détectées : atrazine-déséthyl, chlorotoluron, imidaclopride, métolachlore-ESA." },
      { question: "Bioaccumulation et bioamplification trophique", reponse: "Bioaccumulation : C_organisme >> C_eau. BCF = C_orga/C_eau. log BCF ≈ 0,76 × log Kow. BCF(DDT dans les poissons) ≈ 10⁵. Bioamplification (biomagnification) : concentration croit à chaque niveau trophique. BMF = C_prédateur/C_proie > 1. Accumulation le long de : phytoplancton → zooplancton → poissons fourrages → poissons prédateurs → oiseaux → mammifères marins. DDT, PCB, dioxines : BMF = 3-10 par niveau trophique → ×10⁴ entre eau et dauphin. NQE-biota (protéger l'humain qui mange des poissons) souvent plus contraignante que NQE-eau." }
    ]
  },

  'MASTER-EAU-075': {
    id: 'MASTER-EAU-075',
    titre: 'PFAS, résidus pharmaceutiques et autres contaminants émergents',
    fiche: {
      intro: "Les contaminants émergents (CE) désignent les substances nouvellement identifiées comme préoccupantes dans les milieux aquatiques, même si elles peuvent exister depuis longtemps. Les PFAS (substances per- et polyfluoroalkylées), les résidus pharmaceutiques, les perturbateurs endocriniens et les microplastiques constituent les défis majeurs de la chimie environnementale contemporaine, posant des problèmes de réglementation, d'analyse et de traitement spécifiques.",
      sections: [
        { titre: "PFAS : substances per- et polyfluoroalkylées", sous_sections: [
          { titre: "Structure, propriétés et sources des PFAS", contenu: "Les PFAS (Per and PolyFluoroAlkyl Substances) sont une famille de >4700 composés caractérisés par la présence de liaisons C-F, les plus fortes de la chimie organique (energie de dissociation 544 kJ/mol pour C-F vs 414 kJ/mol pour C-H). Cette résistance chimique rend les PFAS pratiquement indégradables dans les conditions environnementales (d'où le surnom 'forever chemicals'). Les principaux PFAS : PFOS (acide perfluorooctane sulfonique, C8) et PFOA (acide perfluorooctanoïque, C8) sont les PFAS les plus étudiés, inscrits à la Convention de Stockholm, interdits sauf dérogations. Sources : mousses anti-incendie AFFF (aéroports, bases militaires, dépôts), emballages alimentaires imperméables (papiers de McDonald's, pop-corn), textiles Teflon/Gore-tex, cosmétiques. Contamination majeure autour des aéroports et bases militaires en France (PFOS, PFOA détectés à des centaines de ng/L)." },
          { titre: "Comportement environnemental et toxicité des PFAS", contenu: "Les PFAS sont à la fois hydrophiles (solubles dans l'eau) et lipophobes (ne se concentrent pas dans les graisses comme les PCB) mais se fixent sur les protéines plasmatiques (albumine) et les acides biliaires → bioaccumulation différente des POP classiques. PFOS et PFOA persistent dans les eaux souterraines pendant des décennies (pas de biodégradation, pas d'hydrolyse, pas de photolyse). Concentration dans les eaux souterraines proches des aéroports : jusqu'à 1-10 μg/L PFOS. Effets toxicologiques : perturbateurs endocriniens (perturbation de la thyroïde, retard de croissance), hépatotoxiques, immunotoxiques, cancérogènes possibles (rein, testicule). Valeur guide OMS 2022 eau potable : PFOS + PFOA = 100 ng/L (provisoire). Valeur limite Directive (UE) 2020/2184 : somme 20 PFAS = 100 ng/L." }
        ]},
        { titre: "Résidus pharmaceutiques dans l'eau", sous_sections: [
          { titre: "Sources, occurrence et comportement", contenu: "Les médicaments atteignent les eaux naturelles principalement via les urines et les selles (métabolites excrétés), les STEP (élimination insuffisante des micropolluants), les déchets hospitaliers et pharmaceutiques mal gérés. Substances détectées en ng/L à μg/L dans les rivières françaises : ibuprofène, diclofénac (anti-inflammatoires), carbamazépine (antiépileptique), 17α-éthinylestradiol (EE2 des pilules contraceptives), azithromycine (antibiotique), metformine (antidiabétique). La carbamazépine est un marqueur de contamination par les eaux usées (non dégradée en STEP, ubiquiste). Le diclofénac et EE2 sont classés substances prioritaires de la DCE (NQE eaux de surface = 10 ng/L et 0,035 ng/L respectivement). La fréquence de détection dans les eaux souterraines proches des zones urbaines est en augmentation : carbamazépine, sulfaméthoxazole (antibiotique), aténolol (bêta-bloquant)." },
          { titre: "Perturbateurs endocriniens (PE) et effets sur la faune aquatique", contenu: "Les perturbateurs endocriniens (PE) sont des substances qui interfèrent avec le système hormonal des organismes : mimétisme œstrogénique (phyto-œstrogènes, 17β-estradiol naturel, 17α-éthinylestradiol, bisphénol A, nonylphénol), anti-androgénique (vinclozoline fongicide), thyroïdien (PCB, BPA). Effets sur les poissons : féminisation des mâles (vitellogenine, intersex) dans les rivières en aval des STEP → première documentation dans les années 1990 au Royaume-Uni (rivières Nene, Lee). Effets à des concentrations très faibles : 1 ng/L EE2 → féminisation des poissons mâles. The 'Lake Experiment' (Kidd et al., 2007 Science) : ajout de 5 ng/L EE2 dans un lac expérimental → effondrement de la population de ménés en 3 ans (perturbation de la reproduction). Ce résultat a conduit à l'inscription du diclofénac et de EE2 sur la liste DCE." }
        ]},
        { titre: "Résistance aux antibiotiques et One Health", sous_sections: [
          { titre: "Résistance aux antimicrobiens dans les milieux aquatiques", contenu: "Les milieux aquatiques (rivières, eaux souterraines, sédiments) sont des réservoirs et des vecteurs de résistance aux antimicrobiens (RAM). Les gènes de résistance aux antibiotiques (ARG) sont présents dans les microbiomes naturels mais les apports anthropiques (eaux usées hospitalières, effluents d'élevage) augmentent drastiquement leur prévalence. Les STEP ne sont pas conçues pour éliminer les ARG → sortie STEP : forte concentration en ARG et en bactéries résistantes. Les rivières en aval des STEP contiennent plus d'ARG (gènes de résistance aux bêta-lactamines, aux tétracyclines, aux quinolones) que les rivières naturelles. Le concept 'One Health' (une seule santé) relie la santé humaine, animale et environnementale : la RAM dans les milieux aquatiques peut atteindre l'humain par les produits aquacoles, les légumes irrigués, l'eau potable." },
          { titre: "Microplastiques et nanoplastiques", contenu: "Les microplastiques (MP, particules plastiques < 5 mm) proviennent de la dégradation de macroplastiques (UV, érosion physique), des fibres textiles synthétiques (lavages de vêtements polyester : > 700 000 fibres/lavage), des granulés de pré-production (nurdles), des pneumatiques (rubber particles), des cosmétiques (microbeads interdites en France depuis 2018). Concentrations en MP dans les rivières : 1-100 particules/L. Dans les sédiments : 100-10 000 particules/kg. Les nanoplastiques (< 1 μm) sont encore plus difficiles à analyser et potentiellement plus toxiques (pénétration cellulaire). Effets connus : blocage du tube digestif chez les organismes aquatiques, effet dit 'cheval de Troie' (vecteur de contaminants chimiques adsorbés sur les plastiques : PCB, pesticides). La filtration sur membrane (NF, OI) et la coagulation-floculation éliminent efficacement les MP." }
        ]},
        { titre: "Traitement et réglementation des contaminants émergents", sous_sections: [
          { titre: "Élimination en STEP et en AEP", contenu: "Les STEP conventionnelles (boues activées) éliminent mal les contaminants émergents : élimination de 10-50% pour la carbamazépine, l'acide clofibrique. 50-80% pour l'ibuprofène, le diclofénac. > 90% pour l'estradiol naturel (E1, E2) mais l'EE2 persiste à 60-80%. Techniques avancées pour les CE en STEP et AEP : 1. Ozonation (O₃ 5-20 mg/L) → oxydation rapide des CE aromatiques (EE2, diclofénac, ibuprofène). 2. Charbon actif poudre (PAC 10-20 mg/L) → adsorption des CE lipophiles. 3. Nanofiltration (NF) ou Osmose Inverse (OI) → barrière physique absolue. 4. UV/H₂O₂ → oxydation photochimique par radicaux OH●. Les STEP avec lit de boues activées + filtration sur sable + ozonation + GAC (charbon actif granulaire) éliminent > 90% des CE (procédés en Suisse obligatoires depuis 2016 pour les STEP > 100 000 EH)." },
          { titre: "Réglementation européenne en évolution", contenu: "La réglementation sur les contaminants émergents évolue rapidement : DCE révisée (2022) : nouvelle liste des 25 substances prioritaires ajoutant les PFAS (PFOS, PFOA), plusieurs pharmaceutiques (EE2, diclofénac) et le bisphénol A. Directive Eau Potable révisée (2020/2184) : somme 20 PFAS < 100 ng/L. France (arrêté surveillance 2022) : Plan Eau 2023 inclut la surveillance des PFAS, antibiotiques, microplastiques. Règlement REACH (CE 1907/2006) : restriction ou interdiction de PFAS dans les produits de consommation (emballages alimentaires : interdiction de PFAS en France depuis 2020, en EU depuis 2023 selon certaines catégories). L'évaluation de la dangerosité des > 4700 PFAS reste un défi réglementaire majeur." }
        ]}
      ],
      points: ["PFAS : liaisons C-F indestructibles → 'forever chemicals'. Sources : AFFF, Teflon.", "NQE EU 2020 : somme 20 PFAS < 100 ng/L en eau potable.", "Carbamazépine : marqueur de contamination par eaux usées, ubiquiste.", "EE2 : NQE eau 0,035 ng/L, féminise les poissons mâles à 1 ng/L.", "STEP éliminent mal les CE (10-80% selon le composé).", "Ozonation + GAC : traitement avancé des CE (> 90% élimination).", "ARG (gènes de résistance) : STEP = amplificateurs de RAM, One Health.", "Microplastiques < 5 mm : fibres textiles, pneumatiques, dégradation plastiques.", "Microbeads cosmétiques : interdites en France depuis 2018.", "Suisse : ozonation obligatoire pour les STEP > 100 000 EH depuis 2016."],
      formules: [
        { nom: "Énergie liaison C-F vs C-H", expression: "E(C-F) = 544 kJ/mol, E(C-H) = 414 kJ/mol",  variables: "Liaisons C-F les plus fortes de la chimie organique → résistance à toute dégradation chimique, biologique, thermique" },
        { nom: "Efficacité d'élimination en STEP", expression: "E (%) = (C_entrée - C_sortie) / C_entrée × 100",  variables: "Varie selon le composé : carbamazépine 10-30%, ibuprofène 70-90%, EE2 60-80%" },
        { nom: "NQE EE2 (perturbateur endocrinien)", expression: "NQE-MA = 0,000035 μg/L = 35 pg/L",  variables: "Très basse : protection de la faune aquatique (féminisation des poissons). Méthode : LC-MS/MS" },
        { nom: "Dose journalière admissible antibiotique (OMS)", expression: "DJA = NOEC / ASF",  variables: "ASF = facteur de sécurité (100 pour les données animales). Pas de NQE officielle EU pour la plupart des antibiotiques" }
      ],
      retenir: "Les PFAS ('forever chemicals') sont omniprésents, non dégradables et bioaccumulables différemment des POP classiques. EE2 est un perturbateur endocrinien majeur des eaux de surface (NQE = 35 pg/L). La carbamazépine est un marqueur de contamination par eaux usées. Les STEP conventionnelles éliminent mal les CE. L'ozonation, le GAC et l'OI constituent les traitements avancés. La résistance aux antibiotiques dans les milieux aquatiques est un enjeu One Health."
    },
    exercices: [
      { id: 1, enonce: "Citez 3 propriétés des PFAS qui les rendent particulièrement problématiques comme contaminants des eaux.", correction: "1. Persistance absolue ('forever chemicals') : les liaisons C-F (544 kJ/mol) résistent à toutes les conditions environnementales (hydrolyse, photolyse, biodégradation, incinération insuffisante). DT50 = infini dans les conditions naturelles. Accumulation progressive dans tous les compartiments. 2. Mobilité dans les eaux : malgré leur persistance, les PFAS sont solubles dans l'eau (surtout les chaînes courtes C4-C6) → lixiviation vers les aquifères. PFOS et PFOA détectés à des μg/L dans les eaux souterraines proches des aéroports. 3. Bioaccumulation protéique atypique : les PFAS ne se concentrent pas dans les graisses (comme les PCB) mais se fixent sur les protéines (albumine, acides biliaires) → bioaccumulation dans le foie, le sang → difficiles à mobiliser par les techniques classiques de dépollution (charbon actif, nanofiltration efficaces en eau mais pas dans les organismes)." },
      { id: 2, enonce: "Pourquoi la carbamazépine est-elle utilisée comme traceur des eaux usées en hydrogéologie ?", correction: "La carbamazépine est un antiépileptique largement prescrit en Europe (> 100 000 tonnes/an consommées). Ses propriétés en font un traceur idéal : 1. Persistance : non dégradée en STEP (élimination < 20% en boues activées). Résistante à la biodégradation dans les sols et aquifères. DT50 dans l'eau > 1000 jours. 2. Ubiquiste : détectée dans pratiquement toutes les eaux en aval de zones urbanisées (> 90% des sites mondiaux > 50 hab.). 3. Spécificité humaine : métabolite uniquement humain (non détecté dans les déjections animales → distingue la pollution par eaux usées urbaines de la pollution agricole). 4. Faible Koc ≈ 300 L/kg → non retenue par les sols → traceur conservatif des eaux souterraines. Usage : traçage des connexions hydrauliques entre zones urbaines et aquifères, détection des infiltrations d'eaux usées dans les réseaux d'AEP." },
      { id: 3, enonce: "Une eau de rivière en aval d'une STEP mesure 1,5 ng/L EE2. Cette valeur est-elle préoccupante et comment peut-on la traiter ?", correction: "NQE-MA EE2 = 0,000035 μg/L = 0,035 ng/L. 1,5 ng/L >> 0,035 ng/L → dépassement de NQE × 43. Très préoccupant pour la faune aquatique. Des études montrent que 1 ng/L EE2 suffit à féminiser les poissons mâles (vitellogenine détectée). À 1,5 ng/L → féminisation certaine → atteinte du bon état écologique. Traitements pour réduire EE2 : 1. Ozonation en STEP (O₃ 5 mg/L) → élimination > 95% de EE2 (très sensible à l'ozonation). 2. Charbon actif GAC en STEP (filtration sur lit GAC) → adsorption EE2 ≥ 90%. 3. Nanofiltration / osmose inverse (barrière physique) → 100% si MW cut-off < 200 Da. La réglementation française (Plan Eau 2023) impose la surveillance d'EE2 en STEP > 100 000 EH et en eaux réceptrices." },
      { id: 4, enonce: "Citez 4 sources de microplastiques dans les eaux douces de surface.", correction: "1. Fibres textiles synthétiques : chaque lavage de vêtements polyester/nylon libère > 700 000 fibres micro (1-500 μm). Ces fibres passent en grande partie les mailles des stations d'épuration (trop fines pour être retenues par décantation primaire et filière boues activées). 2. Usure des pneumatiques : particules de caoutchouc synthétique (SBR + carbon black) produites par friction route/pneu → ruissellement → rivières. Principal contributeur en masse pour les MP dans les eaux urbaines. 3. Fragmentation de déchets plastiques : UV, gel/dégel, friction → macroplastiques → méso → micro → nanoplastiques. Microplastiques des berges et des zones de dépôt. 4. Dérivés industriels : granulés de pré-production (nurdles) perdus lors du transport, pellets de plastique. Peintures époxy et antifoulings. Poussières d'usine et empoussièrement atmosphérique (MP atmosphériques retrouvés en Himalaya, Alpes)." },
      { id: 5, enonce: "Expliquez le mécanisme de la résistance bactérienne aux antibiotiques transmissible dans les rivières.", correction: "Les bactéries résistantes aux antibiotiques peuvent transférer leurs gènes de résistance (ARG) horizontalement par conjugaison (plasmides), transduction (phages) ou transformation. Dans les rivières : 1. Les eaux usées apportent des bactéries résistantes (E. coli producteurs de BLSE, entérocoques VRE) et des plasmides ARG. 2. La communauté bactérienne naturelle de la rivière acquiert les ARG par transfert horizontal. 3. Les concentrations sub-inhibitrices d'antibiotiques dans les rivières (ng/L à μg/L) exercent une pression sélective → sélection des souches résistantes. 4. L'effet 'hot spot' de transfert : biofilms sur sédiments = environnements propices à la conjugaison (densité cellulaire élevée). 5. Voies de retour vers l'humain : eaux de baignade, irrigation de légumes, production de poissons d'élevage. Concept One Health : les ARG du milieu aquatique peuvent coloniser l'intestin humain → infections résistantes aux antibiotiques." },
      { id: 6, enonce: "Calculez le taux de dépassement de la NQE-EE2 (0,035 ng/L) si une STEP élimine 70% de l'EE2 et que la concentration entrée = 50 ng/L, débit STEP = 50 000 m³/j, débit rivière = 2 m³/s.", correction: "Concentration sortie STEP : 50 × (1 - 0,70) = 15 ng/L. Débit rivière : 2 m³/s = 172 800 m³/j. Après mélange STEP + rivière (en supposant [EE2]_rivière_amont ≈ 0) : C_mélange = 15 × 50 000 / (172 800 + 50 000) = 750 000 / 222 800 = 3,37 ng/L. Dépassement NQE : 3,37 / 0,035 = 96×. La NQE est dépassée d'un facteur 96 même après 70% d'élimination. Pour respecter la NQE, il faudrait une élimination = 1 - (NQE × Q_total) / (C_entrée × Q_STEP) = 1 - (0,035 × 222800) / (50 × 50000) = 1 - 7798/2 500 000 = 1 - 0,003 = 99,7% → nécessite ozonation + GAC ou OI." },
      { id: 7, enonce: "Qu'est-ce que l'effet 'cheval de Troie' des microplastiques ?", correction: "L'effet 'cheval de Troie' est le mécanisme par lequel les microplastiques servent de vecteur pour transporter des contaminants chimiques (sorbed chemicals) dans les organismes aquatiques. Mécanisme : les microplastiques (PP, PE, PS) adsorbent les contaminants organiques lipophiles (PCB, HAP, pesticides, perturbateurs endocriniens) sur leurs surfaces hydrophobes. Kplastic/eau = très élevé pour les POPs hydrophobes. Les organismes ingèrent les microplastiques (ingestion sélective ou accidentelle) → les contaminants se désorption en milieu digestif (intestin = milieu plus acide et liposoluble) → absorption des contaminants. Les contaminants co-adsorbés sur un seul microplastique représentent une dose localisée beaucoup plus élevée que la concentration dans l'eau. Effets prouvés chez le poisson (augmentation des contaminants dans le foie) et les invertébrés marins. Reste discuté pour l'importance relative vs l'ingestion directe via la chaîne alimentaire." },
      { id: 8, enonce: "Citez les techniques analytiques pour détecter les PFAS dans les eaux naturelles à des concentrations de l'ordre du ng/L.", correction: "1. LC-MS/MS (Liquid Chromatography - Tandem Mass Spectrometry) : technique de référence. Résolution des > 40 PFAS en une seule injection. LQ = 0,1-1 ng/L selon le PFAS et la matrice. Colonne C18 en mode gradient. Mode MRM (Multiple Reaction Monitoring) pour sélectivité et sensibilité. 2. HRMS (High Resolution Mass Spectrometry, type Orbitrap ou QTOF) : détection 'untargeted' de tous les PFAS, même inconnus. LQ = 1-10 ng/L (moins sensible). 3. Concentration préalable : SPE (Solid Phase Extraction) sur cartouche WAX ou C18 (facteur de concentration ×1000-100 000) → LQ descend à 0,001-0,01 ng/L. Préparation : verre uniquement (pas de plastique fluoré), élimination des interférences de matrices. Standard interne : composés ¹³C-marqués (13C8-PFOS, 13C8-PFOA). Méthode normée : NF EN ISO 21675, EN 17892." }
    ],
    flashcards: [
      { question: "PFAS : propriétés et enjeux", reponse: "Per and PolyFluoroAlkyl Substances (> 4700 composés). Liaisons C-F = 544 kJ/mol → indestructibles (forever chemicals). Propriétés : hydro- et oléofuges, résistance thermique et chimique. Sources : AFFF (mousses anti-incendie), Teflon, Gore-tex, emballages. PFOS et PFOA les plus étudiés, inscrits à la Convention de Stockholm. Bioaccumulation protéique (albumine, acides biliaires, non lipidique). NQE eau potable EU : somme 20 PFAS < 100 ng/L. Traitement : nanofiltration, charbon actif, osmose inverse." },
      { question: "Perturbateurs endocriniens : EE2 et effets poissons", reponse: "EE2 (17α-éthinylestradiol) : hormone de synthèse des pilules contraceptives. Concentration rivières FR : 0,1-5 ng/L (aval STEP). NQE-MA = 0,035 ng/L (DCE). Effet : féminisation des poissons mâles à 1 ng/L (vitellogenine, intersex). Mécanisme : fixation sur récepteurs aux œstrogènes (ER-alpha) → activation de gènes. Lake Experiment (Science 2007) : 5 ng/L EE2 → effondrement population en 3 ans. Élimination : ozonation (> 95%), GAC (> 90%). STEP classique : 60-80% (insuffisant). Substances similaires : E2 (estradiol naturel), bisphénol A, nonylphénol." },
      { question: "Résistance antimicrobiens et milieux aquatiques", reponse: "ARG (Antibiotic Resistance Genes) : présents naturellement + amplifiés par rejets d'eaux usées. STEP = réservoir et amplificateur de RAM. Mécanismes : conjugaison (plasmides), transduction (phages), transformation. Hot spots : biofilms de sédiments, eaux usées hospitalières. Rivières aval STEP : BLSE (Enterobacteries), VRE (entérocoques), ARG résistance bêta-lactamines. Voies humaines : baignade, irrigation légumes, aquaculture. One Health : lien santé humaine-animale-environnement. Surveillance : qPCR des ARG (blaTEM, sul1, tet, intI1 comme proxy de mobilisation)." },
      { question: "Microplastiques : sources et impacts", reponse: "Sources primaires : granulés pré-production (nurdles), microbeads cosmétiques (interdites FR 2018, EU 2023). Sources secondaires : fibres textiles (lavage > 700 000 fibres/lavage), usure pneumatiques (source principale en masse en zones urbaines), fragmentation UV de macroplastiques. Concentrations : rivières 1-100 particules/L. Effets : blocage digestif, effet cheval de Troie (vecteur de POPs). Nanoplastiques (< 1 μm) : plus toxiques, moins analysés. Élimination en STEP : 70-90% (mais effluents concentrent fibres). Analyses : FTIR, Raman (identification polymère), µFTIR (mapping)." }
    ]
  }

,

  'MASTER-EAU-076': {
    id: 'MASTER-EAU-076',
    titre: 'Particules, colloïdes et microplastiques',
    fiche: {
      intro: "Les particules (> 1 μm), colloïdes (1 nm - 1 μm) et matières en suspension (MES) jouent un rôle majeur dans le transport des contaminants et dans les processus de coagulation-floculation en traitement des eaux. La compréhension de leur stabilité colloïdale (théorie DLVO) et de leur comportement en milieu naturel est fondamentale pour concevoir des traitements physico-chimiques efficaces.",
      sections: [
        { titre: "Particules et colloïdes en milieu aquatique", sous_sections: [
          { titre: "Classification et origine des particules", contenu: "Les particules et colloïdes en milieu aquatique se classent par taille : ions (< 0,001 μm), colloïdes (0,001-1 μm), particules fines (1-10 μm), particules grossières (> 10 μm). En milieu naturel : minéraux argileux (montmorillonite, illite : 0,1-2 μm), oxydes de Fe/Mn (ferrihydrite, goethite : 1-100 nm), matière organique colloïdale (acides humiques : 1-100 nm), virus (0,02-0,2 μm), bactéries (1-10 μm). Les colloïdes naturels ont des surfaces fortement chargées (charge négative à pH > 4) → stabilité colloïdale → pas de sédimentation sans traitement. La turbidité (NTU) mesure la diffusion de la lumière par les particules. 1 NTU ≈ 1 mg MES/L environ (relation empirique et dépendante de la nature des particules). Norme eau potable : turbidité < 1 NTU en distribution (< 0,5 NTU recommandé)." },
          { titre: "Théorie DLVO et stabilité colloïdale", contenu: "La théorie DLVO (Derjaguin, Landau, Verwey, Overbeek, 1941-1948) décrit la stabilité d'une suspension colloïdale par la somme de deux forces : forces de répulsion électrostatique V_R (doubles couches électriques des surfaces chargées) et forces d'attraction de Van der Waals V_A. V_total = V_R + V_A. Si la barrière d'énergie est élevée (forte répulsion) → suspension stable (colloïdes dispersés). La répulsion DLVO dépend de la charge de surface (potentiel ζ, zêta) et de la force ionique (I). Augmentation de I → compression de la double couche → réduction de V_R → déstabilisation → floculation (coagulation par compression de la double couche). C'est le mécanisme de la floculation naturelle en estuaire (eau douce + eau salée → floculation des argiles). Zêta potentiel ζ = 0 au point isoélectrique (PIE) → minimum de stabilité → maximum de coagulabilité." }
        ]},
        { titre: "Coagulation-floculation en traitement des eaux", sous_sections: [
          { titre: "Mécanismes de coagulation", contenu: "La coagulation est l'étape clé du traitement physique des eaux. Les mécanismes sont : 1. Double couche électrique : Al³⁺, Fe³⁺ (coagulants) neutralisent les charges négatives → compression de la double couche (ζ → 0) → floculation. 2. Adsorption et neutralisation de charge : polyhydroxo-Al ou -Fe chargés positivement s'adsorbent sur les colloïdes anioniques → neutralisation. 3. Pontage par polymères (floculants organiques : polyacrylamide, polyDADMAC) : longues chaînes reliant plusieurs colloïdes. 4. Entraînement (sweep flocculation) : précipitation massive de Al(OH)₃ ou Fe(OH)₃ amorphe → emprisonnement des colloïdes. Les coagulants usuels : sulfate d'aluminium Al₂(SO₄)₃, chlorure ferrique FeCl₃, chlorosulfate ferrique. Réactions : Al³⁺ + 3H₂O → Al(OH)₃↓ + 3H⁺ (consomme de l'alcalinité, baisse le pH)." },
          { titre: "Essais Jar-Test et paramètres de coagulation", contenu: "Le Jar-Test est l'essai de laboratoire standard pour optimiser la coagulation : 6 béchers de 1 L avec agitation rapide (G > 500 s⁻¹, 1 min), doses croissantes de coagulant → agitation lente (G ≈ 20 s⁻¹, 15 min de floculation) → décantation 15-30 min → mesure de la turbidité résiduelle et du pH. La dose optimale de coagulant minimise la turbidité résiduelle. Elle dépend de : pH (zone optimale de coagulation au fer : pH 6-8, à l'alun : pH 6-7,5), température (eau froide → floculation plus difficile), turbidité initiale (eau très turbide : dose plus élevée), nature des colloïdes. L'aide à la floculation (floculant : polymère organique 0,1-1 mg/L) améliore la cohésion des flocs. La vitamine de la coagulation : le dosage optimal est celui qui amène ζ ≈ 0 (Jar-Test + mesure du zêta potentiel)." }
        ]},
        { titre: "MES et turbidité dans les milieux naturels", sous_sections: [
          { titre: "Transport des sédiments en suspension", contenu: "Le transport des sédiments en suspension dans les rivières suit la loi de Rouse : vitesse de chute ws des particules vs vitesse de frottement u* et turbulence. Pour des particules fines < 20 μm (argiles) : ws < 0,1 mm/s → transport en suspension quasi permanente (lavage load). Pour des sables (200 μm-2 mm) : transport en suspension intermittent + charriage. La concentration en MES dans les rivières varie de 1 mg/L (eaux claires de montagne) à 10 000 mg/L (crues torrentielles). Les MES transportent les contaminants hydrophobes (métaux, pesticides adsorbés) → surveillance des MES par des préleveurs automatiques lors des crues. Le flux de MES annuel d'un bassin versant agricole : 1-100 tonnes/ha/an selon la pente, les pratiques culturales et les précipitations." },
          { titre: "Impact des MES sur les écosystèmes aquatiques", contenu: "Les matières en suspension (MES) et la turbidité affectent les écosystèmes aquatiques de plusieurs façons : 1. Réduction de la lumière (atténuation du rayonnement photosynthétiquement actif, PAR) → réduction de la production primaire, dégradation des herbiers aquatiques. 2. Colmatage des substrats : dépôt des sédiments fins dans les gravières (interstitiel du lit) → asphyxie des œufs de salmonidés, réduction des échanges hyporhéiques. 3. Irritation des branchies : MES > 25 mg/L → stress respiratoire chez les poissons. 4. Transport des contaminants et dépôt dans les zones de sédimentation (retenues, zones lentiques). La DCE utilise les macroinvertébrés (IBD, IBG-DCE) et le phytobenthos (IPS, IBD) comme indicateurs biologiques du bon état : ces bioindicateurs reflètent entre autres l'impact de la turbidité et du colmatage." }
        ]},
        { titre: "Microplastiques dans les milieux aquatiques", sous_sections: [
          { titre: "Méthodes de prélèvement et d'analyse des microplastiques", contenu: "Le prélèvement des microplastiques dans les eaux : filet manta (maille 300-330 μm) pour les eaux de surface, pompe + filtre (20-200 μm) pour les concentrations faibles, sédiment carotteur pour les sédiments. La préparation des échantillons : digestion de la matière organique (H₂O₂ à 35%, 50°C, 24h) ou digestion enzymatique (protéinase K) pour libérer les MP des matrices biologiques. Identification des polymères : μ-FTIR (Micro-Fourier Transform InfraRed, identification par comparaison spectrale à la bibliothèque) ou Raman microspectroscopie (mieux pour les particules < 20 μm). Comptage automatisé par analyse d'image. Les analyses des MP sont encore peu standardisées (manque de méthodes ISO normées) → difficultés de comparaison inter-laboratoires." },
          { titre: "Élimination des microplastiques en traitement des eaux", contenu: "Les stations d'épuration (STEP) éliminent 70-99% des microplastiques dans leur traitement, mais elles concentrent les MP dans les boues (> 10 000 particules/g de boues sèches). Les MP qui passent les STEP sont les plus petits (< 20 μm, fibres textiles). Les procédés d'élimination des MP en AEP : coagulation-floculation-décantation (élimine > 80% des MP > 1 μm), filtration rapide sur sable (80-90%), filtration sur membranes (MF, UF : élimination quasi-totale > 1 μm). Les fibres textiles (< 10 μm) sont difficiles à éliminer. Les eaux potables contiennent encore quelques MP : 0-10 particules/L en France selon les études récentes (10-20 particules/L en eau du robinet selon certaines études). L'impact sanitaire des MP dans l'eau potable reste mal connu mais est l'objet d'une réglementation imminente en EU." }
        ]}
      ],
      points: ["DLVO : stabilité colloïdale = V_R (répulsion) + V_A (Van der Waals).", "ζ = 0 (point isoélectrique) → minimum de stabilité → floculation optimale.", "Coagulation au fer : Al₂(SO₄)₃ → Al(OH)₃↓, pH optimal 6-7,5.", "Turbidité eau potable : < 1 NTU en distribution.", "MES > 25 mg/L : stress respiratoire des poissons (irritation branchiale).", "STEP : 70-99% d'élimination des MP mais concentration dans les boues.", "Coagulation-floculation élimine > 80% des MP > 1 μm.", "Transport fin (lavage load) : particules < 20 μm, ws < 0,1 mm/s.", "μFTIR et Raman : identification des polymères de MP.", "Colmatage des gravières : dépôt de fines → asphyxie des œufs de saumons."],
      formules: [
        { nom: "Potentiel DLVO total", expression: "V_T = V_R + V_A", variables: "V_R = répulsion électrostatique (double couche). V_A = attraction Van der Waals. V_T > 0 → stable. V_T < 0 → coagulation" },
        { nom: "Loi de Stokes (vitesse de chute)", expression: "ws = (ρ_p - ρ_eau) × g × d² / (18 × μ)", variables: "ρ_p = densité particule, d = diamètre, μ = viscosité dynamique. ws (m/s)" },
        { nom: "Équation de Carman-Kozeny (filtration)", expression: "ΔP/L = 180 × μ × v / (dp² × (1-ε)² / ε³)", variables: "ΔP = perte de charge (Pa), L = épaisseur filtre (m), v = vitesse filtration, dp = diamètre grain, ε = porosité" },
        { nom: "Nombre de Camp (énergie de brassage)", expression: "G = √(P / (μ × V))",  variables: "G = gradient de vitesse (s⁻¹). P = puissance dissipée (W). V = volume du bassin (m³). Coagulation : G = 500-1000 s⁻¹. Floculation : G = 20-100 s⁻¹" },
        { nom: "Camp × Stein (Gt)", expression: "Gt = G × t",  variables: "G = gradient de vitesse (s⁻¹), t = temps de séjour (s). Floculation optimale : Gt = 10⁴ à 10⁵" }
      ],
      retenir: "La stabilité colloïdale est décrite par la théorie DLVO (répulsion électrostatique vs Van der Waals). La coagulation-floculation (Al³⁺, Fe³⁺) neutralise les charges de surface → floulation. Le Jar-Test optimise les doses. Les MES transportent les contaminants et perturbent les écosystèmes. Les MP sont analysés par μFTIR, largement éliminés en AEP par coagulation-filtration mais concentrés dans les boues de STEP."
    },
    exercices: [
      { id: 1, enonce: "Vitesse de chute d'une particule argileuse : diamètre = 2 μm, ρ = 2600 kg/m³, μ = 0,001 Pa·s. Calculez ws.", correction: "ws = (ρ_p - ρ_eau) × g × d² / (18μ) = (2600-1000) × 9,81 × (2×10⁻⁶)² / (18 × 0,001) = 1600 × 9,81 × 4×10⁻¹² / 0,018 = 62 784 × 10⁻¹² / 0,018 = 3,49 × 10⁻⁶ m/s = 3,49 μm/s = 0,30 m/jour. Une particule argileuse de 2 μm met 1000/0,30 = 3300 jours pour sédimenter de 1 m de hauteur. Sans coagulation, les argiles ne sédimentent jamais en temps utile → nécessité absolue de la coagulation-floculation pour le traitement des eaux turbides." },
      { id: 2, enonce: "Jar-Test : dose optimale d'alun = 20 mg/L. Turbidité entrée = 15 NTU, sortie = 0,3 NTU. pH entrée = 7,5, pH sortie = 6,8. Qu'est-ce que la baisse de pH indique ?", correction: "La réaction de coagulation de l'alun : Al₂(SO₄)₃ + 6H₂O → 2Al(OH)₃↓ + 3H₂SO₄. Chaque mole d'alun produit 3 moles d'acide sulfurique (6 mol H⁺). La baisse de pH de 7,5 à 6,8 (ΔpH = 0,7) est normale et attendue : elle indique la consommation d'alcalinité (HCO₃⁻ + H⁺ → CO₂ + H₂O). Si l'alcalinité est insuffisante (< 2-3 mmol/L), le pH peut chuter en dessous de 6 → coagulation sous-optimale (Al soluble en pH acide). Correction : ajout de chaux (Ca(OH)₂) ou soude (NaOH) pour maintenir le pH de coagulation optimal (6-7,5 pour l'alun)." },
      { id: 3, enonce: "Expliquez pourquoi la floculation des argiles en suspension est naturellement plus rapide en eau de mer qu'en eau douce.", correction: "En eau douce : I (force ionique) faible ≈ 0,001-0,01 mol/L → double couche électrique épaisse (épaisseur 1/κ ≈ 10-30 nm) → forte répulsion DLVO → suspension stable (argiles dispersées). En eau de mer : I ≈ 0,7 mol/L → double couche très comprimée (1/κ ≈ 0,3 nm) → V_R ≈ 0 → attraction Van der Waals domine → floculation spontanée. C'est le mécanisme de la turbidité maximale estuarienne : à l'interface eau douce-eau salée (zone de mélange), les argiles en suspension dans l'eau douce floculent en rencontrant l'eau salée → zone d'accumulation de sédiments fins dans les estuaires. Ce phénomène a des implications pour la bathymétrie des ports et des chenaux navigables (dragage nécessaire)." },
      { id: 4, enonce: "Citez 4 facteurs qui influencent l'efficacité de la coagulation en traitement des eaux.", correction: "1. pH : zone optimale pH 6-7,5 pour Al³⁺, pH 5-8 pour Fe³⁺. Hors de cette zone, le métal reste soluble (Al³⁺ à pH < 5, Al(OH)₄⁻ à pH > 8). 2. Température : eau froide < 5°C → floculation lente, flocs fragiles (viscosité élevée → choc entre particules réduit). Nécessite une dose plus élevée ou un aide-floculant. 3. Turbidité initiale : eau très turbide → flocs se forment vite (nombre élevé de chocs). Eau très claire (peu turbide) → difficile à clarifier (peu de chocs). Coagulation-assistée (ballasted flocculation) utile pour eaux claires. 4. Nature des colloïdes : matière organique naturelle (DOC, NOM) → consomme le coagulant (réaction avec les acides humiques) → doses plus élevées. DOC peut aussi former des complexes Al-humiques non précipitants → inefficacité." },
      { id: 5, enonce: "Quels sont les risques liés aux boues de STEP contenant des microplastiques lorsqu'elles sont épandues sur les sols agricoles ?", correction: "Les boues de STEP contiennent > 10 000 particules MP/g de matière sèche (fibres, fragments). L'épandage agricole est une voie majeure d'introduction des MP dans les sols (> 60% des boues en France sont épandues). Risques : 1. Accumulation progressive dans les sols (peu de dégradation, durée de vie décennale). 2. Risque d'ingestion par les lombrics et les invertébrés du sol → perturbation des écosystèmes terrestres. 3. Lessivage des MP et des contaminants chimiques adsorbés (métaux, perturbateurs endocriniens, pesticides) vers les eaux souterraines. 4. Contamination des cultures (racines ou absorption foliaire peu probable à ce stade). 5. Risque pour la faune sauvage (oiseaux) consommant des invertébrés du sol contaminé. Réglementation actuelle : aucune limite en France/EU sur les MP dans les boues (en attente de méthodes analytiques standardisées)." },
      { id: 6, enonce: "Calculez Gt pour une unité de floculation : G = 30 s⁻¹, t = 20 min. Est-ce dans la plage optimale ?", correction: "Gt = G × t = 30 × (20 × 60) = 30 × 1200 = 36 000. Plage optimale de floculation : Gt = 10⁴ à 10⁵. 36 000 est dans la plage 10⁴-10⁵ ✓. Ce Gt correspond à une floculation lente typique permettant la formation de flocs robustes. Si G était trop élevé (G > 100 s⁻¹) : cisaillement → fragmentation des flocs. Si trop faible (G < 10 s⁻¹) : peu de collisions → floculation incomplète. Le gradient décroissant (G fort au début → G faible à la fin) est optimal : il permet d'abord d'agglomérer les petites particules puis de laisser croître les flocs sans les briser." },
      { id: 7, enonce: "Qu'est-ce que la turbidité maximale estuarienne et comment affecte-t-elle les dragages ?", correction: "La zone de turbidité maximale (ZTM) est une zone d'accumulation de sédiments fins dans les estuaires à la rencontre des eaux douces et salées. Mécanisme : les argiles en suspension dans les rivières (eau douce, faible I) floculent en rencontrant la zone de salinité (I augmente → compression de la double couche → floculation DLVO). Les flocs sédimentent dans la ZTM. La ZTM migre amont-aval selon les débits (en crue → ZTM descend vers l'aval). Concentrations MES dans les ZTM : 1-100 g/L (jusqu'à 1000 g/L dans les crèmes de vase). Les ZTM estuariennes sont des zones de dépôt actif → envasement rapide des chenaux navigables (ports de Bordeaux, Nantes, Rouen). Dragage nécessaire (1-10 Mm³/an par grand port). La vase déposée est souvent contaminée (métaux, PCB) → gestion délicate des sédiments de dragage (clapage en mer, confinement terrestre)." },
      { id: 8, enonce: "Citez les mécanismes de coagulation de l'alun (Al₂(SO₄)₃) dans l'ordre d'importance décroissante pour une eau de rivière turbide.", correction: "Pour une eau turbide (MES > 20 mg/L), les mécanismes de coagulation sont par ordre d'importance décroissante : 1. Sweep flocculation (entraînement) : précipitation massive de Al(OH)₃ amorphe → emprisonnement physique des particules dans les flocs d'hydroxyde. Mécanisme dominant pour les fortes doses d'alun (> 15 mg Al/L) et les eaux turbides. 2. Adsorption et neutralisation de charge : polyhydroxo-Al cationiques (Al₁₃O₄(OH)₂₄⁷⁺) s'adsorbent sur les colloïdes anioniques → neutralisation de charge (ζ → 0). 3. Double couche électrique : compression de la double couche par Al³⁺ (charge élevée → efficacité DLVO élevée). 4. Pontage par polymères d'Al : chaînes d'hydroxydes d'Al pontant plusieurs colloïdes. L'importance relative dépend de la dose, du pH et des caractéristiques de l'eau (NOM, pH, alkalinité)." }
    ],
    flashcards: [
      { question: "Théorie DLVO : stabilité colloïdale", reponse: "DLVO = Derjaguin-Landau-Verwey-Overbeek (1941-1948). Énergie d'interaction = V_R (répulsion électrostatique) + V_A (attraction Van der Waals). Épaisseur double couche 1/κ ∝ 1/√I. I faible (eau douce) → double couche épaisse → forte répulsion → stable. I élevée (eau de mer) → double couche comprimée → V_R → 0 → floculation. ζ (zêta potentiel) = mesure indirecte de V_R. ζ > ±30 mV : stable. ζ ≈ 0 : point isoélectrique, stabilité minimale. Application : coagulation en AEP, floculation estuarienne, stabilité des boues." },
      { question: "Jar-Test : principe et paramètres", reponse: "Essai de laboratoire pour optimiser la coagulation. Protocole : 6 béchers × 1 L + agitation rapide (G = 500-1000 s⁻¹, 1 min de coagulation) + doses croissantes de coagulant → agitation lente (G = 20-30 s⁻¹, 15-20 min de floculation) → décantation 30 min → mesure turbidité + pH. La dose optimale minimise la turbidité résiduelle. Facteurs influençant : pH, T, alcalinité, DOC, nature des MES. Zone optimale de pH : Al 6-7,5, Fe 5-8. Floculant organique améliore la cohésion des flocs. G × t (Gt) optimal : 10⁴-10⁵ pour la floculation." },
      { question: "Microplastiques : STEP et impacts", reponse: "STEP : élimination 70-99% des MP. Les MP se concentrent dans les boues (> 10 000 particules/g MS). Voie principale : épandage des boues → contamination des sols agricoles. Fibres textiles (< 20 μm) passent les STEP. AEP : coagulation-filtration (> 80%), UF/MF (quasi-100%). Eau du robinet : 0-10 particules/L (données FR). Analyses : μFTIR (> 20 μm), Raman (< 20 μm). Pas de méthodes ISO standardisées (encore) → comparaison inter-laboratoires difficile. Réglementation EU imminente sur les MP dans l'eau potable (2025-2026 probable)." },
      { question: "MES et turbidité : impacts écologiques", reponse: "MES (Matières En Suspension) : particules inorganiques et organiques > 0,45 μm. Mesure : filtration + pesée (mg/L). Turbidité (NTU) : diffusion lumineuse, proxy des MES. Impacts écologiques : atténuation de la lumière → perte de production primaire + herbiers. Colmatage des gravières → asphyxie des œufs de salmonidés (seuil : < 10% fines pour la reproduction). Stress branchial des poissons (MES > 25 mg/L). Transport des contaminants (métaux, pesticides adsorbés sur MES). DCE : MES et turbidité = condition physico-chimique général pour le bon état écologique." }
    ]
  },

  'MASTER-EAU-077': {
    id: 'MASTER-EAU-077',
    titre: 'Écotoxicologie et évaluation des effets',
    fiche: {
      intro: "L'écotoxicologie évalue les effets des contaminants chimiques sur les organismes aquatiques et les écosystèmes. Elle combine des approches toxicologiques (tests normalisés sur organismes), épidémiologiques (corrélations contaminants-effets in situ) et chimiques (mesure des expositions) pour établir des relations concentration-effet et dériver des critères de qualité environnementale. La DCE impose d'atteindre le bon état chimique et écologique de toutes les masses d'eau d'ici 2027.",
      sections: [
        { titre: "Concepts fondamentaux d'écotoxicologie", sous_sections: [
          { titre: "CL50, NOEC, LOEC et relations dose-réponse", contenu: "La relation dose-réponse est la base de la toxicologie et de l'écotoxicologie. Les paramètres clés : CL50 (Concentration Létale 50%) = concentration qui cause la mort de 50% des individus exposés dans un temps défini (96h pour les poissons, 48h pour les daphnies). CE50 (Concentration Efficace 50%) = concentration qui cause l'effet mesuré sur 50% des individus (immobilisation des daphnies, inhibition de croissance des algues). NOEC (No Observed Effect Concentration) = concentration sans effet observé. LOEC (Lowest Observed Effect Concentration) = plus basse concentration avec effet observé. NOEC < vraie valeur seuil < LOEC. La dose-réponse suit généralement une courbe sigmoïde (log de la concentration vs % d'effet). Le Facteur de Sécurité (AF ou ASF) = rapport entre données toxicologiques et critère de qualité : PNEC = NOEC / AF (AF = 10, 100, ou 1000 selon la quantité de données disponibles)." },
          { titre: "Tests normalisés sur organismes aquatiques", contenu: "Les tests écotoxicologiques normalisés (NF EN ISO) couvrent plusieurs niveaux de la chaîne alimentaire : Algues (Raphidocelis subcapitata = Pseudokirchneriella subcapitata) : inhibition de la croissance (CE50 sur 72h, NF EN ISO 8692). Daphnies (Daphnia magna) : immobilisation aiguë (CL50 48h, NF EN ISO 6341), reproduction chronique (21j, NF EN ISO 10706). Poissons (Danio rerio, truite arc-en-ciel Oncorhynchus mykiss) : CL50 96h (NF EN ISO 7346). Bactéries lumineuses (Aliivibrio fischeri) : inhibition de la bioluminescence (CE50 30 min, NF ISO 11348). Vers (Tubifex, Chironomus) : tests sédiments. Plantes aquatiques (Lemna : lentille d'eau) : inhibition de croissance (NF EN ISO 20079). Ces tests sont utilisés pour évaluer la toxicité des rejets industriels et des eaux usées, et pour dériver les NQE des substances chimiques." }
        ]},
        { titre: "Dérivation des NQE (Normes de Qualité Environnementale)", sous_sections: [
          { titre: "Méthode de dérivation des NQE substances prioritaires", contenu: "La dérivation des NQE substances prioritaires de la DCE (Directive 2013/39/UE, TGD = Technical Guidance Document) suit une méthode hiérarchisée : 1. Collecte des données toxicologiques pour toutes les espèces disponibles (CL50, CE50, NOEC sur algues, daphnies, poissons). 2. Calcul de la HC5 (Hazardous Concentration for 5% of species) à partir de la distribution des NOEC (Species Sensitivity Distribution, SSD). 3. Application d'un facteur d'évaluation (AF) : AF = 2 si SSD robuste (> 10 espèces), AF = 5-50 si moins de données. 4. PNEC = HC5 / AF. 5. NQE = PNEC, corrigée pour la biodisponibilité (métaux : BLM). La Species Sensitivity Distribution (SSD) est un outil probabiliste : elle représente la distribution statistique des seuils d'effet des différentes espèces → la HC5 correspond au 5ème percentile (5% des espèces seraient affectées)." },
          { titre: "Species Sensitivity Distribution (SSD)", contenu: "La SSD (Distribution de Sensibilité des Espèces) est construite en : 1. Collectant les NOEC ou CE50 de N espèces pour un contaminant. 2. Ajustant une distribution statistique log-normale (ou log-logistique) aux données. 3. Lisant la HC5 (5ème percentile = concentration protégeant 95% des espèces). La SSD est robuste si N ≥ 10 espèces représentant différents niveaux trophiques (producteurs, consommateurs primaires et secondaires). Exemple : SSD du cuivre → HC5(Cu) ≈ 1 μg/L en eau très molle (après correction BLM) → NQE-MA Cu ≈ 1 μg/L. Les SSD intègrent les incertitudes via les intervalles de confiance à 95% de la HC5. Les logiciels ETX2.0 (RIVM) et SSD Generator (USEPA) calculent les SSD et HC5." }
        ]},
        { titre: "Bioaccumulation, biomarqueurs et diagnostics in situ", sous_sections: [
          { titre: "Facteurs de bioconcentration et bioaccumulation", contenu: "Le Facteur de Bioconcentration (BCF) mesure l'accumulation d'un contaminant par un organisme aquatique par rapport à l'eau : BCF = C_organisme/C_eau (L/kg ou kg/kg). Le Facteur de Bioaccumulation (BAF) = C_organisme / C_eau intègre l'exposition via l'eau ET l'alimentation (voie alimentaire > voie directe pour les POP très lipophiles). La NQE-biota protège l'humain qui mange des poissons : NQE-b = standard en tissus (muscle de poisson). Exemple : NQE-b mercure = 20 μg Hg/kg poids frais dans le muscle de poisson (Directive 2008/105/CE). Pour une substance très bioaccumulable (BCF > 500) : NQE-b peut être le critère déterminant même si C_eau est basse. Les substances CMR et perturbateurs endocriniens (PCB, Hg, hexachlorobenzène, hexachlorobutadiène) nécessitent une surveillance des poissons et des moules (biosurveillance)." },
          { titre: "Biomarqueurs d'exposition et d'effet", contenu: "Les biomarqueurs sont des mesures biologiques dans les organismes qui indiquent l'exposition ou l'effet d'un contaminant : Biomarqueurs d'exposition : EROD (Ethoxyresorufin-O-deethylase, induction par HAP, PCB, dioxines via récepteur Ah), vitellogenine (VTG, protéine de ponte chez les mâles exposés aux PE œstrogéniques), AChE (activité de l'acetylcholinestérase, inhibée par les organophosphorés et carbamates). Biomarqueurs de dommages : micronoyaux (génotoxicité), 8-hydroxy-déoxyguanosine (oxydation de l'ADN), comet assay (cassures ADN). Ces biomarqueurs sont utilisés en TRIAD approach : intégration des données chimiques (analyse des contaminants), toxicologiques (tests normalisés) et biologiques (biomarqueurs, biocénose) pour évaluer l'impact écologique d'un site." }
        ]},
        { titre: "Réglementation DCE et évaluation du risque chimique", sous_sections: [
          { titre: "Bon état chimique et bon état écologique : articulation", contenu: "La DCE (Directive 2000/60/CE) distingue deux objectifs : bon état chimique = respect des NQE des 45 substances prioritaires (SP) et 8 substances prioritaires dangereuses (SPD) dans les eaux de surface. Bon état écologique = atteinte du 'bon potentiel' pour les EQR (Ecological Quality Ratios) basés sur les communautés biologiques (phytoplancton, macrophytes, diatomées benthiques, macroinvertébrés, poissons). Le mauvais état chimique n'implique pas nécessairement le mauvais état écologique (si les SP présentes ne sont pas biodisponibles ou si l'espèce exposée n'est pas présente). Inversement, le mauvais état écologique peut être dû à des contaminants non listés dans les SP (pollutions locales). La DCE introduit le concept de 'bonne condition de référence' (eau non impactée) comme benchmark pour les EQR biologiques." },
          { titre: "Évaluation du risque écologique : ERA", contenu: "L'Évaluation du Risque Écologique (ERA, Ecological Risk Assessment) est une approche structurée pour évaluer les risques des contaminants sur les écosystèmes : Phase 1 - Formulation du problème : identification des contaminants, des voies d'exposition, des récepteurs à protéger, des endpoints. Phase 2 - Analyse : estimation de l'exposition (PEC, Predicted Environmental Concentration) et de la toxicité (PNEC). Calcul du quotient de risque (RQ) = PEC/PNEC. RQ > 1 → risque inacceptable. Phase 3 - Caractérisation du risque : incertitudes, population d'espèces affectées (% de la SSD dépassant la PEC). L'ERA est requise pour l'autorisation des substances chimiques (REACH, biocides, phytosanitaires) et pour les plans de gestion des sites contaminés." }
        ]}
      ],
      points: ["CL50 : concentration létale 50%. CE50 : concentration efficace 50%.", "PNEC = NOEC / AF ou HC5(SSD) / AF.", "SSD (Species Sensitivity Distribution) : HC5 = 5ème percentile.", "NQE-biota Hg = 20 μg/kg dans le muscle de poisson.", "BCF > 500 → substances bioaccumulables (critère REACH).", "EROD : biomarqueur HAP/PCB/dioxines. VTG : biomarqueur PE œstrogéniques.", "RQ (Risk Quotient) = PEC/PNEC. RQ > 1 → risque inacceptable.", "DCE : bon état chimique (NQE) + bon état écologique (EQR biologiques).", "AChE inhibée par les organophosphorés et carbamates (biomarqueur).", "TRIAD : données chimiques + tests toxicologiques + biocénose in situ."],
      formules: [
        { nom: "PNEC (Predicted No Effect Concentration)", expression: "PNEC = HC5 / AF",  variables: "HC5 = 5ème percentile SSD. AF = 2 si > 10 espèces dans la SSD, jusqu'à 1000 si peu de données" },
        { nom: "Quotient de risque (ERA)", expression: "RQ = PEC / PNEC",  variables: "PEC = Predicted Environmental Concentration (mesurée ou modélisée). RQ > 1 → risque → mesures nécessaires" },
        { nom: "Facteur de Bioconcentration (BCF)", expression: "BCF = C_organisme / C_eau (L/kg)",  variables: "BCF > 500 → potentiellement bioaccumulable (REACH). BCF > 5000 → POP" },
        { nom: "Species Sensitivity Distribution (SSD) log-normale", expression: "logEC50 ~ N(μ, σ²) → HC5 = 10^(μ - 1,645σ)", variables: "μ = moyenne, σ = écart-type des log-NOEC. HC5 = 5ème percentile de la distribution" },
        { nom: "Facteur de Bioaccumulation (BAF)", expression: "BAF = C_organisme / C_eau_totale",  variables: "BAF > BCF car inclut l'exposition alimentaire. Utilisé pour les poissons prédateurs et les POP" }
      ],
      retenir: "La CL50 et la CE50 mesurent la toxicité aiguë, la NOEC la toxicité chronique. Les NQE sont dérivées de la SSD (HC5/AF). Le quotient de risque (PEC/PNEC) évalue l'acceptabilité du risque. Les biomarqueurs (EROD, VTG, AChE) mesurent l'exposition et les effets in situ. La DCE exige le bon état chimique (NQE) et écologique (bioindicateurs). Les substances bioaccumulables (BCF > 500) nécessitent une surveillance du biota."
    },
    exercices: [
      { id: 1, enonce: "CL50 du cuivre sur Daphnia magna = 0,05 mg/L. NOEC reproduction = 0,005 mg/L. Calculez la PNEC avec AF = 100.", correction: "PNEC = NOEC / AF = 0,005 / 100 = 0,00005 mg/L = 0,05 μg/L. Cette PNEC est beaucoup plus restrictive que la CL50 (CL50 = 50 μg/L vs PNEC = 0,05 μg/L, soit un facteur 1000). Cela illustre l'importance de la toxicité chronique : les tests de reproduction sur 21 jours révèlent des effets à des concentrations 10× plus basses que la NOEC aiguë. L'AF = 100 (10 pour l'extrapolation inter-espèces + 10 pour l'extrapolation aigü-chronique) réduit encore d'un facteur 100. Le cuivre NQE-MA réelle (après BLM en eau molle) ≈ 1 μg/L : la PNEC simplifiée (sans BLM) = 0,05 μg/L est plus conservative." },
      { id: 2, enonce: "SSD log-normale du zinc : μ = 1,8, σ = 0,5 (log μg/L). Calculez HC5.", correction: "HC5 = 10^(μ - 1,645 × σ) = 10^(1,8 - 1,645 × 0,5) = 10^(1,8 - 0,8225) = 10^(0,9775) = 9,5 μg/L. Avec AF = 2 (si > 10 espèces dans la SSD) : PNEC = HC5/AF = 9,5/2 = 4,75 μg/L. Cette valeur représente une concentration de Zn protégeant 95% des espèces aquatiques (en eau de référence, sans correction BLM). NQE-MA Zn officielle EU ≈ 7 μg/L en eau très molle → valeur cohérente avec le calcul SSD. L'incertitude de la HC5 est estimée par bootstrap : intervalle de confiance à 95% donne une idée de la robustesse de la SSD." },
      { id: 3, enonce: "Vitellogenine (VTG) est mesurée chez des brèmes (Abramis brama) mâles dans une rivière en aval d'une STEP urbaine : 450 μg/L vs 2 μg/L en amont. Que concluez-vous ?", correction: "La vitellogenine est une phospholipoprotéine normalement produite uniquement par les femelles sous stimulation de l'estradiol (E2). Sa présence chez les mâles (VTG mâle ≈ 2 μg/L en référence, ici 450 μg/L aval) est un biomarqueur d'exposition aux perturbateurs endocriniens œstrogéniques. Rapport aval/amont = 450/2 = ×225. Interprétation : exposition significative aux PE œstrogéniques (EE2, E2, nonylphénol, bisphénol A) venant de la STEP. Ces substances à l'état de ng/L dans la rivière sont suffisantes pour induire la VTG chez les mâles (EE2 : induction à 1 ng/L). Ce résultat justifie une analyse chimique de EE2, E1, E2 dans les eaux de la rivière et une évaluation de la STEP (traitement tertiaire par ozonation ou GAC)." },
      { id: 4, enonce: "Citez 3 avantages de l'approche SSD (Species Sensitivity Distribution) par rapport à l'utilisation de la seule CL50 du poisson le plus sensible pour dériver une NQE.", correction: "1. Représentativité : la SSD utilise des données de N espèces (algues, invertébrés, poissons, bactéries → différents niveaux trophiques), couvrant la diversité écologique de l'écosystème à protéger. La CL50 d'une seule espèce ne représente pas toute la diversité biologique. 2. Probabilisme : la SSD fournit une probabilité de protection (HC5 = 95% des espèces protégées) avec un intervalle de confiance, au lieu d'une valeur fixe avec un AF arbitraire. 3. Transparence et auditabilité : chaque donnée toxicologique est tracée sur la courbe SSD → transparent pour les régulateurs et les industriels. Les AF empiriques (100, 1000) sont souvent jugés trop conservateurs ou insuffisants selon les cas. La SSD justifie statistiquement le niveau de protection." },
      { id: 5, enonce: "PEC d'un insecticide dans un cours d'eau = 0,5 μg/L. PNEC = 0,1 μg/L. Calculez RQ et proposez des mesures de gestion.", correction: "RQ = PEC / PNEC = 0,5 / 0,1 = 5. RQ > 1 (risque inacceptable). RQ = 5 indique que la concentration observée est 5× la concentration sans effet. Selon la SSD, environ 30-40% des espèces aquatiques seraient potentiellement affectées. Mesures de gestion : 1. Réduire l'utilisation de l'insecticide dans le bassin versant (restrictions d'usage, rotations, substitution par des alternatives). 2. Identifier les sources (agricoles → restrictions d'application en périodes de pluie, bandes enherbées, drains végétalisés). 3. Réévaluer l'AMM (autorisation de mise sur le marché) si RQ > 5 de manière répétée. 4. Mettre en place un réseau de surveillance renforcé (biomarqueurs, préleveurs automatiques lors des crues). 5. Plan de gestion des captages si contamination de l'AEP." },
      { id: 6, enonce: "Expliquez la méthode TRIAD pour l'évaluation d'un site de sédiments contaminés.", correction: "L'approche TRIAD évalue le risque écologique d'un site contaminé par 3 lignes de preuves indépendantes : 1. Chimie : analyse des contaminants dans les sédiments (métaux, PCB, HAP, pesticides) → comparaison aux valeurs seuils sédimentaires (NQE-s, SQG). Calcul des HQ (Hazard Quotient) = C_sédiment/NQE_s. 2. Toxicologie : tests de toxicité normalisés sur des organismes exposés aux sédiments du site (Chironomus, Tubifex, Hyalella en contact direct, test éluat 1 dans l'eau de l'élution du sédiment). CL50 et NOEC des tests → comparaison aux sédiments de référence. 3. Biologie : étude des communautés benthiques in situ (macroinvertébrés, indice IBG-DCE, densité, richesse taxonomique) → comparaison à des sites de référence. Les 3 lignes convergent → prise de décision (risque nul si les 3 indiquent absence de risque, risque certain si les 3 sont positives, incertitude si divergence)." },
      { id: 7, enonce: "Qu'est-ce que l'EROD et pourquoi est-il un biomarqueur des contaminants organiques halogénés ?", correction: "EROD (Ethoxyresorufin-O-deethylase) est une enzyme de la famille des cytochromes P450 (CYP1A) inductible par les ligands du récepteur Ah (AhR). Les HAP (benzo[a]pyrène, fluoranthène), PCB coplanaires (PCB 77, 126, 169), dioxines (TCDD) et furanes se lient au récepteur AhR → translocation nucléaire → activation du gène CYP1A → induction de l'EROD. L'activité EROD (en pmol résorufine/min/mg protéines) est mesurée dans le foie des poissons. Élévation de l'EROD × 10-1000 = signal d'exposition à des contaminants organiques halogénés. C'est un biomarqueur de contamination intégratif (mesure l'exposition aux dioxines + PCB + HAP combinés → Toxic Equivalency concept). Utilisé dans le monitoring biologique des sédiments et des poissons des rivières (programme LTER, plans de gestion de captages)." },
      { id: 8, enonce: "NQE-biota du mercure = 20 μg/kg dans le muscle de poisson. BCF(Hg) = 10⁵. Calculez la NQE-eau équivalente.", correction: "NQE-eau = NQE-biota / BCF = 20 μg/kg / 10⁵ L/kg = 2 × 10⁻⁴ μg/L = 0,0002 μg/L = 0,2 ng/L. NQE-eau officielle Hg (Directive 2008/105/CE) = 0,05 μg/L (eaux intérieures). Comparaison : 0,2 ng/L (NQE-biota convertie) << 50 ng/L (NQE-eau officielle). Le critère déterminant est la NQE-biota, pas la NQE-eau : même si l'eau a une concentration < 50 ng/L (conforme NQE-eau), les poissons peuvent accumuler > 20 μg/kg de Hg (non conforme NQE-biota). C'est pourquoi la surveillance du Hg se fait sur les poissons (brochets, perches) et non sur l'eau. Cette logique s'applique à tous les POP très bioaccumulables." }
    ],
    flashcards: [
      { question: "CL50, CE50, NOEC : définitions et usage", reponse: "CL50 : concentration létale 50% de la population testée (aiguë, 48-96h). CE50 : concentration efficace 50% (immobilisation, inhibition croissance). NOEC : concentration sans effet observable (chronique, 21j-28j). LOEC : plus basse concentration avec effet. PNEC = NOEC/AF ou HC5(SSD)/AF. Tests normalisés : algues (72h), Daphnia (48h, 21j), poissons (96h), bactéries (30 min). Plus le NOEC est bas → plus la substance est toxique. L'AF varie de 2 (SSD robuste) à 1000 (peu de données, groupe taxonomique non représenté)." },
      { question: "SSD : construction et HC5", reponse: "Species Sensitivity Distribution : distribution statistique des seuils d'effet de N espèces. Construction : NOEC (ou EC10/CE10) de chaque espèce → rang → ajustement log-normale → HC5 = 5ème percentile = concentration protégeant 95% des espèces. HC5 → PNEC = HC5/AF (AF = 2 si SSD robuste, > 10 espèces). Logiciels : ETX2.0 (RIVM), SSD Generator (USEPA). Avantages sur une seule espèce : représentativité, probabilisme, transparence. NQE-MA des métaux DCE sont dérivées de SSD + BLM pour la biodisponibilité." },
      { question: "Biomarqueurs écotoxicologiques", reponse: "Biomarqueurs d'exposition : EROD (CYP1A : HAP, PCB, dioxines via AhR). Vitellogenine VTG (PE œstrogéniques : EE2, E2, NP, BPA chez les mâles). AChE (inhibée par organophosphorés, carbamates → troubles nerveux). Phytochélatines (métaux en algues). Biomarqueurs de dommages : micronoyaux (génotoxicité). Comet assay (cassures ADN). Lipoperoxydes (stress oxydant). Usage : surveillance biologique des masses d'eau (programme LTER, biosurveillance DCE), évaluation sites contaminés (TRIAD approach)." },
      { question: "ERA (Ecological Risk Assessment) : étapes", reponse: "Phase 1 : Formulation du problème → contaminants, récepteurs (espèces à protéger), endpoints (CL50, reproduction), voies d'exposition. Phase 2 : Analyse → PEC (mesurée ou modèle FOCUS) + PNEC (SSD, littérature). RQ = PEC/PNEC. Phase 3 : Caractérisation du risque → RQ < 0,1 : pas de risque. RQ 0,1-1 : risque faible. RQ > 1 → mesures requises. Incertitudes : variabilité des PEC, qualité des données toxicologiques, effets mélanges. Utilisé pour : REACH (nouvelles substances), autorisation des pesticides (FOCUS), plans de gestion des sites contaminés." }
    ]
  },

  'MASTER-EAU-078': {
    id: 'MASTER-EAU-078',
    titre: 'Modélisation géochimique et transport réactif',
    fiche: {
      intro: "La modélisation géochimique simule l'évolution de la composition chimique d'une eau en interaction avec des phases minérales et en présence de réactions biologiques. Couplée à la modélisation du transport (hydrodynamique), elle permet de prédire le comportement des contaminants dans les systèmes naturels et les procédés de traitement. Les codes PHREEQC, MINTEQ et les codes de transport réactif (HYDRUS, FEFLOW+PHT3D) sont les outils de référence.",
      sections: [
        { titre: "Modélisation géochimique spéciative", sous_sections: [
          { titre: "Calcul des espèces chimiques en solution", contenu: "La modélisation spéciative calcule la distribution de toutes les espèces chimiques d'un élément en solution (ions libres, complexes inorganiques et organiques, spéciation redox) à partir de la composition totale mesurée (analyse chimique) et des constantes d'équilibre thermodynamiques. Les logiciels : PHREEQC (USGS, gratuit, le plus utilisé), MINTEQA2 (EPA), VisualMINTEQ (interface MINTEQA2). Données d'entrée : pH, température, concentrations totales de chaque élément. Calcul itératif de Newton-Raphson pour résoudre le système d'équations non-linéaires. Outputs : speciation de chaque élément (% de chaque espèce), indices de saturation (SI = log IAP/K_sp) pour chaque minéral, force ionique, coefficients d'activité (Davies, Pitzer, SIT). SI > 0 → sursaturation → risque de précipitation. SI < 0 → sous-saturation → dissolution." },
          { titre: "Calcul des indices de saturation et des équilibres redox", contenu: "L'indice de saturation (SI) = log (IAP/K_sp) où IAP = produit ionique activité calculé à partir des activités en solution. SI = 0 : équilibre. SI > 0 : sursaturation (précipitation probable). SI < 0 : sous-saturation (dissolution). Exemple PHREEQC pour une eau calcaire : SI(calcite) = log(a_Ca²⁺ × a_CO₃²⁻ / K_sp_calcite). La modélisation des équilibres redox requiert de spécifier le pe ou Eh de la solution. PHREEQC calcule les formes oxydées et réduites de chaque élément selon le pe : Fe²⁺/Fe³⁺, As(III)/As(V), NO₃⁻/NH₄⁺, Cr(III)/Cr(VI), Se(IV)/Se(VI). Les diagrammes Pourbaix (Eh-pH) représentent les domaines de stabilité des espèces redox dans l'espace Eh-pH." }
        ]},
        { titre: "Modélisation des interactions eau-roche", sous_sections: [
          { titre: "Simulation de la dissolution et de la précipitation", contenu: "PHREEQC peut simuler l'évolution de la composition d'une eau lors de son interaction avec un assemblage minéralogique. Modes de simulation : 1. Inverse modeling : calcul des réactions nécessaires pour passer d'une eau de composition C1 à une eau de composition C2 (chemin réactionnel). 2. Forward modeling : simulation de la dissolution de quantités données de minéraux dans une eau initiale. 3. Batch reaction : mélange de plusieurs eaux + réactions d'équilibre. 4. 1D reactive transport : advection + dispersion + réactions dans une colonne (1D). La simulation de la dissolution de la calcite : Ca(HCO₃)₂ → Ca²⁺ + 2HCO₃⁻. PHREEQC calcule les quantités dissoutes à l'équilibre et la pression partielle de CO₂ à l'équilibre. Application : compréhension de la chimie des aquifères karstiques, simulation de l'entartrage des réseaux (préventif dans les procédés de traitement)." },
          { titre: "Échange ionique et adsorption dans PHREEQC", contenu: "PHREEQC implémente des modèles d'échange ionique (échangeurs d'ions : X, formule générique) et de surface complexation (modèles diffuse layer, constant capacitance, triple layer). Le modèle d'échange ionique : Ca-X₂ + 2Na⁺ ⇌ 2Na-X + Ca²⁺ (sélectivité de Gapon ou Gaines-Thomas). Le modèle de surface complexation simule l'adsorption de métaux (Pb²⁺, Cd²⁺, As) sur les surfaces de FeOOH. PHREEQC utilise la base de données MINTEQ.dat pour les constantes de complexation de surface. Ces modèles permettent de simuler : l'évolution de la chimie lors du passage d'une eau par un aquifère argileux (échanges ioniques), l'adsorption de l'As sur les filtres de déférrisation (FeOOH), la mobilité des métaux lors d'une acidification du sol." }
        ]},
        { titre: "Transport réactif 1D et 2D", sous_sections: [
          { titre: "Équation de transport réactif et couplage avec la géochimie", contenu: "L'équation de transport réactif 1D combine l'équation d'advection-dispersion (transport) et les termes sources/puits géochimiques (réactions) : ∂C/∂t = -v × ∂C/∂x + D_L × ∂²C/∂x² + R_géochimique. Le terme R_géochimique comprend : dissolution/précipitation (± qn de minéral dissous/précipité × stoechiométrie), adsorption/désorption (∂q/∂t = k_ads × C × (q_max - q) - k_des × q), réactions biologiques (cinétique de Monod). Les codes de transport réactif 1D incluent : PHREEQC-1D (module TRANSPORT), HYDRUS-1D (non-saturé + géochimie). Pour les simulations 2D/3D : PHT3D (couplage PHREEQC + MT3DMS), FEFLOW+PHREEQC, OpenGeoSys." },
          { titre: "Applications : panaches de contamination et réhabilitation", contenu: "Le transport réactif est appliqué à : 1. Prédiction des panaches de contamination en aquifère : transport de NO₃⁻ avec dénitrification microbienne, transport de métaux lourds avec adsorption et précipitation. 2. Simulation de la réhabilitation d'aquifères contaminés (phytoextraction, barrières réactives perméables). Les Permeable Reactive Barriers (PRB) : murs de ZVI (zero valent iron) ou de calcite injectés dans les aquifères pour précipiter ou réduire les contaminants (Cr(VI) → Cr(III), TCE → éthylène par déhalogénation). PHREEQC simule la réaction ZVI + H₂O + Cr(VI) → Fe(OH)₃ + Cr(III). 3. Simulation des procédés de traitement de l'eau : colonnes d'échange ionique, adsorption sur GAC, réacteurs de décarbonatation. Les codes de transport réactif permettent d'optimiser la conception et de prédire les performances à long terme." }
        ]},
        { titre: "Modélisation inverse et incertitudes", sous_sections: [
          { titre: "Modélisation inverse et reconstruction des chemins réactionnels", contenu: "La modélisation inverse (PHREEQC module INVERSE_MODELING) permet de calculer les réactions géochimiques (minéraux dissous/précipités, échanges, mélange) nécessaires pour expliquer l'évolution entre une eau initiale et une eau finale mesurée. Données : composition chimique de l'eau de recharge et de l'eau de captage (aquifère profond). Hypothèses : minéraux potentiels à considérer (calcite, dolomite, halite, albite, chlorite, échange ionique). PHREEQC recherche les combinaisons de réactions qui satisfont les bilans de masse de chaque élément et les équilibres réacheminés. Résultat : ensemble de solutions non-uniques (toutes les combinaisons réactionnelles compatibles). La modélisation inverse est utilisée en hydrogéochimie pour reconstituer l'histoire chimique des eaux souterraines et comprendre l'altération des roches dans les aquifères." },
          { titre: "Incertitudes des modèles géochimiques", contenu: "Les incertitudes des modèles géochimiques proviennent de : 1. Incertitudes sur les constantes thermodynamiques (K_sp, K_complexation) : souvent 0,5 à 1 unité log → facteur 3-10 sur IAP/K_sp. Les bases de données (minteq.dat, phreeqc.dat, llnl.dat) donnent différentes valeurs → vérifier la cohérence. 2. Incertitudes analytiques sur les concentrations d'entrée : balance ionique > 5% → erreur sur les activités. 3. Hypothèses sur l'état redox (pe imposé vs pe calculé par couples redox). 4. Modèles d'adsorption non uniques (paramètres de surface complexation ajustables). 5. Cinétiques non prises en compte (état d'équilibre supposé). Pour l'analyse des incertitudes : analyse de sensibilité (variation des paramètres d'entrée ±σ), méthode de Monte-Carlo (tirage aléatoire des paramètres dans leurs distributions)." }
        ]}
      ],
      points: ["PHREEQC (USGS) : logiciel de référence pour la modélisation géochimique.", "SI = log(IAP/K_sp). SI > 0 : sursaturation. SI < 0 : sous-saturation.", "Inverse modeling : reconstitue les réactions d'altération entre eau initiale et finale.", "PHT3D : couplage transport MT3DMS + géochimie PHREEQC.", "PRB (Permeable Reactive Barrier) : ZVI, calcite pour décontamination in situ.", "Diagramme Pourbaix (Eh-pH) : stabilité des espèces redox.", "Transport réactif 1D : ∂C/∂t = -v∂C/∂x + D∂²C/∂x² + R_géochimique.", "Monte-Carlo : analyse des incertitudes des modèles géochimiques.", "Modèle surface complexation (FeOOH) : adsorption des anions (As, PO₄).", "Pe et Eh : paramètres redox imposés dans PHREEQC pour les équilibres."],
      formules: [
        { nom: "Indice de saturation (SI)", expression: "SI = log(IAP / K_sp)",  variables: "IAP = produit des activités ioniques. K_sp = solubilité du minéral. SI = 0 : équilibre. SI > 0 : précipitation probable" },
        { nom: "Transport réactif 1D (ADE + réactions)", expression: "∂C/∂t = D_L ∂²C/∂x² - v ∂C/∂x + R_géochimique",  variables: "D_L = coefficient de dispersion longitudinale (m²/s), v = vitesse de pore (m/s), R = terme source/puits" },
        { nom: "Coefficient de dispersion longitudinale", expression: "D_L = α_L × v + D_e",  variables: "α_L = dispersivité longitudinale (m), D_e = coefficient de diffusion effective. D_L augmente avec la vitesse" },
        { nom: "Réaction de dissolution calcite (PHREEQC)", expression: "CaCO₃(s) + CO₂(g) + H₂O ⇌ Ca²⁺ + 2HCO₃⁻",  variables: "K_eq dépend de pCO₂ et T. PHREEQC calcule l'équilibre et la quantité dissoute à l'équilibre" },
        { nom: "Réduction de Cr(VI) par ZVI (PRB)", expression: "CrO₄²⁻ + Fe⁰ + 4H₂O → Cr(OH)₃ + Fe(OH)₃",  variables: "ZVI = Zero Valent Iron (Fe⁰). Cr(VI) → Cr(III) (non toxique, peu mobile). Réaction principale dans les PRB" }
      ],
      retenir: "PHREEQC calcule la spéciation, les indices de saturation et simule les réactions eau-roche. L'inverse modeling reconstitue les chemins réactionnels. PHT3D couple transport et géochimie en 2D/3D. Les barrières réactives perméables (ZVI, calcite) immobilisent les contaminants in situ. Les diagrammes Pourbaix et les calculs PHREEQC sont les outils standard de l'hydrogéochimie et du traitement de l'eau."
    },
    exercices: [
      { id: 1, enonce: "PHREEQC donne SI(calcite) = +0,5 pour une eau de distribution. Que cela signifie-t-il et quelle est la conséquence pratique ?", correction: "SI(calcite) = +0,5 → IAP/K_sp = 10^0,5 = 3,16. L'eau est sursaturée en calcite : elle a une 'capacité tartrisante' → risque de précipitation de CaCO₃ dans les canalisations (entartrage). Cette eau peut corroder les canalisations en acier mais dépôt protecteur de CaCO₃. En traitement AEP, l'objectif est SI(calcite) ≈ 0 à +0,2 (légèrement sursaturé pour protéger les canalisations). Pour corriger : neutralisation à l'acide CO₂ (gaz carbonique → dissolution du calcaire en excès → baisse du SI). Eau distillée : SI = -∞ (très agressive). Eau très minéralisée calcaire : SI = +1 à +2 (très entartrant). La mesure de SI(calcite) remplace l'ancien indice de Langelier (LSI = pH - pH_s)." },
      { id: 2, enonce: "Simulez qualitativement l'évolution d'une eau de pluie (pH 5, Ca = 0,1 mmol/L, Mg = 0,05 mmol/L) traversant 1 m d'aquifère calcaire.", correction: "Eau de pluie : pH 5 → sous-saturée en calcite (SI(calcite) << 0). Traversée de l'aquifère calcaire : CO₂ + H₂O + CaCO₃ → Ca²⁺ + 2HCO₃⁻. Réaction → consommation d'acidité (H⁺), dissolution de CaCO₃ → augmentation de Ca²⁺ et HCO₃⁻. L'eau évolue : pH 5 → pH 7-8 (tampon carbonate), Ca² += 0,1 → 1-3 mmol/L, HCO₃⁻ ≈ 2× Ca²⁺ ajouté ≈ 2-6 mmol/L. SI(calcite) augmente jusqu'à 0 (équilibre). Résultat : eau bicarbonatée calcique (faciès Ca-HCO₃ typique des aquifères crayeux). Minéralisation croissante avec le temps de résidence (chemin de Chebotarev). PHREEQC simule exactement cette évolution en ajoutant progressivement CaCO₃ à l'eau de pluie jusqu'à l'équilibre." },
      { id: 3, enonce: "Expliquez le principe d'une barrière réactive perméable (PRB) au ZVI pour traiter un panache de Cr(VI) en aquifère.", correction: "Principe : une tranchée est excavée perpendiculairement au sens d'écoulement de la nappe, remplie de ZVI (poudre ou copeaux de fer métallique Fe⁰). L'eau contaminée s'écoule naturellement à travers la barrière (PRB = perméable, pas de pompage requis). Réaction : CrO₄²⁻ + Fe⁰ + H₂O → Cr(OH)₃ ↓ + Fe(OH)₃ ↓. Le Cr(VI) est réduit en Cr(III) (beaucoup moins toxique) et précipité sous forme d'hydroxyde de chrome ou incorporé dans la structure de Fe(OH)₃. Les deux précipités s'accumulent dans les pores de la barrière → colmatage progressif (limitation de durée de vie : 10-30 ans). Avantages : traitement passif (pas d'énergie, pas de pompage), coût faible après installation. Inconvénients : entretien, colmatage, non applicable à tous les contaminants. PHREEQC simule la réaction et la précipitation dans la barrière pour prédire la capacité de traitement et la durée de vie." },
      { id: 4, enonce: "Quelle est la différence entre la modélisation directe et inverse dans PHREEQC ?", correction: "Modélisation directe (forward modeling) : on part d'une eau initiale connue et on simule son évolution au contact de minéraux (quantités imposées) et par des réactions. On prédit la composition finale. Usage : simulation d'altération, d'entartrage, de précipitation lors du traitement. Modélisation inverse (inverse modeling) : on part de deux eaux connues (composition C1 en entrée, C2 en sortie) et on calcule les réactions (dissolution/précipitation de minéraux, échanges ioniques, mélange d'eaux) nécessaires pour expliquer le passage de C1 à C2. Résultat : ensemble de solutions réactionnelles compatibles. Usage : hydrogéochimie (reconstituer l'altération des roches dans un aquifère), procédés de traitement (calculer la chimie du décarbonateur), validation de modèles. Différence clé : inverse = rétro-calcul des réactions à partir des compositions mesurées ; forward = prédiction de la composition finale à partir des réactions imposées." },
      { id: 5, enonce: "PHREEQC simule la dissolution de 0,5 mmol/L de pyrite dans une eau aérée (O₂ = 8 mg/L). Décrivez qualitativement les changements de composition attendus.", correction: "Réaction : FeS₂ + 3,75 O₂ + 2,5 H₂O → Fe²⁺ + 2SO₄²⁻ + 4H⁺. 0,5 mmol/L de FeS₂ produit : Fe²⁺ = 0,5 mmol/L, SO₄²⁻ = 1 mmol/L (2×), H⁺ = 2 mmol/L (4×). pH diminue (H⁺ produits) → eaux acides (pH 3-4). Consommation d'O₂ : 0,5 × 3,75 = 1,875 mmol O₂/L = 60 mg O₂/L (> disponible → oxygène limitant). Fe²⁺ produit → oxydation en Fe³⁺ (si O₂ présent) → précipitation Fe(OH)₃ (amorphe) → SI(Fe(OH)₃) > 0 à pH > 3. Résultat final : eau très acide (pH 2-3), riche en SO₄²⁻ et Fe, dépôts rouges de Fe(OH)₃ → signature typique du drainage minier acide. PHREEQC confirme avec SI(ferrihydrite) > 0 et SI(jarosite) > 0 (phases secondaires de Fe)." },
      { id: 6, enonce: "Citez les avantages de la modélisation PHREEQC pour la conception d'une usine de traitement des eaux souterraines.", correction: "1. Prédiction de l'entartrage (SI calcite, aragonite, hydroxyapatite) → dimensionnement du décarbonatateur, dosage du CO₂, type de calcaire à utiliser. 2. Simulation de la précipitation des métaux (Fe²⁺ → Fe³⁺ → Fe(OH)₃) → dimensionnement des filtres à sable ferriques. 3. Évaluation de la déférisation/démanganisation : PHREEQC calcule la quantité d'O₂ nécessaire pour oxyder Fe²⁺ et Mn²⁺. 4. Simulation de la coagulation-floculation (si chimie complexe). 5. Modélisation des colonnes d'échange ionique (échanges Ca/Na, dénitratation). 6. Prédiction de la corrosivité de l'eau traitée (SI calcite, indice de Langelier). 7. Dimensionnement des réactifs (lime, CO₂, HCl) pour ajuster le pH. 8. Simulation de scénarios (variation de la qualité de la ressource en été/hiver) → robustesse du procédé." },
      { id: 7, enonce: "Qu'est-ce qu'un diagramme Pourbaix et comment l'utiliser pour l'arsenic ?", correction: "Un diagramme Pourbaix (ou diagramme Eh-pH) représente les domaines de stabilité thermodynamique des espèces d'un élément dans l'espace Eh (potentiel redox) vs pH. Pour l'arsenic : domaines principaux : As métallique (Eh très bas), AsH₃ (gaz, Eh très négatif), As(III) = H₃AsO₃ (neutre à pH 6-9, conditions réductrices Eh < 0), As(V) = H₃AsO₄/H₂AsO₄⁻/HAsO₄²⁻ (conditions oxydantes Eh > 0). Eau naturelle : Eh 0 à +500 mV, pH 6-8 → As(V) dominant en conditions oxydantes, As(III) en conditions réductrices (eaux souterraines profondes). La frontière As(V)/As(III) est à Eh ≈ +20 mV (pH 7). Usage pratique : prédire la spéciation As en fonction des conditions redox d'un aquifère → guide pour choisir la méthode de déarsénication (oxydation de As(III) → As(V) par aération ou KMnO₄ avant coagulation-adsorption sur FeOOH)." },
      { id: 8, enonce: "PHT3D est utilisé pour simuler la dénitrification naturelle dans un aquifère. Quels paramètres doit-on mesurer sur le terrain ?", correction: "Pour paramétrer le modèle PHT3D de dénitrification naturelle : 1. Hydraulique : conductivité hydraulique K (pompage, diagraphies), gradient hydraulique (piézomètres), porosité effective θ (essai de traçage). 2. Géochimie spatiale : cartes de NO₃⁻, O₂, pH, Eh, Fe²⁺, Mn²⁺ → délimiter les zones oxiques/anoxiques. 3. Cinétique de dénitrification : constante k₁ (dénitratation de 1er ordre) = expériences push-pull in situ, micro-cosmes de sédiments. 4. DOC (carbone organique dissous) : donneur d'électrons pour la dénitrification. 5. Teneur en S réduit (pyrite) : voie de dénitrification autotrophe (NO₃⁻ + pyrite). 6. Profil vertical de NO₃⁻ et ¹⁵N-NO₃⁻ : signature isotopique de la dénitrification (enrichissement en ¹⁵N des NO₃⁻ résiduels). 7. Données d'entrée PHT3D : maille, dispersivité α_L, conditions aux limites (flux entrant NO₃⁻)." }
    ],
    flashcards: [
      { question: "PHREEQC : fonctions principales", reponse: "Logiciel géochimique USGS (gratuit, open-source). Fonctions : spéciation (calcul de toutes les espèces chimiques d'une eau, SI de tous les minéraux). Réactions d'équilibre (dissolution/précipitation/échange ionique/surface complexation). Mélange d'eaux. Évaporation (evaporation progressive). Transport 1D (TRANSPORT : advection + dispersion + réactions). Inverse modeling (INVERSE_MODELING : reconstruction des chemins réactionnels). Bases de données : phreeqc.dat, minteq.dat, llnl.dat, wateq4f.dat. Interface graphique : PHREEQCI, PhreePlot. Compatible HYDRUS, PHT3D, OpenGeoSys." },
      { question: "Indice de saturation (SI) et entartrage", reponse: "SI = log(IAP/K_sp). SI = 0 : équilibre. SI > 0 : sursaturé, risque de précipitation. SI < 0 : sous-saturé, dissolution. Indice de Langelier (LSI) = pH - pHs (ancien équivalent). Eau de distribution : SI(calcite) = 0 à +0,2 (légèrement sursaturée → protège les canalisations par dépôt CaCO₃). SI trop élevé (> +1) → entartrage fort (réseaux, échangeurs). SI < 0 (eau agressive) → corrosion des canalisations acier et cuivre. Traitement : injection CO₂ (abaisse SI), recarbonation, ajout Ca(OH)₂ (augmente SI)." },
      { question: "Transport réactif : équation et codes", reponse: "∂C/∂t = D_L ∂²C/∂x² - v ∂C/∂x + R_géochimique. Codes 1D : PHREEQC-TRANSPORT, HYDRUS-1D (non saturé + géochimie). Codes 2D/3D : PHT3D (MT3DMS + PHREEQC), FEFLOW+PHREEQC, OpenGeoSys, TOUGHREACT. Applications : panaches de contamination (NO₃⁻, métaux, contaminants organiques), rétention des contaminants par adsorption, simulation des PRB. Dispersivité α_L : paramètre clé à mesurer (essai de traçage). D_L = α_L × v. Facteur de retard R = 1 + ρb/θ × Kd." },
      { question: "Barrières réactives perméables (PRB)", reponse: "Tranchées remplis de matériaux réactifs pour traiter les eaux souterraines contaminées in situ (sans pompage). Matériaux : ZVI (Zero Valent Iron) pour Cr(VI), TCE, As. Calcite pour pH et métaux. Compost/bois pour la dénitrification. Zéolithes pour l'ammonium. Mécanisme ZVI : Fe⁰ + polluant oxydé → Fe oxydé + polluant réduit/précipité. Réaction Cr(VI) : CrO₄²⁻ + Fe⁰ → Cr(OH)₃↓ + Fe(OH)₃↓. Durée de vie : 10-30 ans (colmatage progressif par précipités). Avantage : passif (pas d'énergie). Simulation PHREEQC/PHT3D : prédiction de la durée de vie et des performances." }
    ]
  }

};
